import { INTERACTIONS_SETTINGS_DEFAULTS } from "@/components/settings/interactionsSettingsSchema"

/** Overlay saved actions while retaining add-on fields and opaque sibling values. */
function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v)
}

export function mergeInteractionValues(live: unknown): Record<string, unknown> {
  const defaults = structuredClone(INTERACTIONS_SETTINGS_DEFAULTS) as Record<
    string,
    unknown
  >
  if (!isPlainObject(live)) return defaults

  const merge = (
    base: Record<string, unknown>,
    patch: Record<string, unknown>,
  ): Record<string, unknown> => {
    const out: Record<string, unknown> = { ...base }
    for (const [key, value] of Object.entries(patch)) {
      if (isPlainObject(value) && isPlainObject(out[key])) {
        out[key] = merge(out[key] as Record<string, unknown>, value)
      } else {
        out[key] = value
      }
    }
    return out
  }

  const merged = merge(defaults, live)
  if (isPlainObject(merged.map) && isPlainObject(merged.map.afterLoad)) {
    const afterLoad = merged.map.afterLoad
    if (([true, "true", 1, "1"] as unknown[]).includes(afterLoad.loadPost)) afterLoad.loadPost = "auto"
    else if (!afterLoad.loadPost) afterLoad.loadPost = "off"
  }
  return merged
}

