import { Blocks, Cog, Diamond, FileBox, Folder, FolderOpen, Hash, Images } from "lucide-react"
import { isMapInternalNode, type MapSvgNode } from "@/lib/nodes-admin"

/** Shared by the component tree and inspector breadcrumbs. */
export function ComponentTreeIcon({
  kind,
  expanded = true,
}: {
  kind: "app" | "page" | "components" | "gallery-folder" | "gallery"
  expanded?: boolean
}) {
  const Icon = {
    app: Cog,
    page: FileBox,
    components: Blocks,
    "gallery-folder": expanded ? FolderOpen : Folder,
    gallery: Images,
  }[kind]
  return <Icon aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
}

/** Containers use #; Map internals use gray diamonds; independent components use purple. */
export function LayerTypeIcon({ node }: { node: MapSvgNode }) {
  if (node.type === "slot" || node.type === "frame" || node.type === "body") {
    return <Hash aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
  }
  if (isMapInternalNode(node)) {
    return <Diamond aria-hidden="true" className="size-3.5 shrink-0 fill-neutral-400/10 text-neutral-400 dark:fill-neutral-500/10 dark:text-neutral-500" />
  }
  return <Diamond aria-hidden="true" className="size-3.5 shrink-0 fill-violet-500/20 text-violet-600" />
}
