import { useEffect, useId, useRef, useState } from "react"
import { toast } from "sonner"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { patchLiveMapOptions, subscribeLiveMapOptions } from "@/lib/live-map-options"
import { subscribeAdminMapInstance } from "@/lib/apply-options-patch"
import { applyRegionSync, captureRegionSyncOwner, isRegionSyncOwnerCurrent, previewRegionSync, type RegionSyncOwner, type RegionSyncPlan } from "@/lib/region-svg-sync"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { previewRegionCleanup, applyRegionCleanup, type RegionCleanupPlan } from "@/lib/region-svg-sync"

export function MapRegionSyncControls({ map }: { map: MapsvgMapInstance | null }) {
  const id = useId()
  const [, setOptionsTick] = useState(0)
  const [owner, setOwner] = useState<RegionSyncOwner | null>(null)
  const ownerRef = useRef<RegionSyncOwner | null>(null)
  const [plan, setPlan] = useState<RegionSyncPlan | RegionCleanupPlan | null>(null)
  const [cleanup, setCleanup] = useState(false)
  const [busy, setBusy] = useState<"preview" | "apply" | null>(null)
  const busyRef = useRef<typeof busy>(null)
  const [error, setError] = useState<string | null>(null)
  const close = () => { ownerRef.current = null; setOwner(null); setPlan(null); setBusy(null); busyRef.current = null; setError(null) }
  useEffect(() => {
    const check = () => { setOptionsTick(tick => tick + 1); if (ownerRef.current && !isRegionSyncOwnerCurrent(ownerRef.current)) close() }
    const offMap = subscribeAdminMapInstance(check), offOptions = subscribeLiveMapOptions(check)
    return () => { ownerRef.current = null; offMap(); offOptions() }
  }, [])
  useEffect(() => { if (ownerRef.current && ownerRef.current.map !== map) close() }, [map])

  const review = async (candidate: RegionSyncOwner, cleaning = false) => {
    if (busyRef.current) return
    busyRef.current = "preview"; setBusy("preview"); setPlan(null); setError(null)
    try {
      const result = await (cleaning ? previewRegionCleanup(candidate) : previewRegionSync(candidate))
      if (ownerRef.current === candidate) setPlan(result)
    } catch (failure) {
      if (ownerRef.current === candidate) setError(failure instanceof Error ? failure.message : "Could not review SVG Regions.")
    } finally { if (ownerRef.current === candidate) { setBusy(null); busyRef.current = null } }
  }
  const open = (cleaning = false) => {
    if (!map || ownerRef.current) return
    try { const candidate = captureRegionSyncOwner(map); ownerRef.current = candidate; setOwner(candidate); setCleanup(cleaning); void review(candidate, cleaning) }
    catch (failure) { setError(failure instanceof Error ? failure.message : "Select a saved draft first.") }
  }
  const apply = async () => {
    const candidate = ownerRef.current
    if (!candidate || !plan || busyRef.current) return
    busyRef.current = "apply"; setBusy("apply"); setError(null)
    try {
      const cleaning = "removals" in plan
      const count = await (cleaning ? applyRegionCleanup(candidate, plan) : applyRegionSync(candidate, plan))
      if (ownerRef.current === candidate) { close(); toast.success(`${count} ${count === 1 ? "Region" : "Regions"} ${cleaning ? "deleted" : "added"}.`) }
    } catch (failure) {
      if (ownerRef.current === candidate) { setPlan(null); setError(failure instanceof Error ? failure.message : "Could not synchronize Regions.") }
    } finally { if (ownerRef.current === candidate) { setBusy(null); busyRef.current = null } }
  }
  return <>
    <SettingsControlField id={id} label="Region ID prefix" help="Only SVG shapes whose IDs start with this prefix become Regions. Leave empty to include all eligible shapes.">
      <Input id={id} value={String(map?.options.regionPrefix ?? "")} maxLength={1024} disabled={!map}
        onChange={event => patchLiveMapOptions({ regionPrefix: event.target.value })} />
    </SettingsControlField>
    <div className="flex flex-wrap gap-2">
      <Button type="button" variant="outline" disabled={!map || !map.options.source} onClick={() => open()}>Sync regions from SVG</Button>
      <Button type="button" variant="outline" disabled={!map || !map.options.source} onClick={() => open(true)}>Clean orphan region records</Button>
    </div>
    {!owner && error ? <p role="alert" className="text-xs text-destructive">{error}</p> : null}
    <Dialog open={!!owner} onOpenChange={open => { if (!open && busyRef.current !== "apply") close() }}>
      <DialogContent className="flex max-h-[80vh] min-h-0 flex-col sm:max-w-lg" showCloseButton={false}
        onEscapeKeyDown={event => { if (busy === "apply") event.preventDefault() }}
        onPointerDownOutside={event => event.preventDefault()}>
        <DialogHeader>
          <DialogTitle>{cleanup ? "Clean orphan region records" : "Sync regions from SVG"}</DialogTitle>
          <DialogDescription>{cleanup
            ? `Review orphan records missing from this SVG${plan ? ` in ${plan.collection.title}` : ""}. Confirming permanently deletes the listed records and their Object links. Shared Collections are protected.`
            : plan ? `Add missing SVG Regions to ${plan.collection.title}. Existing records, their values and links are kept.` : "Review missing Region records before adding them to the Page's Regions Collection."}</DialogDescription>
        </DialogHeader>
        {busy === "preview" ? <p className="text-sm text-muted-foreground" role="status">Reading SVG and Region records…</p> : null}
        {plan && "additions" in plan ? <>
          <p className="text-sm">{plan.additions.length} to add · {plan.existing} existing records kept</p>
          {plan.orphaned ? <p className="text-xs text-muted-foreground">{plan.orphaned} existing {plan.orphaned === 1 ? "record is" : "records are"} marked orphaned and will stay unchanged.</p> : null}
          {plan.additions.length ? <div className="min-h-0 overflow-auto rounded-md border [&_[data-slot=table-container]]:overflow-visible">
            <Table><TableHeader><TableRow><TableHead>Region ID</TableHead><TableHead>SVG title</TableHead></TableRow></TableHeader>
              <TableBody>{plan.additions.map(row => <TableRow key={row.id}><TableCell className="break-all">{row.id}</TableCell><TableCell className="break-words">{row.title || "—"}</TableCell></TableRow>)}</TableBody></Table>
          </div> : <p className="text-sm text-muted-foreground">No missing Regions. Nothing needs to be added.</p>}
        </> : null}
        {plan && "removals" in plan ? <>
          <p className="text-sm">{plan.removals.length} to delete · {plan.protected} still present in SVG and kept</p>
          {plan.removals.length ? <div className="min-h-0 overflow-auto rounded-md border [&_[data-slot=table-container]]:overflow-visible">
            <Table><TableHeader><TableRow><TableHead>Region ID</TableHead><TableHead>Stored title</TableHead></TableRow></TableHeader>
              <TableBody>{plan.removals.map(row => <TableRow key={row.id}><TableCell>{row.id}</TableCell><TableCell>{row.title || "—"}</TableCell></TableRow>)}</TableBody>
            </Table>
          </div> : <p className="text-sm">No orphan records to delete.</p>}
        </> : null}
        {error ? <p role="alert" className="text-sm text-destructive">{error}</p> : null}
        <DialogFooter>
          <Button type="button" variant="outline" disabled={busy === "apply"} onClick={close}>Cancel</Button>
          {plan ? <Button type="button" variant={cleanup ? "destructive" : "default"}
            disabled={!!busy || !("removals" in plan ? plan.removals.length : plan.additions.length)} onClick={() => void apply()}>
            {busy === "apply" ? (cleanup ? "Deleting…" : "Adding…") : "removals" in plan
              ? `Delete ${plan.removals.length} orphan ${plan.removals.length === 1 ? "record" : "records"}` : `Add ${plan.additions.length} ${plan.additions.length === 1 ? "Region" : "Regions"}`}</Button>
            : <Button type="button" disabled={!!busy} onClick={() => owner && void review(owner, cleanup)}>Review changes</Button>}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  </>
}
