import { useEffect, useRef, useState } from "react"
import { RefreshCw, Trash2, Upload } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Field, FieldContent, FieldLabel } from "@/components/ui/field"
import { Switch } from "@/components/ui/switch"
import { Table, TableBody, TableCell, TableRow } from "@/components/ui/table"
import { FormBuilderChoice } from "@/components/form-builder/FormBuilderChoice"
import { uploadMarker } from "@/components/form-builder/location-field/adapter"
import { markerOptionPath } from "@/components/form-builder/location-field/value"
import { getAdminParams } from "@/lib/admin-params"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { patchLiveMapOptions, subscribeLiveMapOptions } from "@/lib/live-map-options"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { filterSourceFields } from "../filter-fields/model"
import { loadPostFilterFields } from "../filter-fields/post-filter-fields"
import { readMarkerDataRules, validateMarkerDataRules, type MarkerDataRules } from "../../../../../mapsvg/Marker/dataRules"
import { loadRuleFieldOptions } from "../../../../../mapsvg/Region/dataRuleDomain"
import { DataRuleValue } from "../DataRuleValue"
import { MarkerImagePicker } from "./MarkerImagePicker"

type Repo = { getSchema(): { getFields(): any[]; postType?: string }; getOptionsByField(path: string): Promise<Array<{ label: string; value: string | number }>> }
type Runtime = MapsvgMapInstance & { objectsRepository: Repo }
const read = (map: Runtime) => readMarkerDataRules(map.options, map.objectsRepository?.getSchema()?.getFields() || [])
export function MarkerDataRulesEditor({ map }: { map: MapsvgMapInstance | null }) {
  return map ? <Editor key={map.id} map={map as Runtime} /> : null
}
function Editor({ map }: { map: Runtime }) {
  const [rules, setRules] = useState(() => read(map)), latest = useRef(rules), published = useRef(JSON.stringify(rules))
  const [error, setError] = useState(""), [loading, setLoading] = useState(false), [uploading, setUploading] = useState(false)
  const [manual, setManual] = useState(false), [path, setPath] = useState(rules.field)
  const [catalog, setCatalog] = useState<Array<{ value: string; label: string }>>([])
  const [images, setImages] = useState(() => getAdminParams().markerImages.map(markerOptionPath).filter((image): image is string => !!image))
  const request = useRef(0), uploads = useRef(0)
  const repo = map.objectsRepository
  const normalize = (image: string) => {
    if (/^(?:https?:\/\/|\/)/i.test(image)) return image
    const pluginUrl = getAdminParams().pluginUrl.replace(/\/?$/, "/"), uploaded = image.startsWith("uploads/"), name = image.split("/").pop()
    return images.find(path => path.endsWith(`/${name}`) && path.startsWith(pluginUrl) !== uploaded) || (uploaded ? image : `${pluginUrl}markers/${image}`)
  }
  useEffect(() => {
    const unsubscribe = subscribeLiveMapOptions(() => {
      const next = read(map), serialized = JSON.stringify(next)
      if (serialized !== published.current) {
        request.current++; uploads.current++; published.current = serialized; latest.current = next; setRules(next); setPath(next.field); setError(""); setLoading(false); setUploading(false)
      }
    })
    return () => { unsubscribe(); request.current++; uploads.current++ }
  }, [map])
  useEffect(() => {
    let active = true
    const schema = repo?.getSchema(), fields = schema?.getFields() || []
    const options = filterSourceFields(fields, "objects").map(option => ({ value: option.value.replace(/^Object\./, "object."), label: option.label }))
    setCatalog(options)
    void loadPostFilterFields(fields, "objects", schema?.postType).then(extra => { if (active) setCatalog([...options, ...extra.map(option => ({ value: option.value.replace(/^Object\./, "object."), label: option.label }))]) })
      .catch(() => { if (active) setError("Could not load nested fields. You can enter a field path.") })
    return () => { active = false }
  }, [map, repo])
  const change = (next: MarkerDataRules) => {
    request.current++; uploads.current++; setLoading(false); setUploading(false); latest.current = next; setRules(next)
    const errors = validateMarkerDataRules(next); setError(errors.join(" "))
    if (!errors.length && getAdminMapInstance() === map) { published.current = JSON.stringify(next); patchLiveMapOptions({ markerDataRules: next }) }
  }
  const update = (patch: Partial<MarkerDataRules>) => change({ ...latest.current, ...patch })
  const load = async (field = latest.current.field, reset = false) => {
    if (reset) { update({ field, rows: [] }); setPath(field) }
    const run = ++request.current; setLoading(true); setError("")
    try {
      const options = await loadRuleFieldOptions(repo, field, () => request.current === run && getAdminMapInstance() === map)
      if (request.current !== run || getAdminMapInstance() !== map) return
      const existing = new Map(latest.current.rows.map(row => [row.value, row]))
      const seen = new Set<string>()
      const rows = (options || []).flatMap(option => {
        const value = String(option.value ?? "")
        if (!value || seen.has(value)) return []
        seen.add(value)
        return [{ ...existing.get(value), label: String(option.label ?? value), value, image: existing.get(value)?.image || "" }]
      })
      update({ rows })
    } catch { if (request.current === run) setError("Could not load field values. Please retry.") }
    finally { if (request.current === run) setLoading(false) }
  }
  const upload = async (file?: File) => {
    if (!file || uploading) return
    const run = ++uploads.current; setUploading(true); setError("")
    try {
      const marker = await uploadMarker(file)
      if (uploads.current !== run || getAdminMapInstance() !== map) return
      const image = markerOptionPath(marker)
      if (!image) throw new Error("Upload returned no marker image")
      setImages(current => [...new Set([...current, image])]); update({ defaultImage: image })
    } catch (err) { if (uploads.current === run) setError(err instanceof Error ? err.message : "Marker upload failed.") }
    finally { if (uploads.current === run) setUploading(false) }
  }
  const defaultImage = normalize(rules.defaultImage || "_pin_default.png")
  return <div className="grid min-w-0 gap-4" data-slot="marker-data-rules">
    <Field><FieldContent><FieldLabel>Default marker image</FieldLabel><div className="flex min-w-0 gap-2">
      <MarkerImagePicker label="Default marker image" value={defaultImage} images={images} onChange={defaultImage => update({ defaultImage })} />
      <Button asChild type={undefined} size="sm" variant="outline"><label className={uploading ? "pointer-events-none opacity-50" : "cursor-pointer"}><Upload className="size-3" />{uploading ? "Uploading…" : "Upload"}<input aria-label="Upload marker image" type="file" accept="image/*" className="sr-only" disabled={uploading} onChange={event => { void upload(event.target.files?.[0]); event.currentTarget.value = "" }} /></label></Button>
    </div></FieldContent></Field>
    <Field orientation="horizontal"><FieldLabel>Data rules</FieldLabel><Switch aria-label="Marker images by field" checked={rules.on} onCheckedChange={on => update({ on })} /></Field>
    {rules.on ? <>
      <Field><FieldContent><FieldLabel>Field</FieldLabel><FormBuilderChoice aria-label="Marker rules field" value={rules.field} options={catalog} onValueChange={field => void load(field, true)} /><Button type="button" size="xs" variant="ghost" className="justify-start" onClick={() => setManual(!manual)}>Enter field path</Button>
        {manual ? <Input aria-label="Marker custom field path" placeholder="object.post.meta.myField" value={path} onChange={event => setPath(event.target.value)} onBlur={() => { if (path !== rules.field) void load(path, true) }} onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); event.currentTarget.blur() } }} /> : null}
      </FieldContent></Field>
      <Button type="button" size="xs" variant="outline" disabled={loading} onClick={() => void load()}><RefreshCw className="size-3" />{loading ? "Loading values…" : "Load available values"}</Button>
      <Table aria-label="Marker image rules" className="table-fixed [&_td]:px-1"><colgroup><col /><col className="w-9" /><col className="w-9" /></colgroup><TableBody>
        {rules.rows.map((row, index) => <TableRow className="hover:bg-transparent has-aria-expanded:bg-transparent" key={row.value}>
          <TableCell><DataRuleValue label={row.label} value={row.value} /></TableCell>
          <TableCell><MarkerImagePicker label={`Marker rule ${index + 1} image`} value={row.image ? normalize(row.image) : ""} defaultImage={defaultImage} images={images} onChange={image => update({ rows: latest.current.rows.map((item, i) => i === index ? { ...item, image } : item) })} /></TableCell>
          <TableCell><Button type="button" size="icon" variant="outline" aria-label={`Delete marker rule ${index + 1}`} onClick={() => update({ rows: latest.current.rows.filter((_, i) => i !== index) })}><Trash2 /></Button></TableCell>
        </TableRow>)}
      </TableBody></Table>
    </> : null}
    {error ? <p role="alert" className="text-xs text-destructive">{error}</p> : null}
  </div>
}
