import { createElement } from "react"
import { TypographyThemeStatus } from "../TypographyThemeStatus"
import type { SettingsField, SettingsFormSchema } from '@/lib/settings-form/types'
import { DEFAULT_TYPOGRAPHY } from '../../../../../mapsvg/Core/typography'
export { DEFAULT_TYPOGRAPHY }
const custom = (values: Record<string, any>) => values.typography?.mode === 'custom'
const number = (path: string, label: string, suffix: string, min = 1): SettingsField => ({ type: 'number', path: `typography.${path}`, label, suffix, min, visible: custom, indent: true })
const heading = (tag: 'h1' | 'h2' | 'h3'): SettingsField[] => [
  { type: 'section', id: `typography-${tag}`, label: tag.toUpperCase(), visible: custom },
  number(`${tag}.size`, 'Font size', 'px'),
  { type: 'select', path: `typography.${tag}.weight`, label: 'Font weight', options: [400,500,600,700,800,900].map(value => ({ value: String(value), label: String(value) })), visible: custom, indent: true },
  number(`${tag}.lineHeight`, 'Line height', '%'),
  { type: 'color', path: `typography.${tag}.color`, label: 'Color', placeholder: 'Inherit', visible: custom, indent: true },
]
export const typographySettingsSchema: SettingsFormSchema = { fields: [
  { type: 'section', id: 'typography', label: 'Typography' },
  { type: 'select', path: 'typography.mode', label: 'Typography', help: 'Default: Helvetica · 14px · 150%.', options: [
    { value: 'default', label: 'Default' }, { value: 'theme', label: 'WordPress theme' }, { value: 'custom', label: 'Custom' },
  ] },
  { type: 'custom', id: 'typography-theme-status', visible: (values: Record<string, any>) => ['theme', 'custom'].includes(values.typography?.mode), render: () => createElement(TypographyThemeStatus) },
  { type: 'section', id: 'typography-base', label: 'Base', visible: custom },
  { type: 'text', path: 'typography.base.fontFamily', label: 'Font family', help: 'System fonts or fonts loaded by your WordPress theme.', visible: custom, indent: true },
  number('base.size', 'Font size', 'px'), number('base.lineHeight', 'Line height', '%'),
  { type: 'section', id: 'typography-links', label: 'Links', visible: custom },
  { type: 'color', path: 'typography.links.color', label: 'Color', visible: custom, indent: true },
  { type: 'color', path: 'typography.links.hoverColor', label: 'Hover color', visible: custom, indent: true },
  { type: 'switch', path: 'typography.links.underline', label: 'Underline', visible: custom, indent: true },
  ...heading('h1'), ...heading('h2'), ...heading('h3'),
  { type: 'section', id: 'typography-paragraphs', label: 'Paragraphs', visible: custom },
  number('p.size', 'Font size', 'px'), number('p.lineHeight', 'Line height', '%'), number('p.spacing', 'Paragraph spacing', 'px', 0),
] }
