import { PremiumFeatureButton } from "@/components/PremiumFeaturePlaceholder"
import { hasProductFeature } from "@/lib/product-features"
import { BUILTIN_TEMPLATE_OPTIONS } from "../../../../mapsvg/Map/templatePresets"
import type { SettingsField } from "@/lib/settings-form/types"
import { useCallback, useEffect, useMemo, useState } from "react"
import { SettingsForm } from "@/components/settings-form/SettingsForm"
import { SettingsSection } from "@/components/settings-form/SettingsSection"
import { FieldGroup } from "@/components/ui/field"
import {
  getSchemaForInteractionEvent,
  INTERACTIONS_NAV,
} from "@/components/settings/interactionsNav"
import { mergeInteractionValues } from "@/lib/interaction-values"
import { withoutLayoutPlacementFields } from "@/lib/schema-without-layout-fields"
import { patchLiveMapOptions, subscribeLiveMapOptions } from "@/lib/live-map-options"
import {
  getAdminMapInstance,
  subscribeAdminMapInstance,
} from "@/lib/apply-options-patch"
import type { NodeType } from "@/lib/nodes-admin"
import { interactionGroupForNodeType } from "@/lib/nodes-admin"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

type Props = {
  nodeType: NodeType
}


function interactionGroup(nodeType: NodeType) {
  const groupId = interactionGroupForNodeType(nodeType)
  return INTERACTIONS_NAV.find((item) => item.id === groupId)
}

/**
 * Hidden for now, but kept in the controller toolbar so we can restore
 * single-event navigation later without moving the control again.
 */
export function NodeInteractionsToolbar({ nodeType }: Props) {
  const group = interactionGroup(nodeType)
  const [eventId, setEventId] = useState(group?.events[0]?.id ?? "")

  useEffect(() => {
    const firstEventId = group?.events[0]?.id ?? ""
    if (firstEventId) setEventId(firstEventId)
  }, [group])

  if (!group || group.events.length < 2) return null

  return (
    <div className="hidden">
      <Select value={eventId} onValueChange={setEventId}>
        <SelectTrigger size="sm" className="w-[180px]">
          <SelectValue placeholder="Interaction" />
        </SelectTrigger>
        <SelectContent>
          {group.events.map((event) => (
            <SelectItem key={event.id} value={event.id}>
              {group.label} {event.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  )
}

function templateChoices(field: SettingsField): SettingsField[] {
  if (field.type === "group") return [{ ...field, fields: field.fields.flatMap(templateChoices) } as SettingsField]
  if ("path" in field && field.path === "region.click.loadObjects" && !hasProductFeature("directory")) return [{ ...field, label: "Load linked DB Objects" }]
  if (!("path" in field) || !/Template$/.test(field.path) || !["select", "text"].includes(field.type)) return [field]
  if (hasProductFeature("templates")) return []
  const options = field.type === "select" ? field.options : []
  return [{ ...field, type: "select", options: [
    ...options,
    ...BUILTIN_TEMPLATE_OPTIONS.filter(option => !options.some(existing => existing.value === option.value)),
  ], help: undefined } as SettingsField]
}

/** Interactions tab content for nodes backed by legacy Actions / `actions.*`. */
export function NodeInteractionsPanel({ nodeType }: Props) {
  const group = interactionGroup(nodeType)

  const [values, setValues] = useState<Record<string, unknown>>(() =>
    mergeInteractionValues(getAdminMapInstance()?.options?.actions),
  )

  useEffect(() => {
    const refresh = () => setValues(mergeInteractionValues(getAdminMapInstance()?.options?.actions))
    const unsubscribeMap = subscribeAdminMapInstance(refresh)
    const unsubscribeOptions = subscribeLiveMapOptions(refresh)
    return () => { unsubscribeMap(); unsubscribeOptions() }
  }, [])

  const eventSchemas = useMemo(
    () =>
      (group?.events ?? []).map((event) => ({
        event,
        schema: withoutLayoutPlacementFields(
          { ...getSchemaForInteractionEvent(event.path), fields: getSchemaForInteractionEvent(event.path).fields
            .filter(field => hasProductFeature("show_another_map") || !("path" in field && field.path.includes("showAnotherMap")) && !field.id?.includes("showAnotherMap"))
            .filter(field => hasProductFeature("directory") || !("path" in field && field.path === "region.click.filterDirectory"))
            .flatMap(templateChoices) },
        ),
      })),
    [group],
  )

  const onChange = useCallback((next: Record<string, unknown>) => {
    setValues(next)
    patchLiveMapOptions({ actions: next })
  }, [])

  if (!group) return null

  return (
    <div className="p-3 pb-4">
      <FieldGroup className="gap-4">
        {eventSchemas.map(({ event, schema }) => (
          <SettingsSection key={event.id} title={`${group.label} ${event.label}`}>
            <SettingsForm
              schema={schema}
              values={values}
              onChange={onChange}
              className="p-0"
            />
            {event.path.endsWith(".click") && ["region", "marker", "directoryItem"].includes(event.path.split(".")[0]) && !hasProductFeature("show_another_map") ? <PremiumFeatureButton feature="show_another_map" /> : null}
          </SettingsSection>
        ))}
      </FieldGroup>
    </div>
  )
}
