import { useState } from "react"
import { ComponentController } from "@/components/ComponentController"
import { containerBackground } from "../../../../mapsvg/Layout/ContainerStyles"
import { stackComponentLayout } from "../../../../mapsvg/Layout/StackLayout"
import { LayoutPositionField, LayoutSizeFields } from "./LayoutGeometryFields"
import { gridContainerLayout } from "../../../../mapsvg/Layout/LayoutGridRuntime"
import { readNodes } from "@/lib/nodes-admin"
import { Trash2 } from "lucide-react"
import { SettingsSection } from "@/components/settings-form/SettingsSection"
import { SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { LayoutDisplaySection } from "./LayoutDisplaySection"
import { SettingsChoice } from "@/components/settings-form/SettingsChoice"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { DeleteLayoutNodeDialog } from "@/components/layout/DeleteLayoutNodeDialog"
import { patchLiveMapOptions, useAdminMap } from "@/lib/live-map-options"
import { applyLayoutEdit } from "@/lib/layout-history"
import { readLayoutOptions } from "@/lib/layout-grid"
import { containerSettingsPatch, type ContainerLayout } from "@/lib/layout-containers"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { previewSessionLayoutBreakpoint } from "@/lib/preview-canvas"
import { useLayoutMigration } from "@/components/layout/LayoutMigrationDialog"
import type { MapSvgNode } from "@/lib/nodes-admin"

export function ContainerSettingsBody({ node }: { node: MapSvgNode }) {
  const map = useAdminMap()
  const bp = useWorkspaceStore(state => previewSessionLayoutBreakpoint(map ? state.mapSessions[String(map.id)] : undefined))
  const { requestMigration } = useLayoutMigration()
  const [confirmDelete, setConfirmDelete] = useState(false)
  if (!map) return null
  const values = gridContainerLayout(node, bp, readLayoutOptions(map.options.layout).grids[bp], readNodes(map))
  const frameLayout = stackComponentLayout(node, bp, readNodes(map))
  const change = (patch: ContainerLayout) => requestMigration(() => {
    const next = containerSettingsPatch(map, node.id, bp, patch)
    applyLayoutEdit({ ...next, layout: { ...next.layout, mountMode: "tree" } })
  })
  const size = (axis: "width" | "height") => (
    <SettingsControlField label={axis === "width" ? "Width" : "Height"} help={axis === "height" ? "Auto sizes the row from content. Fill follows the row height and scrolls overflow." : undefined}>
      <SettingsChoice aria-label={`${axis} mode`} value={values[axis === "width" ? "widthPercent" : "heightPercent"] !== undefined ? "legacy-percentage" : values[axis]?.mode ?? (axis === "width" ? "fill" : "auto")} onValueChange={mode => change({ [axis]: { mode, value: values[axis]?.value ?? (axis === "width" ? 250 : 300) } })}
        options={[{ value: "auto", label: "Auto" }, { value: "fill", label: "Fill" }, { value: "fixed", label: "Fixed" }]} />
      {values[axis]?.mode === "fixed" ? <Input aria-label={`${axis} in pixels`} type="number" min={0} value={values[axis]?.value ?? 0}
        onChange={event => change({ [axis]: { mode: "fixed", value: Math.max(0, Number(event.target.value) || 0) } })} /> : null}
    </SettingsControlField>
  )
  const settingsBody = <div className="flex flex-col gap-4" data-slot="container-settings">
      <LayoutDisplaySection map={map} node={node} hideDivider>
        {node.type === "frame" ? <LayoutPositionField values={frameLayout} onChange={change} /> : null}
      </LayoutDisplaySection>
      <SettingsSection title="Size">
        {node.type === "frame" ? <LayoutSizeFields values={frameLayout} onChange={change} /> : <>{size("width")}{size("height")}</>}
      </SettingsSection>
      <SettingsSection title="Spacing">
        {(["padding", "paddingBottom", "gap"] as const).map(key => <SettingsControlField key={key} label={key === "padding" ? "Padding (px)" : key === "paddingBottom" ? "Bottom padding (px)" : "Gap (px)"} id={`container-${key}`}>
          <Input id={`container-${key}`} type="number" min={0} value={values[key] ?? (key === "paddingBottom" ? values.padding : 0) ?? 0} onChange={event => change({ [key]: Math.max(0, Number(event.target.value) || 0) })} />
        </SettingsControlField>)}
        <SettingsControlField label="Alignment">
          <SettingsChoice aria-label="Container alignment" value={values.align ?? "stretch"} onValueChange={align => change({ align: align as ContainerLayout["align"] })}
            options={[{ value: "start", label: "Start" }, { value: "center", label: "Center" }, { value: "end", label: "End" }, { value: "stretch", label: "Stretch" }]} />
        </SettingsControlField>
      </SettingsSection>
      <details className="text-xs"><summary className="cursor-pointer text-muted-foreground">Advanced size</summary>
        <div className="mt-4 grid grid-cols-2 gap-4">
          {(["minWidth", "maxWidth", "minHeight", "maxHeight"] as const).map(key => <SettingsControlField key={key} label={`${key.replace(/([A-Z])/g, " $1")} (px)`} id={`container-${key}`}>
            <Input id={`container-${key}`} type="number" min={0} value={values[key] ?? ""} onChange={event => change({ [key]: event.target.value === "" ? undefined : Math.max(0, Number(event.target.value) || 0) })} />
          </SettingsControlField>)}
        </div>
      </details>
      <SettingsSection title="All layouts" help="Container identity and its components are shared across all layouts.">
        <Button type="button" size="xs" variant="outline" className="self-start text-destructive" onClick={() => setConfirmDelete(true)}><Trash2 />Delete container</Button>
      </SettingsSection>
    </div>
  return <>
    <ComponentController settings={{ schema: { fields: [{ type: "custom", id: "container-settings", render: () => settingsBody }] } }}
      styles={{
        schema: { fields: [{ type: "color", path: "backgroundColor", label: "Background" }] },
        values: { backgroundColor: containerBackground(node, map.options.colors as Record<string, unknown> | undefined) },
        onChange: next => requestMigration(() => {
          const nodes = readNodes(map).map(item => item.id === node.id
            ? { ...item, styles: { ...item.styles, backgroundColor: String(next.backgroundColor ?? "") } } : item)
          const layout = readLayoutOptions(map.options.layout)
          patchLiveMapOptions({ nodes, ...(layout.mountMode !== "tree" ? { layout: { ...layout, mountMode: "tree" } } : {}) })
        }),
      }} />
    <DeleteLayoutNodeDialog map={map} nodeId={node.id} open={confirmDelete} onOpenChange={setConfirmDelete} />
  </>
}
