import { ProductFeatureDialog } from "@/components/PremiumFeaturePlaceholder"
import { hasProductFeature } from "@/lib/product-features"
import { availableFilterFields, mergeLiteFilterFields } from "../../../../../mapsvg/Core/productFeatures"
import { componentBindingRole } from "../../../../../mapsvg/Map/pageBindings"
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { patchLiveMapOptions } from "@/lib/live-map-options"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import { SchemaBuilder, type SchemaBuilderSaveState } from "../../form-builder/schema-builder/SchemaBuilder"
import { OptionsFieldSettings } from "../../form-builder/schema-builder/settings"
import type { SchemaFieldSettingsProps } from "../../form-builder/schema-builder/types"
import { FormBuilderChoice } from "../../form-builder/FormBuilderChoice"
import { Button } from "@/components/ui/button"
import { buildFieldOptionsPatch } from "../../form-builder/schema-builder/model"
import { loadPostFilterFields } from "./post-filter-fields"
import {
  createMapFilterField,
  filterParameterPatch,
  filterSourceFields,
  MAP_FILTER_FIELD_TYPES,
  validateMapFilterFields,
} from "./model"

type FilterRepository = {
  getSchema: () => { getFields: () => FormFieldData[]; postType?: string }
  getOptionsByField?: (field: string) => Promise<Array<{ label: string; value: string }>>
}
export type FilterRuntime = MapsvgMapInstance & {
  filtersSchema?: { getFields: () => FormFieldData[] }
  objectsRepository?: FilterRepository
  regionsRepository?: FilterRepository
}

function ChoiceFilterSettings(props: SchemaFieldSettingsProps) {
  const sourceFields = (props.context?.sourceFields as ReturnType<typeof filterSourceFields>) ?? []
  const repository = props.context?.repository as FilterRepository | undefined
  const settingsField = useMemo(() => ({ ...props.field, renamable: false }), [props.field])
  const parameter = String(props.field.parameterName ?? "")
  const options = sourceFields.map(({ value, label }) => ({ value, label }))
  if (parameter && !options.some((option) => option.value === parameter))
    options.push({ value: parameter, label: parameter })
  const [pending, setPending] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const request = useRef(0)
  useLayoutEffect(() => {
    request.current++
    setPending(false)
    setError(null)
    return () => {
      request.current++
    }
  }, [repository, parameter, props.fieldIndex, props.field])
  return (
    <div
      className="grid gap-4"
      onChangeCapture={() => {
        request.current++
        setPending(false)
      }}
    >
      <FormBuilderChoice
        aria-label="Filter source field"
        value={parameter}
        options={options}
        emptyLabel="Choose source field"
        onValueChange={(next) => {
          const sourceField = sourceFields.find(({ value }) => value === next)?.field
          props.onPatch({
            ...filterParameterPatch(next),
            ...(Array.isArray(sourceField?.options)
              ? buildFieldOptionsPatch(props.field, structuredClone(sourceField.options))
              : {}),
          })
        }}
      />
      {repository?.getOptionsByField && parameter ? (
        <Button
          type="button"
          size="sm"
          variant="outline"
          disabled={pending}
          onClick={async () => {
            setPending(true)
            setError(null)
            const run = ++request.current
            try {
              const values = await repository.getOptionsByField!(
                parameter.split(".").slice(1).join("."),
              )
              if (run === request.current)
                props.onPatch(buildFieldOptionsPatch(props.field, values))
            } catch {
              if (run === request.current) setError("Could not load filter options")
            } finally {
              if (run === request.current) setPending(false)
            }
          }}
        >
          Load source options
        </Button>
      ) : null}
      {error ? <p role="alert">{error}</p> : null}
      <OptionsFieldSettings
        {...props}
        field={settingsField}
        validation={undefined}
        searchable={props.field.type !== "checkboxes"}
        multiselect={props.field.type === "select"}
        placeholderLabel={props.field.type === "select" ? "Placeholder" : props.field.type === "radio" ? "Default option text" : undefined}
      />
    </div>
  )
}

const choiceSettings = {
  select: ChoiceFilterSettings,
  radio: ChoiceFilterSettings,
  checkboxes: ChoiceFilterSettings,
}

type Props = {
  map: MapsvgMapInstance | null
  formId?: string
  showSaveButton?: boolean
  onSaveStateChange?: (state: SchemaBuilderSaveState) => void
  onSaved?: () => void
  isCurrentOwner?: () => boolean
}

export function MapFilterFieldsBuilder({ map, formId, showSaveButton = true, onSaveStateChange, onSaved, isCurrentOwner }: Props) {
  const runtime = map as FilterRuntime | null
  const fullFilters = hasProductFeature("filters")
  const [premiumOpen, setPremiumOpen] = useState(false)
  const [allFields] = useState(
    () =>
      runtime?.filtersSchema?.getFields() ??
      ((Array.isArray(runtime?.options.filtersSchema)
        ? runtime.options.filtersSchema
        : []) as FormFieldData[]),
  )
  const [fields, setFields] = useState(() => availableFilterFields(allFields, fullFilters))
  const source = componentBindingRole(runtime?.options, "filters")
  const repository = source === "regions" ? runtime?.regionsRepository : runtime?.objectsRepository
  const owner = useRef({ runtime, source, repository })
  const [postCatalog, setPostCatalog] = useState<{
    repository: FilterRepository | undefined
    source: string
    fields: ReturnType<typeof filterSourceFields>
    error?: string
  } | null>(null)
  const [retry, setRetry] = useState(0)
  useEffect(() => {
    let current = true
    if (!fullFilters) return
    const schema = repository?.getSchema()
    const fields = schema?.getFields() ?? []
    if (!fields.some((field) => field.type === "post")) return
    void loadPostFilterFields(fields, source, schema?.postType).then(
      (fields) => {
        if (current) setPostCatalog({ repository, source, fields })
      },
      () => {
        if (current)
          setPostCatalog({
            repository,
            source,
            fields: [],
            error: "Could not load post filter fields",
          })
      },
    )
    return () => {
      current = false
    }
  }, [repository, source, retry, fullFilters])
  const settingsContext = useMemo(
    () => ({
      sourceFields: [
        ...filterSourceFields(repository?.getSchema().getFields() ?? [], source),
        ...(postCatalog?.repository === repository && postCatalog?.source === source
          ? (postCatalog?.fields ?? [])
          : []),
      ],
      repository,
    }),
    [repository, source, postCatalog],
  )
  if (!runtime) return <p>Select a map to edit its filter fields.</p>
  return (
    <section className="flex min-h-0 min-w-0 flex-1 flex-col gap-3 overflow-hidden" aria-label="Map filter fields">
      {postCatalog?.repository === repository &&
      postCatalog?.source === source &&
      postCatalog?.error ? (
        <p role="alert">
          {postCatalog.error}{" "}
          <Button size="sm" variant="outline" onClick={() => setRetry((value) => value + 1)}>
            Retry source fields
          </Button>
        </p>
      ) : null}
      <SchemaBuilder
        className="min-w-0 flex-1 grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)] rounded-none border-0 [&>div]:min-w-0"
        fields={fields}
        fieldTypes={fullFilters ? MAP_FILTER_FIELD_TYPES : ["distance", ...MAP_FILTER_FIELD_TYPES.filter(type => type !== "distance")]}
        restrictedFieldTypes={fullFilters ? [] : MAP_FILTER_FIELD_TYPES.filter(type => type !== "distance")}
        onRestrictedFieldTypeSelect={() => setPremiumOpen(true)}
        fieldTypeLabels={{ distance: "Search by address" }}
        createField={createMapFilterField}
        validateFields={validateMapFilterFields}
        enableRecordValidation={false}
        settingsRegistry={choiceSettings}
        settingsContext={settingsContext}
        formId={formId}
        showSaveButton={showSaveButton}
        onSaveStateChange={onSaveStateChange}
        saveButtonLabel="Save"
        onSave={(next) => {
          const liveSource = componentBindingRole(runtime.options, "filters")
          const liveRepository = liveSource === "regions" ? runtime.regionsRepository : runtime.objectsRepository
          if (getAdminMapInstance() !== runtime ||
            owner.current.runtime !== runtime || owner.current.source !== source ||
            owner.current.repository !== repository ||
            owner.current.source !== liveSource || owner.current.repository !== liveRepository ||
            (isCurrentOwner && !isCurrentOwner())) return
          patchLiveMapOptions({ filtersSchema: fullFilters ? next : mergeLiteFilterFields(allFields, next) })
          setFields(next)
          onSaved?.()
        }}
      />
      <ProductFeatureDialog feature="filters" open={premiumOpen} onOpenChange={setPremiumOpen} />
    </section>
  )
}
