import { useEffect, useState } from 'react'
import { useAdminMap } from '@/lib/live-map-options'
export function TypographyThemeStatus() {
  const map = useAdminMap()
  const [status, setStatus] = useState(() => map?.getTypographyStatus?.() ?? '')
  useEffect(() => {
    const refresh = () => setStatus(map?.getTypographyStatus?.() ?? '')
    refresh(); map?.events.on('typographyChanged', refresh)
    return () => map?.events.off?.('typographyChanged', refresh)
  }, [map])
  return status ? <p role="status" className="text-xs text-muted-foreground">{status}</p> : null
}
