import type { JSX } from "react"
import type { MapSvgNode, NodeType } from "@/lib/nodes-admin"
import { getSharedExtensionHost } from "@/lib/extensions"

export type NodeAdminPanelProps = {
  node: MapSvgNode
  omitLayoutPlacement: boolean
}

export type NodeAdminDefinition = {
  type: NodeType
  SettingsPanel: (props: NodeAdminPanelProps) => JSX.Element | null
}

export function registerNodeAdminDefinition(definition: NodeAdminDefinition): void {
  getSharedExtensionHost().register("admin.node", definition.type, definition)
}

export function getNodeAdminDefinition(type: NodeType): NodeAdminDefinition | undefined {
  const host = getSharedExtensionHost()
  host.seal("admin.node")
  return host.get<NodeAdminDefinition>("admin.node", type)
}
