import type { SettingsFormSchema } from "@/lib/settings-form/types"

export const TOOLTIP_POSITION_OPTIONS = [
  { value: "left", label: "Left" },
  { value: "top-left", label: "Top-left" },
  { value: "top", label: "Top" },
  { value: "top-right", label: "Top-right" },
  { value: "right", label: "Right" },
  { value: "bottom-right", label: "Bottom-right" },
  { value: "bottom", label: "Bottom" },
  { value: "bottom-left", label: "Bottom-left" },
] as const

/** Defaults matching `default-options.ts` tooltips (+ form fields). */
export const TOOLTIP_SETTINGS_DEFAULTS: Record<string, unknown> = {
  position: "bottom-right",
  template: "",
}

export const TOOLTIP_STYLES_DEFAULTS: Record<string, unknown> = {
  minWidth: 100,
  maxWidth: "",
}

/** Schema for Components → Tooltip settings (dev `form-tooltip-settings`). */
export const tooltipSettingsSchema: SettingsFormSchema = {
  fields: [
    {
      type: "position-grid",
      path: "position",
      label: "Position",
      options: [...TOOLTIP_POSITION_OPTIONS],
    },
  ],
}

export const tooltipStylesSchema: SettingsFormSchema = {
  fields: [
    {
      type: "group",
      id: "tooltip-width",
      label: "Width",
      fields: [
        {
          type: "number",
          path: "minWidth",
          shortLabel: "Min",
          label: "Minimum width",
          integer: true,
          allowEmpty: true,
          suffix: "px",
        },
        {
          type: "number",
          path: "maxWidth",
          shortLabel: "Max",
          label: "Maximum width",
          integer: true,
          allowEmpty: true,
          suffix: "px",
        },
      ],
    },
  ],
}
