import type { ReactNode } from "react"
import { SettingsSection } from "@/components/settings-form/SettingsSection"
import { SettingsBooleanField } from "@/components/settings-form/SettingsControlField"
import { useLayoutMigration } from "@/components/layout/LayoutMigrationDialog"
import { containerSettingsPatch, isContainerHidden } from "@/lib/layout-containers"
import { readLayoutOptions } from "@/lib/layout-grid"
import { applyLayoutEdit } from "@/lib/layout-history"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import type { MapSvgNode } from "@/lib/nodes-admin"
import { previewSessionLayoutBreakpoint } from "@/lib/preview-canvas"
import { useWorkspaceStore } from "@/lib/workspace-store"

/** Inspector and canvas share profile visibility, independently of legacy enable flags. */
export function LayoutDisplaySection({ map, node, children, hideDivider }: {
  map: MapsvgMapInstance; node: MapSvgNode; children?: ReactNode; hideDivider?: boolean
}) {
  const bp = useWorkspaceStore(state => previewSessionLayoutBreakpoint(state.mapSessions[String(map.id)]))
  const { requestMigration } = useLayoutMigration()
  return <SettingsSection title={`Display: ${bp.charAt(0).toUpperCase() + bp.slice(1)}`} hideDivider={hideDivider}>
    <SettingsBooleanField id={`layout-hidden-${node.id}`} label="Hide in this layout"
      checked={isContainerHidden(node, bp, readLayoutOptions(map.options.layout))}
      onCheckedChange={hidden => requestMigration(() => {
        const patch = containerSettingsPatch(map, node.id, bp, { hidden })
        applyLayoutEdit({ ...patch, layout: { ...patch.layout, mountMode: "tree" } })
      })} />
    {children}
  </SettingsSection>
}
