import { useMemo, useState } from "react"
import { Search, Table2 } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { schemaDisplayTitle, type DataSchema } from "@/lib/mapsvg-api"
import { cn } from "@/lib/utils"

type Props = {
  open: boolean
  onOpenChange: (open: boolean) => void
  schemas: DataSchema[]
  connectedIds: Set<string>
  onSelect: (schemaId: string) => void
}

export function DataSourceBrowser({ open, onOpenChange, schemas, connectedIds, onSelect }: Props) {
  const [search, setSearch] = useState("")

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase()
    if (!q) return schemas

    return schemas.filter((schema) => {
      const title = schemaDisplayTitle(schema).toLowerCase()
      return (
        title.includes(q) || schema.name.toLowerCase().includes(q) || String(schema.id).includes(q)
      )
    })
  }, [schemas, search])

  const select = (schemaId: string) => {
    onSelect(schemaId)
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[70vh] flex-col sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>Browse all sources</DialogTitle>
          <DialogDescription>
            Inspect any data source without connecting it to this map.
          </DialogDescription>
        </DialogHeader>

        <div className="relative">
          <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            autoFocus
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search sources…"
            className="pl-9"
          />
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto rounded-md border border-border">
          {filtered.length === 0 ? (
            <p className="p-4 text-sm text-muted-foreground">No matches.</p>
          ) : (
            filtered.map((schema) => {
              const id = String(schema.id)
              const connected = connectedIds.has(id)

              return (
                <button
                  key={id}
                  type="button"
                  onClick={() => select(id)}
                  className={cn(
                    "flex w-full items-center gap-3 border-b border-border px-3 py-2.5 text-left last:border-b-0 hover:bg-accent hover:text-accent-foreground",
                  )}
                >
                  <Table2 className="size-4 shrink-0 text-muted-foreground" />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium">
                      {schemaDisplayTitle(schema)}
                    </span>
                    <span className="block truncate font-mono text-[11px] text-muted-foreground">
                      {schema.name}
                    </span>
                  </span>
                  {connected ? (
                    <Badge variant="secondary" className="shrink-0 px-1.5 text-[10px]">
                      Map
                    </Badge>
                  ) : null}
                </button>
              )
            })
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}
