import { createElement } from "react"
import { RegionDataRulesEditor } from "../region-data-rules/RegionDataRulesEditor"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import type { SettingsFormSchema, SettingsOption } from "@/lib/settings-form/types"

const CURSOR_OPTIONS: SettingsOption[] = [
  { value: "default", label: "Default" },
  { value: "pointer", label: "Pointer" },
]

/** Root options slice — region behaviour. */
export const REGION_SETTINGS_DEFAULTS: Record<string, unknown> = {
  cursor: "default",
  multiSelect: false,
  disableAll: false,
  labelsRegions: { on: false },
}

export const regionSettingsSchema: SettingsFormSchema = {
  fields: [
    {
      type: "radio",
      path: "cursor",
      label: "Cursor",
      options: CURSOR_OPTIONS,
    },
    { type: "switch", path: "multiSelect", label: "Multi Select" },
    { type: "switch", path: "disableAll", label: "Disable all regions" },
    { type: "switch", path: "labelsRegions.on", label: "Region labels" },
    { type: "section", id: "region-data-rules", label: "Data rules" },
    { type: "custom", id: "region-data-rules-editor", render: () => createElement(RegionDataRulesEditor, { map: getAdminMapInstance() }) },
  ],
}
