import type { SettingsFormSchema, SettingsOption } from "@/lib/settings-form/types"
import { getByPath } from "@/lib/settings-form/path"

const REFETCH_UNITS: SettingsOption[] = [
  { value: "s", label: "seconds" },
  { value: "m", label: "minutes" },
  { value: "h", label: "hours" },
]

/** Stub region statuses until schema is wired. */
export const CONNECTION_STATUS_OPTIONS: SettingsOption[] = [
  { value: "unchanged", label: "Unchanged" },
  { value: "1", label: "Enabled" },
  { value: "0", label: "Disabled" },
]

function on(path: string) {
  return (values: Record<string, unknown>) => Boolean(getByPath(values, path))
}

function whenSourceObjects(values: Record<string, unknown>) {
  return (
    Boolean(getByPath(values, "statusSyncOn")) &&
    getByPath(values, "statusSyncSource") !== "regions"
  )
}

export const REGIONS_CONNECTIONS_DEFAULTS: Record<string, unknown> = {
  regionsAutoRefetch: { on: false, value: 5, unit: "s" },
  regionsDynamicStatusOrder: ["statusSync", "noObjects", "filtered"],
  statusSyncOn: false,
  statusSyncSource: "objects",
  statusSyncField: "",
  statusSyncMultiStrategy: "priority",
  regionsDynamicStatus: {
    noObjects: "unchanged",
    filtered: "unchanged",
  },
}

/** Regions query settings — declarative fields; priority / sync table via custom. */
export const regionsConnectionsSchema: SettingsFormSchema = {
  fields: [
    {
      type: "switch",
      path: "regionsAutoRefetch.on",
      label: "Auto-refetch",
      help: "Periodically reload regions on the front-end map only (not in the admin). Minimum interval is 5 seconds.",
    },
    {
      type: "number",
      path: "regionsAutoRefetch.value",
      label: "Interval",
      indent: true,
      integer: true,
      min: 1,
      visible: on("regionsAutoRefetch.on"),
    },
    {
      type: "select",
      path: "regionsAutoRefetch.unit",
      label: "Unit",
      indent: true,
      options: REFETCH_UNITS,
      visible: on("regionsAutoRefetch.on"),
    },

    { type: "section", id: "sec-dynamic-status", label: "Dynamic status" },

    {
      type: "custom",
      id: "status-priority",
      render: (ctx) => {
        const order = (ctx.getValue("regionsDynamicStatusOrder") as string[]) ?? [
          "statusSync",
          "noObjects",
          "filtered",
        ]
        const labels: Record<string, string> = {
          statusSync: "Object fields sync",
          noObjects: "No objects",
          filtered: "Filtered out",
        }
        return (
          <div className="grid gap-1.5">
            <div className="text-sm font-medium">Status priority</div>
            <ul className="rounded-md border border-border">
              {order.map((rule) => (
                <li key={rule} className="border-b border-border px-3 py-2 text-sm last:border-b-0">
                  {labels[rule] ?? rule}
                </li>
              ))}
            </ul>
            <p className="text-sm text-muted-foreground">
              Drag-to-reorder later. Topmost matching rule wins.
            </p>
          </div>
        )
      },
    },

    {
      type: "switch",
      path: "statusSyncOn",
      label: "Fields sync",
      help: "Set region status from a field on the front end only; does not write to the database.",
    },
    {
      type: "select",
      path: "statusSyncSource",
      label: "Source",
      indent: true,
      options: [
        { value: "objects", label: "Connected objects" },
        { value: "regions", label: "Regions data" },
      ],
      visible: on("statusSyncOn"),
    },
    {
      type: "select",
      path: "statusSyncField",
      label: "Field",
      indent: true,
      placeholder: "…",
      options: [
        { value: "status", label: "status" },
        { value: "category", label: "category" },
      ],
      visible: on("statusSyncOn"),
    },
    {
      type: "radio",
      path: "statusSyncMultiStrategy",
      label: "When multiple objects have different values",
      indent: true,
      options: [
        {
          value: "priority",
          label: "Pick by priority",
          help: "Topmost matching field value wins (sortable table later).",
        },
        {
          value: "special",
          label: "Set special status",
          help: "Uses the special “Multiple values” row status.",
        },
      ],
      visible: whenSourceObjects,
    },
    {
      type: "custom",
      id: "status-sync-table",
      visible: on("statusSyncOn"),
      render: () => (
        <div className="rounded-md border border-dashed border-border p-3 text-sm text-muted-foreground">
          Field value → Region status mapping table — later.
        </div>
      ),
    },

    {
      type: "radio",
      path: "regionsDynamicStatus.noObjects",
      label: "Status of Regions with no objects",
      options: CONNECTION_STATUS_OPTIONS,
    },
    {
      type: "radio",
      path: "regionsDynamicStatus.filtered",
      label: "Status of Regions that are filtered out",
      options: CONNECTION_STATUS_OPTIONS,
    },
  ],
}
