import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import { createSchemaField, validateSchemaFields } from "../../form-builder/schema-builder/model"

export const MAP_FILTER_FIELD_TYPES = [
  // START filters
  "select",
  "radio",
  "checkboxes",
  "search",
  // END
  "distance",
] as const

/** Matches the retained FormElement filter-mode nested parameter convention. */
export function filterParameterPatch(parameterName: string) {
  const parts = parameterName.split(".")
  const path = parts.length > 1 ? parts.slice(1) : parts
  const short =
    path[0] +
    path
      .slice(1)
      .map((part) => `[${part}]`)
      .join("")
  return { parameterName, parameterNameShort: short, name: short }
}

export function createMapFilterField(type: string, fields: FormFieldData[]) {
  const field = createSchemaField(type, fields)
  return type === "search" || type === "distance"
    ? field
    : { ...field, ...filterParameterPatch("") }
}

export function validateMapFilterFields(fields: FormFieldData[]) {
  // Database reserved column names do not apply to parameters such as Region.status.
  // Reuse the constructor's option validation while validating filter identities below.
  const errors = validateSchemaFields(
    fields.map((field, index) => ({ ...field, name: `filter_${index}` })),
  )
  const names = new Set<string>()
  fields.forEach((field, index) => {
    const parameter = String(field.parameterName ?? "")
    if (!parameter) errors.push({ index, message: "Choose a source field for this filter" })
    const name = String(field.parameterNameShort ?? field.name ?? "")
    if (names.has(name)) errors.push({ index, message: "Filter parameters should be unique" })
    names.add(name)
  })
  return errors
}

export function filterSourceFields(fields: FormFieldData[], source: "objects" | "regions") {
  const prefix = source === "regions" ? "Region" : "Object"
  return fields
    .filter((field) => !["location", "image"].includes(field.type))
    .flatMap((field) => {
      const names =
        field.type === "post" ? ["post.post_title", "post.post_status"] : [String(field.name)]
      return names.map((name) => ({
        value: `${prefix}.${name}`,
        label: `${field.label || name} (${prefix}.${name})`,
        field,
      }))
    })
}
