import { useEffect, useState } from "react"
import { ChevronDownIcon } from "lucide-react"
import { ControllerView } from "@/components/ControllerView"
import { SettingsForm } from "@/components/settings-form/SettingsForm"
import {
  SCENE_SETTINGS_DEFAULTS,
  sceneSettingsSchema,
} from "@/components/settings/schemas/sceneSettingsSchema"
import { FormBuilderCombobox } from "@/components/form-builder/FormBuilderCombobox"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { openDatabaseQuery } from "@/lib/database-navigation"
import { SettingsBooleanField, SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from "@/components/ui/input-group"
import { DropdownMenu, DropdownMenuContent, DropdownMenuRadioGroup, DropdownMenuRadioItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import {
  mergeOptionsSlice,
  patchLiveMapOptions,
  subscribeLiveMapOptions,
  useAdminMap,
} from "@/lib/live-map-options"
import {
  patchSceneQueryBinding,
  readNodes,
  readScenes,
  sceneById,
  sceneQueryId,
  updateSceneQueryBinding,
  writeNodesAndScenes,
  type SceneQueryBinding,
} from "@/lib/nodes-admin"
import { QueryOrderEditor } from "@/components/data/QueryOrderEditor"
import { bindingPageSize, readPageBinding } from "../../../../mapsvg/Map/pageBindings"
import { getAdminParams } from "@/lib/admin-params"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { appEditingPageId } from "@/lib/app-state-editor"
import { compatibleGlobalQueries, queryResultFields } from "@/lib/global-query-bindings"
import { fetchGlobalQueries, fetchSchemas, type DataSchema, type GlobalSavedQuery } from "@/lib/mapsvg-api"

type Props = {
  sceneId: string
}

type BindingRole = "objects" | "regions"

const QUERY_OPTIONS: Record<BindingRole, ReadonlyArray<{ id: string; label: string }>> = {
  objects: [{ id: "getObjects", label: "getObjects" }],
  regions: [{ id: "getRegions", label: "getRegions" }],
}

const DEFAULT_REFETCH = {
  on: false,
  value: 5,
  unit: "s" as const,
}

function availableQueryValue(role: BindingRole, queryId: string, globalQueries: GlobalSavedQuery[]): string | undefined {
  return QUERY_OPTIONS[role].some((query) => query.id === queryId)
    || globalQueries.some((query) => query.id === queryId || query.name === queryId) ? queryId : undefined
}

export function SceneSettingsBody({ sceneId }: Props) {
  const map = useAdminMap()
  const mapId = map?.id ? Number(map.id) : null
  const session = useWorkspaceStore((state) =>
    mapId ? state.mapSessions[String(mapId)] : undefined,
  )
  const setMapScroll = useWorkspaceStore((state) => state.setMapScroll)
  const [, setOptionsTick] = useState(0)
  const [globalQueries, setGlobalQueries] = useState<GlobalSavedQuery[]>([])
  const [catalog, setCatalog] = useState<DataSchema[]>([])
  const [queryError, setQueryError] = useState<string | null>(null)
  const [queriesLoaded, setQueriesLoaded] = useState(false)

  useEffect(() => subscribeLiveMapOptions(() => setOptionsTick((tick) => tick + 1)), [])
  useEffect(() => {
    if (!getAdminParams().globalQueriesEnabled) return
    let active = true
    const reload = () => {
      Promise.all([fetchGlobalQueries(), fetchSchemas()])
        .then(([queries, schemas]) => {
          if (active) {
            setGlobalQueries(queries)
            setCatalog(schemas)
            setQueryError(null)
            setQueriesLoaded(true)
          }
        })
        .catch((error) => {
          if (active) {
            setQueryError(error instanceof Error ? error.message : String(error))
            setQueriesLoaded(true)
          }
        })
    }
    reload()
    const onQueryMutation = () => reload()
    const onSchemaMutation = () => reload()
    window.addEventListener("mapsvg:query-mutation", onQueryMutation)
    window.addEventListener("mapsvg:schema-mutation", onSchemaMutation)
    return () => {
      active = false
      window.removeEventListener("mapsvg:query-mutation", onQueryMutation)
      window.removeEventListener("mapsvg:schema-mutation", onSchemaMutation)
    }
  }, [sceneId])

  const scenes = readScenes(map)
  const scene = sceneById(scenes, sceneId)

  if (!scene) {
    return <p className="p-3 text-sm text-muted-foreground">Page not found.</p>
  }
  if (appEditingPageId(map) && appEditingPageId(map) !== sceneId) {
    return <p className="p-3 text-sm text-muted-foreground">Select this Page in the preview switcher to edit it.</p>
  }

  const sceneSettingsValues = mergeOptionsSlice(SCENE_SETTINGS_DEFAULTS, map?.options)

  const setBindingQuery = (role: BindingRole, queryId: string) => {
    const nextScenes = updateSceneQueryBinding(readScenes(map), sceneId, role, queryId)
    writeNodesAndScenes(readNodes(map), nextScenes)
    map?.refreshPageBindings?.()
  }

  const patchBinding = (role: BindingRole, patch: Partial<SceneQueryBinding>) => {
    const nextScenes = patchSceneQueryBinding(readScenes(map), sceneId, role, {
      ...readPageBinding(map?.options, role, sceneId),
      ...patch,
    })
    writeNodesAndScenes(readNodes(map), nextScenes)
    map?.refreshPageBindings?.()
  }

  const bindingFields = (role: BindingRole) => {
    const queryId = sceneQueryId(scene, role)
    const compatible = compatibleGlobalQueries(globalQueries, catalog, role)
    const selectedQuery = availableQueryValue(role, queryId, compatible)
    const activeBinding = readPageBinding(map?.options, role, sceneId)
    const refetch = activeBinding?.refetch ?? DEFAULT_REFETCH
    const selectedDefinition = globalQueries.find(query => query.id === activeBinding?.queryId || query.name === activeBinding?.queryId)
    const legacySchema = (map?.options?.database as { schemas?: Record<string, { id?: string | number; name?: string }> })?.schemas?.[role]
    const boundSchema = selectedDefinition
      ? catalog.find(schema => String(schema.id) === String(selectedDefinition.schemaId))
      : catalog.find(schema => (legacySchema?.id != null && String(schema.id) === String(legacySchema.id)) || schema.name === legacySchema?.name)
    let parameterFields: Record<string, { type: string; title?: string }> = {}
    try { parameterFields = JSON.parse(selectedDefinition?.rpc?.paramsSchema ?? "{}").properties ?? {} } catch { /* Server reports malformed persisted definitions. */ }
    const sortFields = queryResultFields(selectedDefinition, boundSchema).filter(field => !["location", "images", "post", "region", "relation"].includes(field.type ?? "")).map(field => ({ value: field.name, label: field.label || field.name || "" }))
    return (
      <div role="region" aria-label={`${role === "objects" ? "Objects" : "Regions"} data binding`} className="contents">
        <SettingsControlField id={`binding-${role}-query`} label="Query">
          <div className="flex min-w-0 items-center gap-2">
            <div className="min-w-0 flex-1">
              <FormBuilderCombobox
                id={`binding-${role}-query`}
                aria-label={"Query for " + role}
                value={compatible.find(query => query.name === selectedQuery)?.id ?? selectedQuery ?? ""}
                onValueChange={value => value && setBindingQuery(role, value)}
                placeholder="Choose a Query"
                searchPlaceholder="Search queries..."
                options={[
                  ...QUERY_OPTIONS[role].filter(query => !getAdminParams().globalQueriesEnabled || query.id === queryId).map(query => ({ value: query.id, label: query.label })),
                  ...compatible.map(query => ({ value: query.id, label: query.name })),
                ]}
              />
            </div>
            {selectedDefinition ? (
              <Button type="button" variant="outline"
                onClick={() => openDatabaseQuery(selectedDefinition.id)}>Edit query</Button>
            ) : null}
          </div>
          {queriesLoaded && !selectedQuery ? (
            <p className="text-xs text-destructive">
              Query {queryId} is unavailable or its result is incompatible with this binding. Select a compatible query.
            </p>
          ) : null}
        </SettingsControlField>
        {Object.entries(parameterFields).map(([name, definition]) => definition.type === "boolean" ? (
          <SettingsBooleanField key={name} id={`binding-${role}-param-${name}`} label={definition.title || name}
            aria-label={`Query parameter ${name}`} checked={activeBinding.params?.[name] === true}
            onCheckedChange={value => patchBinding(role, { params: { ...activeBinding.params, [name]: value } })} />
        ) : (
          <SettingsControlField key={name} id={`binding-${role}-param-${name}`} label={definition.title || name}>
            <Input id={`binding-${role}-param-${name}`} aria-label={`Query parameter ${name}`}
              inputMode={definition.type === "integer" ? "numeric" : definition.type === "number" ? "decimal" : undefined}
              value={String(activeBinding.params?.[name] ?? "")} onChange={event => {
                const next = { ...activeBinding.params }
                if (event.target.value === "") delete next[name]
                else next[name] = definition.type === "string" ? event.target.value : Number(event.target.value)
                patchBinding(role, { params: next })
              }} />
          </SettingsControlField>
        ))}
        <SettingsBooleanField id={`binding-${role}-sort`} label="Override Query sort order"
          checked={!!activeBinding.orderBy?.length}
          onCheckedChange={on => patchBinding(role, { orderBy: on && sortFields[0] ? [{ [sortFields[0].value]: "asc" }] : [] })} />
        {activeBinding.orderBy?.length ? (
          <div data-slot="settings-dependent-fields" className="ml-2 flex min-w-0 flex-col gap-4 border-l-2 border-border pl-4">
            <QueryOrderEditor value={activeBinding.orderBy} fields={sortFields}
              onChange={orderBy => patchBinding(role, { orderBy })} />
          </div>
        ) : null}
        <SettingsControlField id={`binding-${role}-items-per-page`} label="Items per page">
          <Input id={`binding-${role}-items-per-page`} aria-label="Binding items per page" inputMode="numeric"
            value={activeBinding.perPage === null ? "" : bindingPageSize(activeBinding, selectedDefinition?.input.take)}
            placeholder={`Query · ${selectedDefinition?.input.take ?? 50}`}
            onChange={event => patchBinding(role, { perPage: event.target.value === "" ? null : Math.min(5000, Math.max(1, Math.trunc(Number(event.target.value)) || 1)) })} />
        </SettingsControlField>
        {(["next", "prev"] as const).map(direction => <SettingsControlField
          key={direction} id={`binding-${role}-${direction}`} label={direction === "next" ? '"Next page" text' : '"Previous page" text'}>
          <Input id={`binding-${role}-${direction}`} value={activeBinding.pagination[direction]}
            onChange={event => patchBinding(role, { pagination: { ...activeBinding.pagination, [direction]: event.target.value } })} />
        </SettingsControlField>)}
        <SettingsBooleanField id={"refetch-" + role} label="Auto-refetch"
          checked={refetch.on} onCheckedChange={on => patchBinding(role, { refetch: { ...refetch, on } })} />
        {refetch.on ? (
          <div data-slot="settings-dependent-fields" className="ml-2 flex min-w-0 flex-col gap-4 border-l-2 border-border pl-4">
            <SettingsControlField id={"refetch-value-" + role} label="Every">
              <InputGroup>
                <InputGroupInput id={"refetch-value-" + role} inputMode="numeric" value={refetch.value}
                  onChange={event => patchBinding(role, { refetch: { ...refetch, value: Math.max(1, Number.parseInt(event.target.value || "1", 10)) } })} />
                <InputGroupAddon align="inline-end">
                  <DropdownMenu modal={false}>
                    <DropdownMenuTrigger asChild>
                      <InputGroupButton aria-label="Interval unit"
                        className="text-muted-foreground hover:bg-transparent hover:text-foreground/80 dark:hover:bg-transparent">
                        {{ s: "seconds", m: "minutes", h: "hours" }[refetch.unit]}
                        <ChevronDownIcon />
                      </InputGroupButton>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuRadioGroup value={refetch.unit} onValueChange={unit => {
                        if (unit !== "s" && unit !== "m" && unit !== "h") return
                        patchBinding(role, { refetch: { ...refetch, unit } })
                      }}>
                        <DropdownMenuRadioItem value="s">seconds</DropdownMenuRadioItem>
                        <DropdownMenuRadioItem value="m">minutes</DropdownMenuRadioItem>
                        <DropdownMenuRadioItem value="h">hours</DropdownMenuRadioItem>
                      </DropdownMenuRadioGroup>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </InputGroupAddon>
              </InputGroup>
            </SettingsControlField>
          </div>
        ) : null}
        <SettingsControlField id={`binding-${role}-disable-on`} label="Disable on">
          <div id={`binding-${role}-disable-on`} role="group" aria-label="Disable on" className="contents">
            <SettingsBooleanField id={`binding-${role}-initial-load`} label="Initial load"
              checked={activeBinding.disableOn.initialLoad}
              onCheckedChange={initialLoad => patchBinding(role, { disableOn: { ...activeBinding.disableOn, initialLoad } })} />
            <SettingsBooleanField id={`binding-${role}-empty-filters`} label="Empty filters"
              checked={activeBinding.disableOn.emptyFilters}
              onCheckedChange={emptyFilters => patchBinding(role, { disableOn: { ...activeBinding.disableOn, emptyFilters } })} />
          </div>
        </SettingsControlField>
      </div>
    )
  }

  return (
    <div className="relative h-full min-h-0 min-w-0 max-w-full overflow-hidden">
      <ControllerView
        scrollTop={session?.scrollPositions?.scene ?? 0}
        onScrollTopChange={
          mapId ? next => setMapScroll(mapId, "scene", next) : undefined
        }
      >
        <SettingsForm
          schema={{ fields: [
            ...sceneSettingsSchema.fields,
            { type: "section", id: "scene-objects-binding", label: "Objects" },
            { type: "custom", id: "scene-objects-binding-fields", render: () => bindingFields("objects") },
            { type: "section", id: "scene-regions-binding", label: "Regions" },
            { type: "custom", id: "scene-regions-binding-fields", render: () => bindingFields("regions") },
          ] }}
          leading={queryError ? <p role="alert" className="text-xs text-destructive">{queryError}</p> : undefined}
          values={sceneSettingsValues}
          onChange={next => patchLiveMapOptions(next)}
        />
      </ControllerView>
    </div>
  )
}
