import { getSharedExtensionHost } from "@/lib/extensions"
import type { SettingsField, SettingsFormSchema } from "./types"

/**
 * A Pro schema fragment: a list of fields each carrying a `replacesAlert` key
 * that identifies which `type: "alert"` placeholder in the Lite schema it replaces.
 *
 * Pro bundles call `mergeSettingsSchema(liteSchema, proFragment)` at runtime after
 * the Pro admin chunk loads. The Lite admin never imports Pro field components —
 * Pro fields arrive only through this merge, keeping the package boundary intact.
 */
export type ProSchemaField = SettingsField & {
  /**
   * ID of the `type: "alert"` field in the Lite schema that this Pro field replaces.
   * If the alert is not found the Pro field is appended at the end instead.
   */
  replacesAlert?: string
}

export type ProSchemaFragment = {
  fields: ProSchemaField[]
}

/**
 * Merge a Pro schema fragment into a Lite schema.
 *
 * Rules:
 * 1. For each Pro field with `replacesAlert: "<id>"`:
 *    - Find the `type: "alert"` field with that id in the Lite schema.
 *    - Replace it in-place with the Pro field (preserving position).
 *    - If no matching alert exists, append the Pro field at the end.
 * 2. Pro fields without `replacesAlert` are appended at the end.
 * 3. The Lite schema is never mutated — a new schema object is returned.
 * 4. Alert fields with no matching Pro replacement are kept as-is
 *    (Lite users still see the info notice).
 */
export function mergeSettingsSchema(
  liteSchema: SettingsFormSchema,
  proFragment: ProSchemaFragment,
): SettingsFormSchema {
  // Index Pro fields by the alert id they replace
  const replacements = new Map<string, ProSchemaField>()
  const appended: ProSchemaField[] = []

  for (const proField of proFragment.fields) {
    if (proField.replacesAlert) {
      replacements.set(proField.replacesAlert, proField)
    } else {
      appended.push(proField)
    }
  }

  const mergedFields: SettingsField[] = liteSchema.fields.map((field) => {
    if (field.type === "alert" && replacements.has(field.id)) {
      const proField = replacements.get(field.id)!
      // Strip replacesAlert from the field that ends up in the merged schema
      const { replacesAlert: _, ...rest } = proField
      return rest as SettingsField
    }
    return field
  })

  return { fields: [...mergedFields, ...appended] }
}

export type RegisteredSettingsSchemaFragment = {
  scope: string
  id: string
  fragment: ProSchemaFragment
}

export function registerSettingsSchemaFragment(
  scope: string,
  id: string,
  fragment: ProSchemaFragment,
): void {
  getSharedExtensionHost().register("admin.schema", `${scope}:${id}`, {
    scope,
    id,
    fragment,
  } satisfies RegisteredSettingsSchemaFragment)
}

export function getRegisteredSettingsSchemaFragments(scope: string): ProSchemaFragment[] {
  const host = getSharedExtensionHost()
  host.seal("admin.schema")
  return host
    .list<RegisteredSettingsSchemaFragment>("admin.schema")
    .map((entry) => entry.value)
    .filter((entry) => entry.scope === scope)
    .map((entry) => entry.fragment)
}

export function mergeRegisteredSettingsSchema(
  scope: string,
  liteSchema: SettingsFormSchema,
): SettingsFormSchema {
  return getRegisteredSettingsSchemaFragments(scope).reduce(
    (schema, fragment) => mergeSettingsSchema(schema, fragment),
    liteSchema,
  )
}
