import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { DatabaseIcon, PlusIcon, SlidersHorizontalIcon } from "lucide-react"
import { AdminView, type AdminBreadcrumb } from "@/components/AdminView"
import { ControllerView } from "@/components/ControllerView"
import { DataListTable } from "@/components/data/DataListTable"
import { DataQuerySettings } from "@/components/data/DataQuerySettings"
import { DataSourceBrowser } from "@/components/data/DataSourceBrowser"
import { DataSourcesSidebar } from "@/components/data/DataSourcesSidebar"
import { SavedDataQueryEditor } from "@/components/data/SavedDataQueryEditor"
import {
  COMPLEX_FIELD_CONTEXT_KEY,
  createMapRegionAdapter,
  createWordPressMediaPicker,
  createWordPressPostAdapter,
} from "@/components/form-builder/complex-fields"
import {
  LOCATION_FIELD_CONTEXT_KEY,
  createMapSvgLocationAdapter,
} from "@/components/form-builder/location-field"
import { SchemaBuilder } from "@/components/form-builder/schema-builder"
import { SchemaForm } from "@/components/form-builder/schema-form"
import {
  deleteSavedDataQuery,
  readMapSavedDataQueries,
  upsertSavedDataQuery,
  writeMapSavedDataQueries,
  type SavedDataQuery,
} from "@/components/data/savedDataQueries"
import {
  builtInQueryForRole,
  sourceLabel,
  type BuiltInDataQueryId,
  type DataSelection,
  type DataSourceRole,
} from "@/components/data/dataNav"
import { Button } from "@/components/ui/button"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { getAdminParams } from "@/lib/admin-params"
import { useAdminMap } from "@/lib/live-map-options"
import {
  executeMapDataQuery,
  fetchCollectionRows,
  fetchMapDatabaseMeta,
  fetchSchemas,
  updateCollectionRow,
  updateSchemaFields,
  type DataSchema,
  type SchemaField,
  type ZodSettings,
} from "@/lib/mapsvg-api"
import { isRecordValidationError } from "@/lib/record-validation-error"
import { useCollectionEditorDefaults } from "@/lib/collection-editor-defaults"
import { cn } from "@/lib/utils"
import { useWorkspaceStore } from "@/lib/workspace-store"
import type { FormFieldData } from "../../../../mapsvg/FormBuilder/FieldDefinitions"

type Props = {
  mapId: number | null
  className?: string
}

type QueryViewMode = "data" | "edit"
type SourceViewMode = "rows" | "fields"

/** Map-scoped Data workspace with an opt-in Plasma saved-query canary. */
export function DataPanel({ mapId, className }: Props) {
  const map = useAdminMap()
  const session = useWorkspaceStore((state) =>
    mapId ? state.mapSessions[String(mapId)] : undefined,
  )
  const patchMapSession = useWorkspaceStore((state) => state.patchMapSession)
  const setMapScroll = useWorkspaceStore((state) => state.setMapScroll)
  const initialSelectionRef = useRef<DataSelection | null>(
    (session?.dataSelection as DataSelection | undefined) ?? null,
  )
  const restoredRowIdRef = useRef<string | number | null | undefined>(
    session?.dataSelectedRowId,
  )
  const canUseV2 = getAdminParams().dataLayerV2Enabled
  const canEditSavedQueries = canUseV2 && map !== null && mapId !== null && map.id === mapId
  const [schemas, setSchemas] = useState<DataSchema[]>([])
  const [connectedIds, setConnectedIds] = useState<Set<string>>(new Set())
  const [sourceRoles, setSourceRoles] = useState<Map<string, DataSourceRole>>(new Map())
  const [savedQueries, setSavedQueries] = useState<SavedDataQuery[]>([])
  const [selection, setSelection] = useState<DataSelection | null>(
    initialSelectionRef.current,
  )
  const [creatingQueryForSchemaId, setCreatingQueryForSchemaId] = useState<string | null>(null)
  const [rows, setRows] = useState<Record<string, unknown>[]>([])
  const [selectedRow, setSelectedRow] = useState<Record<string, unknown> | null>(null)
  const [rowCount, setRowCount] = useState(0)
  const [loadingSchemas, setLoadingSchemas] = useState(true)
  const [loadingRows, setLoadingRows] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [browseOpen, setBrowseOpen] = useState(false)
  const [queryViewMode, setQueryViewMode] = useState<QueryViewMode>(
    session?.dataQueryViewMode ?? "data",
  )
  const [sourceViewMode, setSourceViewMode] = useState<SourceViewMode>(
    session?.dataSourceViewMode ?? "rows",
  )

  const selectedSchema = useMemo(() => {
    if (!selection) return null
    return schemas.find((schema) => String(schema.id) === selection.schemaId) ?? null
  }, [schemas, selection])

  const selectedRole = selectedSchema ? sourceRoles.get(String(selectedSchema.id)) : undefined
  const editorPreferences = useCollectionEditorDefaults(selectedSchema)
  const rememberMarkerImage = useCallback((defaultMarkerImage: string) => editorPreferences.remember({ defaultMarkerImage }), [editorPreferences.remember])
  const selectedQuery = selection?.kind === "query" ? builtInQueryForRole(selectedRole) : null
  const editableSchemaFields = useMemo(
    () => (selectedSchema?.fields ?? []) as FormFieldData[],
    [selectedSchema],
  )

  const markerImages = useMemo(() => getAdminParams().markerImages, [])
  const mediaAdapter = useMemo(() => createWordPressMediaPicker(), [])
  const postAdapter = useMemo(() => createWordPressPostAdapter(), [])
  const filterableMarkerFields = useMemo(
    () =>
      (selectedSchema?.fields ?? [])
        .filter((field) =>
          ["select", "radio", "checkboxes", "region", "relation"].includes(
            String(field.type ?? ""),
          ),
        )
        .map((field) => `Object.${field.name}`),
    [selectedSchema],
  )
  const regionAdapter = useMemo(
    () => (map ? createMapRegionAdapter(map as never) : undefined),
    [map],
  )
  const locationAdapter = useMemo(
    () =>
      map && selectedSchema && connectedIds.has(String(selectedSchema.id))
        ? createMapSvgLocationAdapter(map as never, {
            markerImages,
            markerDefaults: { image: editorPreferences.defaults.defaultMarkerImage, rememberImage: rememberMarkerImage },
            filterableFields: filterableMarkerFields,
          })
        : undefined,
    [connectedIds, filterableMarkerFields, map, markerImages, selectedSchema, editorPreferences.defaults.defaultMarkerImage, rememberMarkerImage],
  )
  const formContext = useMemo(
    () => ({
      [COMPLEX_FIELD_CONTEXT_KEY]: {
        media: mediaAdapter,
        posts: postAdapter,
        regions: regionAdapter,
      },
      [LOCATION_FIELD_CONTEXT_KEY]: locationAdapter,
    }),
    [locationAdapter, mediaAdapter, postAdapter, regionAdapter],
  )
  const selectedSavedQuery = useMemo(() => {
    if (selection?.kind !== "savedQuery") return null
    return (
      savedQueries.find(
        (query) =>
          query.id === selection.savedQueryId &&
          query.schemaId === selection.schemaId &&
          query.sourceRole === selectedRole,
      ) ?? null
    )
  }, [savedQueries, selectedRole, selection])
  const creatingQuery =
    queryViewMode === "edit" &&
    selectedSchema != null &&
    creatingQueryForSchemaId === String(selectedSchema.id)

  useEffect(() => {
    if (!mapId) return
    patchMapSession(mapId, {
      dataSelection: selection ?? undefined,
      dataQueryViewMode: queryViewMode,
      dataSourceViewMode: sourceViewMode,
    })
  }, [mapId, patchMapSession, queryViewMode, selection, sourceViewMode])

  const selectRow = useCallback(
    (row: Record<string, unknown> | null) => {
      setSelectedRow(row)
      const id =
        row?.id != null && (typeof row.id === "string" || typeof row.id === "number")
          ? row.id
          : null
      restoredRowIdRef.current = id
      if (mapId) patchMapSession(mapId, { dataSelectedRowId: id })
    },
    [mapId, patchMapSession],
  )

  const selectRestoredSourceRow = useCallback(
    (nextRows: Record<string, unknown>[]) => {
      const restoredId = restoredRowIdRef.current
      const restored =
        restoredId == null
          ? undefined
          : nextRows.find((row) => String(row.id) === String(restoredId))
      selectRow(restored ?? nextRows[0] ?? null)
    },
    [selectRow],
  )

  const breadcrumbs = useMemo<AdminBreadcrumb[]>(() => {
    const crumbs: AdminBreadcrumb[] = [{ label: "Data" }]
    if (!selectedSchema) return crumbs

    const schemaId = String(selectedSchema.id)
    crumbs.push({
      label: sourceLabel(selectedSchema, selectedRole),
      onClick:
        selection?.kind !== "source" || creatingQuery
          ? () => {
              setSelection({ kind: "source", schemaId })
              setCreatingQueryForSchemaId(null)
              setQueryViewMode("data")
            }
          : undefined,
    })

    if (selection?.kind === "query" && selectedQuery) {
      crumbs.push({ label: selectedQuery.label })
    } else if (selection?.kind === "savedQuery" && selectedSavedQuery) {
      crumbs.push({ label: selectedSavedQuery.name })
    } else if (creatingQuery) {
      crumbs.push({ label: "New query" })
    } else {
      crumbs.push({ label: "All rows" })
    }

    return crumbs
  }, [creatingQuery, selectedRole, selectedQuery, selectedSavedQuery, selectedSchema, selection])

  useEffect(() => {
    const currentMap = mapId !== null && map?.id === mapId ? map : null
    setSavedQueries(canUseV2 ? readMapSavedDataQueries(currentMap) : [])
  }, [canUseV2, map, mapId])

  useEffect(() => {
    let cancelled = false
    setLoadingSchemas(true)
    setError(null)
    setCreatingQueryForSchemaId(null)

    void (async () => {
      try {
        const list = await fetchSchemas()
        if (cancelled) return
        setSchemas(list)

        const connected = new Set<string>()
        const roles = new Map<string, DataSourceRole>()

        if (mapId) {
          try {
            const meta = await fetchMapDatabaseMeta(mapId)

            const registerRole = (
              role: DataSourceRole,
              schemaId: string | null,
              tableName: string | null,
            ) => {
              const schema =
                (schemaId ? list.find((item) => String(item.id) === schemaId) : null) ??
                (tableName ? list.find((item) => item.name === tableName) : null)

              if (!schema) return
              const id = String(schema.id)
              connected.add(id)
              roles.set(id, role)
            }

            registerRole("objects", meta.objectsSchemaId, meta.objectsTableName)
            registerRole("regions", meta.regionsSchemaId, meta.regionsTableName)

            for (const id of meta.connectedSchemaIds) connected.add(id)
          } catch {
            // Map metadata is optional; keep the global browser available.
          }
        }

        if (cancelled) return
        setConnectedIds(connected)
        setSourceRoles(roles)

        const restoredSelection = initialSelectionRef.current
        const restoredSchemaExists =
          restoredSelection != null &&
          list.some(
            (schema) => String(schema.id) === restoredSelection.schemaId,
          )
        const preferred =
          list.find((schema) => roles.get(String(schema.id)) === "objects") ??
          list.find((schema) => connected.has(String(schema.id))) ??
          null

        setSelection(
          restoredSchemaExists
            ? restoredSelection
            : preferred
              ? { kind: "source", schemaId: String(preferred.id) }
              : null,
        )
      } catch (err) {
        if (cancelled) return
        setError(err instanceof Error ? err.message : String(err))
        setSchemas([])
        setConnectedIds(new Set())
        setSourceRoles(new Map())
        setSelection(null)
      } finally {
        if (!cancelled) setLoadingSchemas(false)
      }
    })()

    return () => {
      cancelled = true
    }
  }, [mapId])

  useEffect(() => {
    if (selection?.kind === "savedQuery" && !selectedSavedQuery) {
      setSelection({ kind: "source", schemaId: selection.schemaId })
      setQueryViewMode("data")
    }
  }, [selectedSavedQuery, selection])

  useEffect(() => {
    if (!selectedSchema) {
      setRows([])
      setSelectedRow(null)
      setRowCount(0)
      return
    }

    let cancelled = false
    setLoadingRows(true)
    setError(null)
    setSelectedRow(null)

    void (async () => {
      try {
        const schemaId = String(selectedSchema.id)
        const connected = connectedIds.has(schemaId)
        if (
          selection?.kind === "savedQuery" &&
          (!canUseV2 || !mapId || !connected || !selectedRole || !selectedSavedQuery)
        ) {
          throw new Error("This saved query is not connected to the current map source.")
        }

        if (canUseV2 && mapId && connected && selectedRole) {
          const saved = selection?.kind === "savedQuery" ? selectedSavedQuery : null
          const result = await executeMapDataQuery(mapId, selectedRole, {
            ...(saved?.query ?? {}),
            take: saved?.query.take ?? 50,
            skip: saved?.query.skip ?? 0,
          })
          if (cancelled) return
          setRows(result.rows)
          setRowCount(result.count)
          if (selection?.kind === "source") {
            selectRestoredSourceRow(result.rows)
          } else {
            setSelectedRow(null)
          }
        } else {
          const data = await fetchCollectionRows(selectedSchema, { perpage: 50 })
          if (cancelled) return
          setRows(data)
          setRowCount(data.length)
          if (selection?.kind === "source") {
            selectRestoredSourceRow(data)
          } else {
            setSelectedRow(null)
          }
        }
      } catch (err) {
        if (cancelled) return
        setRows([])
        setSelectedRow(null)
        setRowCount(0)
        setError(err instanceof Error ? err.message : String(err))
      } finally {
        if (!cancelled) setLoadingRows(false)
      }
    })()

    return () => {
      cancelled = true
    }
  }, [
    canUseV2,
    connectedIds,
    mapId,
    selectRestoredSourceRow,
    selectedRole,
    selectedSavedQuery,
    selectedSchema,
    selection,
  ])

  const selectSource = (schemaId: string) => {
    setSelection({ kind: "source", schemaId })
    setCreatingQueryForSchemaId(null)
    setQueryViewMode("data")
    setSourceViewMode("rows")
  }

  const selectQuery = (schemaId: string, queryId: BuiltInDataQueryId) => {
    setSelection({ kind: "query", schemaId, queryId })
    setCreatingQueryForSchemaId(null)
    setQueryViewMode("data")
  }

  const selectSavedQuery = (schemaId: string, savedQueryId: string) => {
    setSelection({ kind: "savedQuery", schemaId, savedQueryId })
    setCreatingQueryForSchemaId(null)
    setQueryViewMode("data")
  }

  const createQuery = (schemaId: string) => {
    setSelection({ kind: "source", schemaId })
    setCreatingQueryForSchemaId(schemaId)
    setQueryViewMode("edit")
  }

  const saveQuery = (query: SavedDataQuery) => {
    const next = upsertSavedDataQuery(savedQueries, query)
    writeMapSavedDataQueries(map, next)
    setSavedQueries(next)
    setCreatingQueryForSchemaId(null)
    setSelection({ kind: "savedQuery", schemaId: query.schemaId, savedQueryId: query.id })
    setQueryViewMode("data")
  }

  const removeQuery = (query: SavedDataQuery) => {
    const next = deleteSavedDataQuery(savedQueries, query.id)
    writeMapSavedDataQueries(map, next)
    setSavedQueries(next)
    setCreatingQueryForSchemaId(null)
    setSelection({ kind: "source", schemaId: query.schemaId })
    setQueryViewMode("data")
  }

  const saveSelectedRow = async (record: Record<string, unknown>) => {
    if (!selectedSchema) return

    setError(null)
    try {
      await updateCollectionRow(selectedSchema, record)
      const refreshed = await fetchCollectionRows(selectedSchema, { perpage: 50 })
      const id = record.id
      setRows(refreshed)
      setRowCount(refreshed.length)
      setSelectedRow(
        id == null
          ? (refreshed[0] ?? null)
          : (refreshed.find((row) => String(row.id) === String(id)) ?? refreshed[0] ?? null),
      )
    } catch (err) {
      if (!isRecordValidationError(err)) {
        setError(err instanceof Error ? err.message : String(err))
      }
      throw err
    }
  }

  const saveSchemaFields = async (fields: FormFieldData[], zodSettings: ZodSettings | null) => {
    if (!selectedSchema) return

    setError(null)
    try {
      await updateSchemaFields(selectedSchema, fields as SchemaField[], zodSettings)
      const refreshed = await fetchSchemas()
      setSchemas(refreshed)
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err))
      throw err
    }
  }

  const browsedSchemaId =
    selection?.kind === "source" && !connectedIds.has(selection.schemaId)
      ? selection.schemaId
      : null

  const hasEditableSelection =
    (selection?.kind === "query" && selectedQuery != null) ||
    (selection?.kind === "savedQuery" && selectedSavedQuery != null)

  return (
    <>
      <AdminView
        className={cn("h-full", className)}
        breadcrumbs={breadcrumbs}
        sidebar={
          loadingSchemas ? (
            <p className="px-2 text-xs text-muted-foreground">Loading…</p>
          ) : (
            <DataSourcesSidebar
              schemas={schemas}
              connectedIds={connectedIds}
              sourceRoles={sourceRoles}
              savedQueries={savedQueries}
              canUseV2={canEditSavedQueries}
              selection={selection}
              browsedSchemaId={browsedSchemaId}
              onSelectSource={selectSource}
              onSelectQuery={selectQuery}
              onSelectSavedQuery={selectSavedQuery}
              onCreateQuery={createQuery}
              onBrowseAll={() => setBrowseOpen(true)}
            />
          )
        }
      >
        <ControllerView
          toolbarStart={
            selectedSchema ? (
              selection?.kind === "source" && !creatingQuery ? (
                <ToggleGroup
                  type="single"
                  variant="outline"
                  size="sm"
                  spacing={1}
                  value={sourceViewMode}
                  onValueChange={(next) => {
                    if (next) setSourceViewMode(next as SourceViewMode)
                  }}
                  className="justify-start"
                >
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex">
                        <ToggleGroupItem value="rows" aria-label="Rows" className="size-6 p-0">
                          <DatabaseIcon />
                        </ToggleGroupItem>
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="bottom">Rows</TooltipContent>
                  </Tooltip>

                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex">
                        <ToggleGroupItem value="fields" aria-label="Fields" className="size-6 p-0">
                          <SlidersHorizontalIcon />
                        </ToggleGroupItem>
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="bottom">Fields</TooltipContent>
                  </Tooltip>
                </ToggleGroup>
              ) : hasEditableSelection ? (
                <ToggleGroup
                  type="single"
                  variant="outline"
                  size="sm"
                  spacing={1}
                  value={queryViewMode}
                  onValueChange={(next) => {
                    if (next) setQueryViewMode(next as QueryViewMode)
                  }}
                  className="justify-start"
                >
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex">
                        <ToggleGroupItem value="data" aria-label="Data" className="size-6 p-0">
                          <DatabaseIcon />
                        </ToggleGroupItem>
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="bottom">Data</TooltipContent>
                  </Tooltip>

                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex">
                        <ToggleGroupItem value="edit" aria-label="Edit" className="size-6 p-0">
                          <SlidersHorizontalIcon />
                        </ToggleGroupItem>
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="bottom">Edit</TooltipContent>
                  </Tooltip>
                </ToggleGroup>
              ) : (
                <span className="text-sm font-medium">{creatingQuery ? "New query" : "Data"}</span>
              )
            ) : null
          }
          scrollTop={session?.scrollPositions?.data ?? 0}
          onScrollTopChange={
            mapId ? (next) => setMapScroll(mapId, "data", next) : undefined
          }
          toolbarEnd={
            selectedSchema && selectedRole && connectedIds.has(String(selectedSchema.id)) ? (
              <div className="flex items-center gap-2">
                {(
                  selection?.kind === "source"
                    ? sourceViewMode === "rows"
                    : queryViewMode === "data"
                ) ? (
                  <span className="text-xs text-muted-foreground">
                    {rows.length === rowCount
                      ? `${rowCount} rows`
                      : `${rows.length} of ${rowCount}`}
                  </span>
                ) : null}
                {canEditSavedQueries && selection?.kind === "source" && !creatingQuery ? (
                  <Button
                    type="button"
                    size="xs"
                    variant="outline"
                    onClick={() => createQuery(String(selectedSchema.id))}
                  >
                    <PlusIcon />
                    New query
                  </Button>
                ) : null}
              </div>
            ) : null
          }
        >
          {error ? <p className="p-3 text-sm text-destructive">{error}</p> : null}

          {selection?.kind === "source" && selectedSchema && !creatingQuery ? (
            sourceViewMode === "fields" ? (
              <div className="h-full min-h-0 p-3">
                <SchemaBuilder
                  className="h-full"
                  fields={editableSchemaFields}
                  hiddenFieldNames={selectedSchema.type === "region" ? ["orphaned"] : undefined}
                  zodSettings={selectedSchema.zodSettings ?? null}
                  settingsContext={formContext}
                  onSave={saveSchemaFields}
                />
              </div>
            ) : (
              <div className="grid h-full min-h-0 grid-cols-2 overflow-hidden">
                <section className="min-h-0 min-w-0 overflow-hidden border-r border-border">
                  <DataListTable
                    schema={selectedSchema}
                    rows={rows}
                    loading={loadingRows}
                    readOnly
                    selectedRow={selectedRow}
                    onRowClick={selectRow}
                  />
                </section>
                <section className="flex min-h-0 min-w-0 flex-col overflow-hidden">
                  <header className="flex h-10 shrink-0 items-center border-b border-border px-3">
                    <span className="text-sm font-medium">
                      {selectedRow?.id != null ? `Edit row #${selectedRow.id}` : "Row editor"}
                    </span>
                  </header>
                  <div className="min-h-0 flex-1 overflow-auto p-4">
                    {selectedRow ? (
                      <SchemaForm
                        key={`${selectedSchema.id}:${String(selectedRow.id ?? "")}`}
                        schema={{
                          fields: editableSchemaFields,
                          zodSettings: selectedSchema.zodSettings ?? null,
                        }}
                        value={selectedRow}
                        controlContext={formContext}
                        submitLabel="Save row"
                        onSubmit={saveSelectedRow}
                      />
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        Select a row to edit its fields.
                      </p>
                    )}
                  </div>
                </section>
              </div>
            )
          ) : selectedSchema && selectedRole && creatingQuery ? (
            <SavedDataQueryEditor
              schema={selectedSchema}
              sourceRole={selectedRole}
              onSave={saveQuery}
              onCancel={() => {
                setCreatingQueryForSchemaId(null)
                setQueryViewMode("data")
              }}
            />
          ) : selection?.kind === "savedQuery" &&
            queryViewMode === "edit" &&
            selectedSchema &&
            selectedRole &&
            selectedSavedQuery ? (
            <SavedDataQueryEditor
              schema={selectedSchema}
              sourceRole={selectedRole}
              query={selectedSavedQuery}
              onSave={saveQuery}
              onDelete={removeQuery}
              onCancel={() => setQueryViewMode("data")}
            />
          ) : selection?.kind === "query" && queryViewMode === "edit" && selectedRole ? (
            <DataQuerySettings role={selectedRole} />
          ) : (
            <DataListTable schema={selectedSchema} rows={rows} loading={loadingRows} />
          )}
        </ControllerView>
      </AdminView>

      <DataSourceBrowser
        open={browseOpen}
        onOpenChange={setBrowseOpen}
        schemas={schemas}
        connectedIds={connectedIds}
        onSelect={selectSource}
      />
    </>
  )
}
