import { hasProductFeature } from "@/lib/product-features"
import { PremiumBadge } from "@/components/PremiumFeaturePlaceholder"
import { useState } from "react"
import { ChevronRight, Plus } from "lucide-react"
import { Collapsible, CollapsibleContent } from "@/components/ui/collapsible"
import { ComponentTreeActionButton } from "./ComponentTreeActionButton"
import { ComponentTreeIcon } from "./ComponentTreeIcon"
import { GalleriesPanel } from "./galleries/GalleriesPanel"
import {
  createAppGallery,
  galleryTitle,
  readGalleries,
  selectAppGallery,
} from "@/lib/app-galleries"
import { useWorkspaceStore } from "@/lib/workspace-store"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { cn } from "@/lib/utils"

/** Gallery is the only reusable resource; ordinary components remain in the Page tree. */
export function ComponentResourcesTree({
  map,
  selected,
}: {
  map: MapsvgMapInstance | null
  selected: boolean
}) {
  const [open, setOpen] = useState(true)
  const [galleryOpen, setGalleryOpen] = useState(true)
  const session = useWorkspaceStore((state) =>
    map ? state.mapSessions[String(map.id)] : undefined,
  )
  if (!map) return null
  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <div className="flex h-7 min-w-0 items-center rounded-md pl-4 hover:bg-muted/60">
        <button
          type="button"
          aria-label={open ? "Collapse components" : "Expand components"}
          aria-expanded={open}
          className="inline-flex size-5 shrink-0 items-center justify-center"
          onClick={() => setOpen((value) => !value)}
        >
          <ChevronRight className={cn("size-3.5", open && "rotate-90")} />
        </button>
        <button
          type="button"
          className="flex h-full min-w-0 flex-1 items-center gap-1.5 text-left text-xs"
          onClick={() => {
            setOpen(true)
            selectAppGallery(map.id, null)
          }}
        >
          <ComponentTreeIcon kind="components" />
          Components
        </button>
      </div>
      <CollapsibleContent data-slot="component-resources">
        <Collapsible
          open={galleryOpen}
          onOpenChange={setGalleryOpen}
          data-component-folder="gallery"
        >
          <div className="group/folder flex h-7 min-w-0 items-center rounded-md pr-0.5 pl-12 hover:bg-muted/60">
            <button
              type="button"
              aria-label={`${galleryOpen ? "Collapse" : "Expand"} Gallery folder`}
              aria-expanded={galleryOpen}
              className="flex h-full min-w-0 flex-1 items-center gap-1.5 text-left text-xs"
              onClick={() => {
                setGalleryOpen((value) => !value)
                selectAppGallery(map.id, null, "gallery")
              }}
            >
              <ComponentTreeIcon kind="gallery-folder" expanded={galleryOpen} />
              <span>Gallery</span>{!hasProductFeature("gallery") ? <PremiumBadge /> : null}
            </button>
            <ComponentTreeActionButton
              aria-label="Create gallery"
              onClick={() => {
                setGalleryOpen(true)
                if (hasProductFeature("gallery")) createAppGallery(map)
                else selectAppGallery(map.id, null, "gallery")
              }}
              className="text-muted-foreground opacity-0 group-hover/folder:opacity-100 group-focus-within/folder:opacity-100"
            >
              <Plus className="size-3.5" />
            </ComponentTreeActionButton>
          </div>
          <CollapsibleContent>
            {readGalleries(map.options.galleries).map((gallery) => {
              const id = String(gallery.id),
                title = galleryTitle(gallery),
                active = selected && session?.selectedGalleryId === id
              return (
                <button
                  key={id}
                  type="button"
                  aria-label={`Edit gallery ${title}`}
                  aria-current={active ? "page" : undefined}
                  className={cn(
                    "flex h-7 w-full min-w-0 items-center gap-1.5 rounded-md pr-1 pl-16 text-left text-xs",
                    active ? "bg-accent" : "hover:bg-muted/60",
                  )}
                  onClick={() => selectAppGallery(map.id, id)}
                >
                  <ComponentTreeIcon kind="gallery" />
                  <span className="truncate" title={title}>
                    {title}
                  </span>
                </button>
              )
            })}
          </CollapsibleContent>
        </Collapsible>
      </CollapsibleContent>
    </Collapsible>
  )
}

export function ComponentResourcesPanel({ map }: { map: MapsvgMapInstance | null }) {
  return <GalleriesPanel map={map} />
}
