import type { JSX } from "react"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { getSharedExtensionHost } from "@/lib/extensions"

export type ComponentAdminPanelProps = {
  componentId: string
  map: MapsvgMapInstance | null
  controllerKey: string
  omitLayoutPlacement: boolean
}

export type ComponentAdminDefinition = {
  id: string
  Panel: (props: ComponentAdminPanelProps) => JSX.Element | null
}

export function registerComponentAdminDefinition(definition: ComponentAdminDefinition): void {
  getSharedExtensionHost().register("admin.component", definition.id, definition)
}

export function getComponentAdminDefinition(id: string): ComponentAdminDefinition | undefined {
  const host = getSharedExtensionHost()
  host.seal("admin.component")
  return host.get<ComponentAdminDefinition>("admin.component", id)
}
