import { CogIcon, MessageCircleIcon, DatabaseIcon, GitBranchIcon } from "lucide-react"
import type { ReactNode } from "react"
import { Button } from "@/components/ui/button"
import type { SettingsTabDefinition } from "@/lib/admin-extension-registry"
import { cn } from "@/lib/utils"
import { PREMIUM_FEATURES } from "@/lib/premium-features"
import { CHAT_COMPOSER_PLACEHOLDER } from "@/components/ChatComposer"

export const CORE_SETTINGS_TABS: readonly SettingsTabDefinition[] = [
  {
    id: "ai",
    label: "AI",
    icon: MessageCircleIcon,
    order: 10,
    requiresCapability: "ai_assistant",
    premiumFallback: {
      feature: "ai_assistant",
      title: PREMIUM_FEATURES.ai_assistant.title,
      description: PREMIUM_FEATURES.ai_assistant.summary,
      disabledInputPlaceholder: CHAT_COMPOSER_PLACEHOLDER,
    },
    keepMounted: true,
  },
  {
    id: "components",
    label: "Settings",
    icon: CogIcon,
    order: 20,
  },
  { id: "states", label: "Scenes", icon: GitBranchIcon, order: 25 },
  {
    id: "data",
    label: "Data",
    icon: DatabaseIcon,
    order: 30,
  },
]

export type SettingsTabId = string

type Props = {
  tabs: readonly SettingsTabDefinition[]
  value: SettingsTabId
  onValueChange: (value: SettingsTabId) => void
  className?: string
  endActions?: ReactNode
}

/**
 * Horizontal navigation and App actions at the top of the full-height panel.
 * Lite owns its core tabs; paid bundles may register additional leaves before
 * React mounts through the shared admin.navigation extension point.
 */
export function SettingsPanelToolbar({ tabs, value, onValueChange, className, endActions }: Props) {
  return (
    <div
      data-slot="settings-panel-toolbar"
      role="toolbar"
      aria-label="Map editor toolbar"
      className={cn("flex min-h-11 shrink-0 items-center justify-between gap-2 border-b bg-background px-2 py-2", className)}
    >
      <div role="group" aria-label="Editor panels" className="flex shrink-0 items-center gap-1">
        {tabs.filter(tab => tab.id !== "states").map(({ id, label, icon: Icon }) => (
            <Button key={id} type="button" size="sm" variant={value === id ? "secondary" : "ghost"}
              aria-label={label} aria-pressed={value === id} onClick={() => onValueChange(id)}>
              <Icon /><span>{label}</span>
            </Button>
        ))}
      </div>
      {endActions ? <div data-slot="workspace-actions" className="ml-auto flex min-w-0 items-center justify-end">{endActions}</div> : null}
    </div>
  )
}
