import { useMemo, type ReactNode } from "react"
import { AppStatesPanel } from "@/components/states/AppStatesPanel"
import { ComponentsPanel } from "@/components/ComponentsPanel"
import { DataPanel } from "@/components/data/DataPanel"
import { PremiumFeaturePlaceholder } from "@/components/PremiumFeaturePlaceholder"
import {
  CORE_SETTINGS_TABS,
  SettingsPanelToolbar,
  type SettingsTabId,
} from "@/components/SettingsPanelToolbar"
import { TooltipProvider } from "@/components/ui/tooltip"
import {
  getAdminPanelDefinition,
  resolveSettingsTabs,
  type SettingsTabDefinition,
} from "@/lib/admin-extension-registry"
import { hasMapSVGCapability } from "@/lib/extensions"
import { cn } from "@/lib/utils"
import { getAdminParams } from "@/lib/admin-params"
import { useWorkspaceStore } from "@/lib/workspace-store"

type Props = {
  mapId?: number | null
  className?: string
  headerActions?: ReactNode
  contentInert?: boolean
}

function BuiltinSettingsPanel({
  tab,
  mapId,
}: {
  tab: SettingsTabDefinition
  mapId: number | null
}) {
  switch (tab.id) {
    case "components":
      return <ComponentsPanel />
    case "states":
      return <AppStatesPanel mapId={mapId} />
    case "data":
      return <DataPanel mapId={mapId} />
    default:
      return (
        <div className="h-full overflow-y-auto p-3">
          <p className="text-sm text-muted-foreground">{tab.label} — no panel registered.</p>
        </div>
      )
  }
}

function SettingsTabBody({ tab, mapId }: { tab: SettingsTabDefinition; mapId: number | null }) {
  const capabilityMissing =
    tab.requiresCapability != null && !hasMapSVGCapability(tab.requiresCapability)

  if (capabilityMissing) {
    return (
      <PremiumFeaturePlaceholder
        feature={tab.premiumFallback?.feature}
        title={tab.premiumFallback?.title ?? tab.label}
        description={
          tab.premiumFallback?.description ??
          `${tab.label} requires an additional MapSVG capability.`
        }
        disabledInputPlaceholder={tab.premiumFallback?.disabledInputPlaceholder}
      />
    )
  }

  const registered = getAdminPanelDefinition(tab.id)
  if (registered) {
    const Panel = registered.Panel
    return <Panel mapId={mapId} />
  }

  return <BuiltinSettingsPanel tab={tab} mapId={mapId} />
}

/**
 * Full-height settings chrome: horizontal toolbar + tab body.
 *
 * Paid bundles register navigation/panels before React mounts. Lite-owned tabs
 * can remain visible as capability-gated placeholders while their paid panel is
 * absent. keepMounted preserves stateful panels such as AI across tab switches.
 */
export function SettingsPanel({ mapId = null, className, headerActions, contentInert = false }: Props) {
  const tabs = useMemo(() => {
    const definitions = getAdminParams().globalQueriesEnabled
      ? CORE_SETTINGS_TABS.filter((item) => item.id !== "data")
      : CORE_SETTINGS_TABS
    return resolveSettingsTabs(definitions)
  }, [])
  const session = useWorkspaceStore((state) =>
    mapId ? state.mapSessions[String(mapId)] : undefined,
  )
  const patchMapSession = useWorkspaceStore((state) => state.patchMapSession)
  const requestedTab = session?.settingsTab as SettingsTabId | undefined
  const activeTab =
    tabs.find((definition) => definition.id === requestedTab) ?? tabs[0] ?? null

  return (
    <TooltipProvider delayDuration={400}>
      <div className={cn("flex h-full min-h-0 flex-col bg-background", className)}>
        <SettingsPanelToolbar
          tabs={tabs}
          value={activeTab?.id ?? ""}
          endActions={headerActions}
          onValueChange={(next) => {
            if (mapId) patchMapSession(mapId, { settingsTab: next })
          }}
        />
        <div className="relative min-h-0 min-w-0 flex-1 overflow-hidden" inert={contentInert}>
          {tabs
            .filter((definition) => definition.keepMounted || definition.id === activeTab?.id)
            .map((definition) => {
              const hidden = definition.id !== activeTab?.id
              return (
                <div
                  key={definition.id}
                  className={cn(
                    "h-full min-h-0",
                    hidden && "pointer-events-none invisible absolute inset-0",
                  )}
                  aria-hidden={hidden}
                >
                  <SettingsTabBody tab={definition} mapId={mapId} />
                </div>
              )
            })}
        </div>
      </div>
    </TooltipProvider>
  )
}
