import { componentBindingRole, readPageBinding } from "../../../../../mapsvg/Map/pageBindings"
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { getAdminMapInstance, subscribeAdminMapInstance } from "@/lib/apply-options-patch"
import { subscribeLiveMapOptions } from "@/lib/live-map-options"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import type { SchemaBuilderSaveState } from "@/components/form-builder/schema-builder/SchemaBuilder"
import { MapFilterFieldsBuilder, type FilterRuntime } from "./MapFilterFieldsBuilder"

function readOwner(map: MapsvgMapInstance) {
  const runtime = map as FilterRuntime
  const source = componentBindingRole(runtime.options, "filters")
  return { map, source, binding: JSON.stringify([map.activePageId, readPageBinding(map.options, source, map.activePageId)]), repository: source === "regions" ? runtime.regionsRepository : runtime.objectsRepository }
}
type Owner = ReturnType<typeof readOwner>

export function MapFilterFormDialog({ map }: { map: MapsvgMapInstance | null }) {
  const formId = `map-filter-form-${useId()}`
  const [owner, setOwner] = useState<Owner | null>(null)
  const ownerRef = useRef<Owner | null>(null)
  const [saveState, setSaveState] = useState<SchemaBuilderSaveState>({ dirty: false, valid: false })

  const close = useCallback(() => {
    // Retire callbacks synchronously, before the dialog's unmount/render.
    ownerRef.current = null
    setOwner(null)
    setSaveState({ dirty: false, valid: false })
  }, [])
  const isCurrentOwner = useCallback(() => {
    const current = ownerRef.current
    if (!current || getAdminMapInstance() !== current.map) return false
    const live = readOwner(current.map)
    return live.source === current.source && live.repository === current.repository && live.binding === current.binding
  }, [])

  useLayoutEffect(() => {
    if (ownerRef.current && ownerRef.current.map !== map) close()
  }, [map, close])
  useLayoutEffect(() => () => { ownerRef.current = null }, [])
  useEffect(() => {
    const checkOwner = () => {
      if (ownerRef.current && !isCurrentOwner()) close()
    }
    const unsubscribeOptions = subscribeLiveMapOptions(checkOwner)
    const unsubscribeMap = subscribeAdminMapInstance(checkOwner)
    return () => { unsubscribeOptions(); unsubscribeMap() }
  }, [close, isCurrentOwner])

  return (
    <Dialog open={owner != null} onOpenChange={(open) => {
      if (!open) { close(); return }
      if (!map || getAdminMapInstance() !== map) return
      const next = readOwner(map)
      ownerRef.current = next
      setOwner(next)
      setSaveState({ dirty: false, valid: false })
    }}>
      <DialogTrigger asChild>
        <Button type="button" variant="outline" disabled={!map}>Edit form</Button>
      </DialogTrigger>
      <DialogContent
        data-slot="map-filter-form-dialog"
        showCloseButton={false}
        aria-describedby={undefined}
        // In the editor ShadowRoot, document listeners see its host as the event
        // target. Radix's scroll lock mistakes these events for outside scrolling.
        // Keep native scrolling inside the modal without reaching that listener.
        onWheel={(event) => event.stopPropagation()}
        onTouchMove={(event) => event.stopPropagation()}
        className="h-[calc(100%-2rem)] w-[calc(100%-2rem)] max-w-none grid-rows-[auto_minmax(0,1fr)_auto] gap-0 overflow-hidden p-0 sm:max-w-none"
      >
        <DialogHeader className="border-b p-4">
          <DialogTitle>Edit filter form</DialogTitle>
        </DialogHeader>
        <div className="flex min-h-0 min-w-0 overflow-hidden">
          {owner ? <MapFilterFieldsBuilder
            map={owner.map}
            formId={formId}
            showSaveButton={false}
            onSaveStateChange={setSaveState}
            isCurrentOwner={isCurrentOwner}
            onSaved={close}
          /> : null}
        </div>
        <DialogFooter data-slot="map-filter-form-footer" className="sticky bottom-0 border-t bg-background p-4">
          <Button type="button" variant="outline" onClick={close}>Close</Button>
          <Button type="submit" form={formId} disabled={!saveState.dirty || !saveState.valid}>Save</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
