import { PanelLeftIcon } from "lucide-react"
import { useState, type ReactNode } from "react"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

export type AdminBreadcrumb = {
  label: string
  icon?: ReactNode
  onClick?: () => void
}

type Props = {
  /**
   * Shell path: top > … > current (e.g. Components > Views > Tooltip).
   * Last item is the current page.
   */
  breadcrumbs: AdminBreadcrumb[]
  /**
   * Optional nav/list sidebar. When provided, a collapse toggle is injected
   * into the shell toolbar automatically.
   */
  sidebar?: ReactNode
  sidebarCollapsed?: boolean
  defaultSidebarCollapsed?: boolean
  onSidebarCollapsedChange?: (collapsed: boolean) => void
  /** Optional actions on the right of the shell toolbar (e.g. New Chat). */
  toolbarEnd?: ReactNode
  /** Controller(s) — typically a ControllerView. */
  children?: ReactNode
  className?: string
}

function AdminToolbarBreadcrumbs({ items }: { items: AdminBreadcrumb[] }) {
  if (items.length === 0) return null

  return (
    <Breadcrumb>
      <BreadcrumbList className="flex-nowrap sm:gap-1.5">
        {items.map((item, index) => {
          const isLast = index === items.length - 1
          const content = <>{item.icon}<span className="truncate">{item.label}</span></>
          return (
            <span key={`${item.label}-${index}`} className="contents">
              {index > 0 ? <BreadcrumbSeparator /> : null}
              <BreadcrumbItem className="min-w-0">
                {item.onClick ? (
                  <button
                    type="button"
                    onClick={item.onClick}
                    aria-current={isLast ? "page" : undefined}
                    className={cn(
                      "inline-flex min-w-0 items-center gap-1.5 hover:text-foreground hover:underline",
                      isLast ? "font-medium text-foreground" : "text-muted-foreground",
                    )}
                  >
                    {content}
                  </button>
                ) : isLast ? (
                  <BreadcrumbPage className="inline-flex min-w-0 items-center gap-1.5 font-medium">
                    {content}
                  </BreadcrumbPage>
                ) : (
                  <span className="inline-flex min-w-0 items-center gap-1.5 text-muted-foreground">
                    {content}
                  </span>
                )}
              </BreadcrumbItem>
            </span>
          )
        })}
      </BreadcrumbList>
    </Breadcrumb>
  )
}

/**
 * Abstract module shell: optional sidebar + breadcrumbs toolbar + controller slot.
 * Controllers own their own toolbars via ControllerView (no breadcrumbs there).
 * Shell-level actions use `toolbarEnd` (same slot idea as ControllerView).
 */
export function AdminView({
  breadcrumbs,
  sidebar,
  sidebarCollapsed: sidebarCollapsedProp,
  defaultSidebarCollapsed = false,
  onSidebarCollapsedChange,
  toolbarEnd,
  children,
  className,
}: Props) {
  const hasSidebar = sidebar != null
  const [uncontrolledCollapsed, setUncontrolledCollapsed] = useState(
    defaultSidebarCollapsed,
  )
  const collapsed =
    sidebarCollapsedProp !== undefined
      ? sidebarCollapsedProp
      : uncontrolledCollapsed

  const setCollapsed = (next: boolean) => {
    if (sidebarCollapsedProp === undefined) {
      setUncontrolledCollapsed(next)
    }
    onSidebarCollapsedChange?.(next)
  }

  return (
    <div data-slot="admin-view" className={cn("flex h-full min-h-0 min-w-0 max-w-full bg-background", className)}>
      {hasSidebar ? (
        <aside
          className={cn(
            "shrink-0 overflow-y-auto border-r border-border transition-[width,opacity] duration-200",
            collapsed
              ? "w-0 overflow-hidden border-r-0 opacity-0"
              : "w-56 opacity-100",
          )}
          aria-hidden={collapsed}
        >
          <div className="w-56 p-2">{sidebar}</div>
        </aside>
      ) : null}

      <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
        <header data-slot="admin-toolbar" className="flex h-8 shrink-0 items-center gap-1.5 border-b border-border px-2">
          {hasSidebar ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="outline"
                  size="icon-xs"
                  className="size-6 shrink-0"
                  aria-label={
                    collapsed ? "Expand sidebar" : "Collapse sidebar"
                  }
                  aria-pressed={collapsed}
                  onClick={() => setCollapsed(!collapsed)}
                >
                  <PanelLeftIcon />
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom">
                {collapsed ? "Expand sidebar" : "Collapse sidebar"}
              </TooltipContent>
            </Tooltip>
          ) : null}
          <div className="min-w-0 flex-1">
            <AdminToolbarBreadcrumbs items={breadcrumbs} />
          </div>
          {toolbarEnd ? (
            <div className="flex shrink-0 items-center gap-1 [&_[data-slot=button]]:h-6! [&_[data-slot=button]]:px-2! [&_[data-slot=select-trigger]]:h-6!">{toolbarEnd}</div>
          ) : null}
        </header>

        <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
          {children}
        </div>
      </div>
    </div>
  )
}
