import { componentBindingRole } from "../../../../mapsvg/Map/pageBindings"
import { useEffect, useState } from "react"
import { Field, FieldContent, FieldDescription, FieldLabel } from "@/components/ui/field"
import { FormBuilderChoice } from "@/components/form-builder/FormBuilderChoice"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { subscribeLiveMapOptions, useAdminMap } from "@/lib/live-map-options"
import { appEditingPageId } from "@/lib/app-state-editor"
import type { SettingsFieldContext } from "@/lib/settings-form/types"
import type { FormFieldData } from "../../../../mapsvg/FormBuilder/FieldDefinitions"
import { filterSourceFields } from "./filter-fields/model"
import { loadPostFilterFields } from "./filter-fields/post-filter-fields"

type Props = { ctx: SettingsFieldContext; eventPath: string; option: string; label: string }

/** Action paths use the runtime's Region/Object prefixes, including linked sources. */
export function ActionFieldPicker({ ctx, eventPath, option, label }: Props) {
  const map = useAdminMap()
  const [, refresh] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => refresh(value => value + 1)), [])
  const pageId = appEditingPageId(map)
  const runtime = map as typeof map & {
    regionsRepository?: { getSchema: () => { getFields: () => FormFieldData[]; postType?: string } }
    objectsRepository?: { getSchema: () => { getFields: () => FormFieldData[]; postType?: string } }
  }
  const regions = runtime?.regionsRepository, objects = runtime?.objectsRepository
  const regionOnly = eventPath === "directoryItem.click" && componentBindingRole(map?.options, "directory") === "regions"
  const sources = [
    ...(eventPath !== "marker.click" ? [{ source: "regions" as const, repository: regions }] : []),
    ...(!regionOnly ? [{ source: "objects" as const, repository: objects }] : []),
  ]
  // Schemas may be replaced on the same repository instance; retire its old catalog too.
  const sourceKey = JSON.stringify(sources.map(({ source, repository }) => ({
    source, fields: repository?.getSchema().getFields(), postType: repository?.getSchema().postType,
  })))
  const fields = sources.flatMap(({ source, repository }) => {
    const fields = repository?.getSchema().getFields() ?? []
    const prefix = source === "regions" ? "Region" : "Object"
    return [
      ...filterSourceFields(fields, source),
      ...fields.filter(field => field.type === "post").map(field => ({
        value: `${prefix}.post.url`, label: `Post URL (${prefix}.post.url)`, field,
      })),
    ]
  })
  const [catalog, setCatalog] = useState<{ key: string; owner: typeof map; pageId: ReturnType<typeof appEditingPageId>; fields: typeof fields; error: boolean } | null>(null)
  useEffect(() => {
    let active = true
    void Promise.allSettled(sources.map(({ source, repository }) => {
      const schema = repository?.getSchema()
      const fields = schema?.getFields() ?? []
      return fields.some(field => field.type === "post") ? loadPostFilterFields(fields, source, schema?.postType) : []
    })).then(groups => {
      if (active) setCatalog({ key: sourceKey, owner: map, pageId,
        fields: groups.flatMap(group => group.status === "fulfilled" ? group.value : []),
        error: groups.some(group => group.status === "rejected"),
      })
    })
    return () => { active = false }
  }, [map, regions, objects, regionOnly, pageId, sourceKey])
  const path = `${eventPath}.${option}`, value = String(ctx.getValue(path) ?? "")
  const currentCatalog = catalog?.key === sourceKey && catalog.owner === map && catalog.pageId === pageId ? catalog : null
  const options = [...new Map([...fields, ...(currentCatalog?.fields ?? [])].map(({ value, label }) => [value, { value, label }])).values()]
  // A removed or temporarily unavailable source must not erase an authored path.
  if (value && !options.some(item => item.value === value)) options.push({ value, label: value })
  return <Field><FieldContent>
    <FieldLabel htmlFor={path}>{label}</FieldLabel>
    <FormBuilderChoice id={path} aria-label={label} value={value} options={options} emptyLabel="Choose a field"
      onValueChange={value => {
        if (map && getAdminMapInstance() === map && appEditingPageId(map) === pageId) ctx.setValue(path, value)
      }} />
    {currentCatalog?.error ? <FieldDescription>Could not load WordPress post fields. Reopen this panel to retry.</FieldDescription> : null}
  </FieldContent></Field>
}
