import { Link, Unlink } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Field, FieldLabel } from "@/components/ui/field"
import { InputGroup, InputGroupAddon, InputGroupInput, InputGroupText } from "@/components/ui/input-group"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { useAdminMap } from "@/lib/live-map-options"
import type { SettingsFieldContext } from "@/lib/settings-form/types"

export function MapSizeControls({ ctx }: { ctx: SettingsFieldContext }) {
  const map = useAdminMap()
  const locked = Boolean(ctx.values.lockAspectRatio)
  const change = (dimension: "width" | "height", value: string) => {
    const next = { ...ctx.values, [dimension]: value }
    const width = Number(map?.svgDefault?.width ?? ctx.values.width)
    const height = Number(map?.svgDefault?.height ?? ctx.values.height)
    const numeric = Number(value)
    if (locked && numeric > 0 && Number.isFinite(numeric) && width > 0 && height > 0) {
      if (dimension === "width") next.height = Math.max(1, Math.round(numeric * height / width))
      else next.width = Math.max(1, Math.round(numeric * width / height))
    }
    ctx.setValues(next)
  }
  const input = (dimension: "width" | "height", label: string) => (
    <InputGroup className="min-w-0 flex-1">
      <InputGroupAddon><InputGroupText>{label}</InputGroupText></InputGroupAddon>
      <InputGroupInput id={dimension} aria-label={dimension === "width" ? "Width" : "Height"}
        inputMode="decimal" value={String(ctx.values[dimension] ?? "")}
        onChange={event => change(dimension, event.target.value)} />
    </InputGroup>
  )
  return (
    <Field data-slot="map-size-controls">
      <FieldLabel className="text-[11px] font-normal text-foreground/55">Size</FieldLabel>
      <div className="flex min-w-0 items-center gap-1">
        {input("width", "W")}
        <Tooltip>
          <TooltipTrigger asChild>
            <Button type="button" size="icon" variant="ghost" className="shrink-0"
              aria-label="Lock aspect ratio" aria-pressed={locked}
              onClick={() => ctx.setValue("lockAspectRatio", !locked)}>
              {locked ? <Link data-slot="aspect-ratio-linked" /> : <Unlink data-slot="aspect-ratio-unlinked" />}
            </Button>
          </TooltipTrigger>
          <TooltipContent>{locked ? "Unlock aspect ratio" : "Lock aspect ratio"}</TooltipContent>
        </Tooltip>
        {input("height", "H")}
      </div>
    </Field>
  )
}
