import { useCallback, useEffect, useState } from "react"
import { SettingsForm } from "@/components/settings-form/SettingsForm"
import {
  LOCATIONS_CONNECTIONS_DEFAULTS,
  locationsConnectionsSchema,
} from "@/components/settings/locationsConnectionsSchema"
import {
  REGIONS_CONNECTIONS_DEFAULTS,
  regionsConnectionsSchema,
} from "@/components/settings/regionsConnectionsSchema"
import { getAdminMapInstance, subscribeAdminMapInstance } from "@/lib/apply-options-patch"
import { mergeOptionsSlice, patchLiveMapOptions, readLiveDatabase } from "@/lib/live-map-options"
import type { DataSourceRole } from "@/components/data/dataNav"

type Props = {
  role: DataSourceRole
}

function readRegionsValues(): Record<string, unknown> {
  const map = getAdminMapInstance()
  return mergeOptionsSlice(REGIONS_CONNECTIONS_DEFAULTS, map?.options)
}

function readObjectsValues(): Record<string, unknown> {
  const map = getAdminMapInstance()
  return mergeOptionsSlice(LOCATIONS_CONNECTIONS_DEFAULTS, readLiveDatabase(map))
}

/**
 * Existing map query/config options, relocated from the retired Connections tab.
 *
 * This deliberately keeps the old option paths and write behavior. #122 changes
 * where these controls live, not the underlying map/query persistence model.
 */
export function DataQuerySettings({ role }: Props) {
  const [regionsValues, setRegionsValues] = useState(readRegionsValues)
  const [objectsValues, setObjectsValues] = useState(readObjectsValues)

  useEffect(() => {
    return subscribeAdminMapInstance(() => {
      setRegionsValues(readRegionsValues())
      setObjectsValues(readObjectsValues())
    })
  }, [])

  const onRegionsChange = useCallback((next: Record<string, unknown>) => {
    setRegionsValues(next)
    const {
      regionsAutoRefetch,
      regionsDynamicStatusOrder,
      statusSyncOn,
      statusSyncSource,
      statusSyncField,
      statusSyncMultiStrategy,
      regionsDynamicStatus,
    } = next

    patchLiveMapOptions({
      regionsAutoRefetch,
      regionsDynamicStatusOrder,
      statusSyncOn,
      statusSyncSource,
      statusSyncField,
      statusSyncMultiStrategy,
      regionsDynamicStatus,
    })
  }, [])

  const onObjectsChange = useCallback((next: Record<string, unknown>) => {
    setObjectsValues(next)
    const { loadOnStart, noFiltersNoLoad, autoRefetch } = next

    patchLiveMapOptions({
      database: {
        loadOnStart,
        noFiltersNoLoad,
        autoRefetch,
      },
    })
  }, [])

  return role === "regions" ? (
    <SettingsForm
      schema={regionsConnectionsSchema}
      values={regionsValues}
      onChange={onRegionsChange}
    />
  ) : (
    <SettingsForm
      schema={locationsConnectionsSchema}
      values={objectsValues}
      onChange={onObjectsChange}
    />
  )
}
