import { useEffect, useState } from "react"
import { Button } from "@/components/ui/button"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import { patchLiveMapOptions, subscribeLiveMapOptions, useAdminMap } from "@/lib/live-map-options"

export function MapPositionControls() {
  const map = useAdminMap()
  const [, refresh] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => refresh(tick => tick + 1)), [])
  const initial = map?.getViewBoxByState?.("custom")
  const available = Boolean(map?.getViewBox && map?.viewBoxReset)
  return (
    <Field data-slot="map-position-controls">
      <FieldLabel className="text-[11px] font-normal text-foreground/55">Initial position</FieldLabel>
      <FieldDescription>Pan and zoom the preview, then save its position for when the map opens.</FieldDescription>
      {initial ? <div className="text-xs text-muted-foreground">Center: {Number((initial.x + initial.width / 2).toFixed(2))}, {Number((initial.y + initial.height / 2).toFixed(2))}</div> : null}
      <div className="flex min-w-0 flex-wrap gap-2">
        <Button type="button" variant="outline" disabled={!available} onClick={() => {
          const position = map?.getViewBox?.()
          if (position) patchLiveMapOptions({ initialViewBox: position.toArray() })
        }}>Set current position as initial</Button>
        <Button type="button" variant="outline" disabled={!available} onClick={() => {
          map?.viewBoxReset?.("custom")
          patchLiveMapOptions({})
        }}>Go to initial position</Button>
        <Button type="button" variant="outline" disabled={!available} onClick={() => {
          const position = map?.viewBoxReset?.("initial")
          if (position) patchLiveMapOptions({ initialViewBox: position.toArray() })
        }}>Reset position</Button>
      </div>
    </Field>
  )
}
