import { useEffect, useMemo, useState } from "react"
import { AdminView, type AdminBreadcrumb } from "@/components/AdminView"
import { MAP_SETTINGS_NAV_ITEMS } from "@/components/componentsNav"
import { ComponentSettingsBody } from "@/components/settings/ComponentSettingsBody"
import { NodeSettingsBody } from "@/components/settings/NodeSettingsBody"
import { SceneSettingsBody } from "@/components/settings/SceneSettingsBody"
import { ScenesLayersSidebar } from "@/components/settings/ScenesLayersSidebar"
import { previewSessionLayoutBreakpoint } from "@/lib/preview-canvas"
import { useAdminMap, subscribeLiveMapOptions } from "@/lib/live-map-options"
import { buildParentIndex, nodeById, readNodes, readScenes, sceneById } from "@/lib/nodes-admin"
import { appPageLabel } from "@/lib/app-page-label"
import { appEditingPageId, getAppStateEditor } from "@/lib/app-state-editor"
import { pageNodeIds } from "@/lib/app-page-context"
import { scenePointId } from "@/lib/app-state-graph"
import { cn } from "@/lib/utils"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { galleryTitle, readGalleries, selectAppGallery } from "@/lib/app-galleries"
import { ComponentResourcesPanel } from "./settings/ComponentResources"
import { ComponentTreeIcon, LayerTypeIcon } from "./settings/ComponentTreeIcon"

type Props = {
  className?: string
}

/** Components tab: Pages/Layers + node settings. Internal scene identities remain stable. */
export function ComponentsPanel({ className }: Props) {
  const map = useAdminMap()
  const [optionsTick, setOptionsTick] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => setOptionsTick((n) => n + 1)), [])
  const nodes = useMemo(() => {
    void optionsTick
    return readNodes(map)
  }, [map, optionsTick])
  const mapId = map?.id ? Number(map.id) : null
  const session = useWorkspaceStore((state) =>
    mapId ? state.mapSessions[String(mapId)] : undefined,
  )
  const patchMapSession = useWorkspaceStore((state) => state.patchMapSession)
  const scenes = useMemo(() => {
    void optionsTick
    return readScenes(map)
  }, [map, optionsTick])
  const pageId = appEditingPageId(map)
  const pageNodes = map && pageId ? pageNodeIds(map.options, pageId) : null
  const editableNodes = nodes.filter(node => !pageNodes || pageNodes.has(node.id))
  const defaultNodeId = nodeById(editableNodes, "Main")
    ? "Main"
    : nodeById(editableNodes, "map")
      ? "map"
      : (editableNodes[0]?.id ?? null)
  const requestedSceneId = session?.selectedSceneId ?? null
  const selectedComponent = MAP_SETTINGS_NAV_ITEMS.find(
    (item) => item.id === session?.selectedComponentId,
  )
  const selectedComponentId = selectedComponent?.id ?? null
  const selectedSceneId =
    !selectedComponentId && requestedSceneId && requestedSceneId === pageId && sceneById(scenes, requestedSceneId)
      ? requestedSceneId
      : null
  const requestedNodeId = session?.selectedNodeId
  const selectedNodeId = selectedComponentId || selectedSceneId
    ? null
    : requestedNodeId && nodeById(editableNodes, requestedNodeId)
      ? requestedNodeId
      : defaultNodeId
  const resolvedScene = useMemo(
    () => (selectedSceneId ? sceneById(scenes, selectedSceneId) : undefined),
    [scenes, selectedSceneId],
  )

  const resolved = useMemo(
    () => (selectedNodeId ? nodeById(nodes, selectedNodeId) : undefined),
    [selectedNodeId, nodes],
  )

  const selectNode = (nodeId: string) => {
    if (!nodeById(editableNodes, nodeId)) return
    if (mapId) patchMapSession(mapId, {
      selectedNodeId: nodeId, selectedSceneId: null, selectedComponentId: null,
    })
  }

  const selectScene = (sceneId: string) => {
    if (map && sceneId !== pageId) getAppStateEditor(map).select(scenePointId(sceneId))
    if (mapId) patchMapSession(mapId, {
      selectedSceneId: sceneId, selectedNodeId: null, selectedComponentId: null,
    })
  }

  const editInteractions = (nodeId: string) => {
    if (!nodeById(editableNodes, nodeId)) return
    if (mapId) patchMapSession(mapId, {
      selectedNodeId: nodeId, selectedSceneId: null, selectedComponentId: null,
      componentMode: "interactions",
    })
  }

  const selectComponent = (componentId: string) => {
    if (mapId) patchMapSession(mapId, {
      selectedComponentId: componentId, selectedNodeId: null, selectedSceneId: null,
    })
  }

  const breadcrumbs: AdminBreadcrumb[] = []
  if (selectedComponent) {
    if (selectedComponent.id === "gallery" || selectedComponent.id === "components") {
      breadcrumbs.push({
        label: "Components", icon: <ComponentTreeIcon kind="components" />,
        onClick: () => { if (mapId) selectAppGallery(mapId, null) },
      })
      const gallery = readGalleries(map?.options.galleries).find(item => String(item.id) === session?.selectedGalleryId)
      if (gallery || selectedComponent.id === "gallery") breadcrumbs.push({
        label: "Gallery", icon: <ComponentTreeIcon kind="gallery-folder" />,
        onClick: () => { if (mapId) selectAppGallery(mapId, null, "gallery") },
      })
      if (gallery) breadcrumbs.push({
        label: galleryTitle(gallery), icon: <ComponentTreeIcon kind="gallery" />,
        onClick: () => { if (mapId) selectAppGallery(mapId, gallery.id) },
      })
    } else breadcrumbs.push({
      label: selectedComponent.label, icon: <ComponentTreeIcon kind="app" />,
      onClick: () => selectComponent(selectedComponent.id),
    })
  } else if (resolvedScene) {
    breadcrumbs.push({
      label: appPageLabel(resolvedScene), icon: <ComponentTreeIcon kind="page" />,
      onClick: () => selectScene(resolvedScene.id),
    })
  } else if (resolved) {
    const parents = buildParentIndex(nodes)
    const seen = new Set<string>()
    let node: typeof resolved | undefined = resolved
    while (node && !seen.has(node.id)) {
      const nodeId = node.id
      seen.add(nodeId)
      breadcrumbs.unshift({
        label: node.title || nodeId, icon: <LayerTypeIcon node={node} />,
        onClick: () => selectNode(nodeId),
      })
      if (node.type === "slot") break
      const parentId = parents.get(nodeId)
      node = parentId ? nodeById(nodes, parentId) : undefined
    }
  }

  return (
    <AdminView
      className={cn("h-full", className)}
      breadcrumbs={breadcrumbs}
      sidebar={
        <ScenesLayersSidebar
          layoutBreakpoint={previewSessionLayoutBreakpoint(session)}
          selectedNodeId={selectedNodeId}
          selectedSceneId={selectedSceneId}
          selectedComponentId={selectedComponentId}
          onSelectNode={selectNode}
          onEditInteractions={editInteractions}
          onSelectScene={selectScene}
          onSelectComponent={selectComponent}
        />
      }
    >
      {selectedComponentId === "components" || selectedComponentId === "gallery" ? <ComponentResourcesPanel map={map}/> : selectedComponentId ? (
        <ComponentSettingsBody componentId={selectedComponentId} />
      ) : selectedSceneId ? (
        <SceneSettingsBody sceneId={selectedSceneId} />
      ) : (
        <NodeSettingsBody nodeId={selectedNodeId} />
      )}
    </AdminView>
  )
}
