import { schemaDisplayTitle, type DataSchema } from "@/lib/mapsvg-api"

export type DataSourceRole = "objects" | "regions"
export type BuiltInDataQueryId = "getObjects" | "getRegions"

export type DataSelection =
  | { kind: "source"; schemaId: string }
  | { kind: "query"; schemaId: string; queryId: BuiltInDataQueryId }
  | { kind: "savedQuery"; schemaId: string; savedQueryId: string }

export type BuiltInDataQuery = {
  id: BuiltInDataQueryId
  label: string
  role: DataSourceRole
}

const QUERY_BY_ROLE: Record<DataSourceRole, BuiltInDataQuery> = {
  objects: { id: "getObjects", label: "getObjects", role: "objects" },
  regions: { id: "getRegions", label: "getRegions", role: "regions" },
}

export function builtInQueryForRole(role: DataSourceRole | undefined): BuiltInDataQuery | null {
  return role ? QUERY_BY_ROLE[role] : null
}

export function sourceLabel(schema: DataSchema, role?: DataSourceRole): string {
  if (role === "objects") return "Objects"
  if (role === "regions") return "Regions"
  return schemaDisplayTitle(schema)
}

export function isSelectionForSource(selection: DataSelection | null, schemaId: string): boolean {
  return selection?.kind === "source" && selection.schemaId === schemaId
}

export function isSelectionForQuery(
  selection: DataSelection | null,
  schemaId: string,
  queryId: BuiltInDataQueryId,
): boolean {
  return (
    selection?.kind === "query" && selection.schemaId === schemaId && selection.queryId === queryId
  )
}

export function isSelectionForSavedQuery(
  selection: DataSelection | null,
  schemaId: string,
  queryId: string,
): boolean {
  return (
    selection?.kind === "savedQuery" &&
    selection.schemaId === schemaId &&
    selection.savedQueryId === queryId
  )
}
