import { useEffect, useMemo, useState } from "react"
import { ChevronRight, Code2, FileSearch2, ListIcon, PlusIcon, Search, Table2 } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import type { DataSchema } from "@/lib/mapsvg-api"
import { cn } from "@/lib/utils"
import type { SavedDataQuery } from "@/components/data/savedDataQueries"
import {
  builtInQueryForRole,
  isSelectionForQuery,
  isSelectionForSavedQuery,
  isSelectionForSource,
  sourceLabel,
  type BuiltInDataQueryId,
  type DataSelection,
  type DataSourceRole,
} from "@/components/data/dataNav"

type Props = {
  schemas: DataSchema[]
  connectedIds: Set<string>
  sourceRoles: Map<string, DataSourceRole>
  savedQueries: SavedDataQuery[]
  canUseV2: boolean
  selection: DataSelection | null
  browsedSchemaId?: string | null
  onSelectSource: (id: string) => void
  onSelectQuery: (schemaId: string, queryId: BuiltInDataQueryId) => void
  onSelectSavedQuery: (schemaId: string, queryId: string) => void
  onCreateQuery: (schemaId: string) => void
  onBrowseAll: () => void
  className?: string
}

function SourceTreeItem({
  schema,
  role,
  connected,
  savedQueries,
  canUseV2,
  selection,
  onSelectSource,
  onSelectQuery,
  onSelectSavedQuery,
  onCreateQuery,
}: {
  schema: DataSchema
  role?: DataSourceRole
  connected: boolean
  savedQueries: SavedDataQuery[]
  canUseV2: boolean
  selection: DataSelection | null
  onSelectSource: () => void
  onSelectQuery: (queryId: BuiltInDataQueryId) => void
  onSelectSavedQuery: (queryId: string) => void
  onCreateQuery: () => void
}) {
  const query = builtInQueryForRole(role)
  const sourceId = String(schema.id)
  const sourceSelected = isSelectionForSource(selection, sourceId)
  const querySelected = query != null && isSelectionForQuery(selection, sourceId, query.id)
  const sourceQueries = savedQueries.filter(
    (saved) => saved.schemaId === sourceId && saved.sourceRole === role,
  )
  const savedSelected = sourceQueries.some((saved) =>
    isSelectionForSavedQuery(selection, sourceId, saved.id),
  )
  const [open, setOpen] = useState(true)

  useEffect(() => {
    if (sourceSelected || querySelected || savedSelected) setOpen(true)
  }, [querySelected, savedSelected, sourceSelected])

  return (
    <div className="min-w-0">
      <div className="group flex min-w-0 items-center rounded-md hover:bg-accent hover:text-accent-foreground">
        <button
          type="button"
          className="flex size-7 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:text-foreground"
          aria-label={(open ? "Collapse " : "Expand ") + sourceLabel(schema, role)}
          aria-expanded={open}
          onClick={() => setOpen((value) => !value)}
        >
          <ChevronRight className={cn("size-3.5 transition-transform", open && "rotate-90")} />
        </button>

        <button
          type="button"
          onClick={() => setOpen((value) => !value)}
          className="flex min-w-0 flex-1 items-center gap-2 py-1.5 pr-2 text-left text-sm"
          title={schema.name}
        >
          <Table2 className="size-3.5 shrink-0 text-muted-foreground" />
          <span className="min-w-0 flex-1 truncate">{sourceLabel(schema, role)}</span>
          {connected ? (
            <Badge variant="secondary" className="shrink-0 px-1.5 text-[10px]">
              Map
            </Badge>
          ) : null}
        </button>
      </div>

      {open ? (
        <div className="ml-3.5 border-l border-border pl-3">
          <button
            type="button"
            onClick={onSelectSource}
            className={cn(
              "flex w-full min-w-0 items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground",
              sourceSelected && "bg-accent font-medium text-accent-foreground",
            )}
          >
            <ListIcon className="size-3.5 shrink-0" />
            <span className="truncate">All rows</span>
          </button>

          {query ? (
            <button
              type="button"
              onClick={() => onSelectQuery(query.id)}
              className={cn(
                "flex w-full min-w-0 items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground",
                querySelected && "bg-accent font-medium text-accent-foreground",
              )}
            >
              <Code2 className="size-3.5 shrink-0" />
              <span className="truncate font-mono text-xs">{query.label}</span>
            </button>
          ) : null}

          {canUseV2
            ? sourceQueries.map((saved) => (
                <button
                  key={saved.id}
                  type="button"
                  onClick={() => onSelectSavedQuery(saved.id)}
                  className={cn(
                    "flex w-full min-w-0 items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground",
                    isSelectionForSavedQuery(selection, sourceId, saved.id) &&
                      "bg-accent font-medium text-accent-foreground",
                  )}
                  title={saved.name}
                >
                  <FileSearch2 className="size-3.5 shrink-0" />
                  <span className="truncate">{saved.name}</span>
                </button>
              ))
            : null}

          {canUseV2 && connected && role ? (
            <button
              type="button"
              onClick={onCreateQuery}
              className="flex w-full min-w-0 items-center gap-2 rounded-md px-2 py-1.5 text-left text-xs text-muted-foreground hover:bg-accent hover:text-accent-foreground"
            >
              <PlusIcon className="size-3.5 shrink-0" />
              <span className="truncate">New query</span>
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

/** Map-scoped Data navigation with built-in and saved query nodes. */
export function DataSourcesSidebar({
  schemas,
  connectedIds,
  sourceRoles,
  savedQueries,
  canUseV2,
  selection,
  browsedSchemaId,
  onSelectSource,
  onSelectQuery,
  onSelectSavedQuery,
  onCreateQuery,
  onBrowseAll,
  className,
}: Props) {
  const schemaById = useMemo(
    () => new Map(schemas.map((schema) => [String(schema.id), schema])),
    [schemas],
  )

  const connected = useMemo(
    () => schemas.filter((schema) => connectedIds.has(String(schema.id))),
    [schemas, connectedIds],
  )

  const browsed =
    browsedSchemaId && !connectedIds.has(browsedSchemaId)
      ? (schemaById.get(browsedSchemaId) ?? null)
      : null

  return (
    <nav className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-col gap-0.5">
        <div className="px-2 py-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
          Sources
        </div>

        {connected.length === 0 ? (
          <p className="px-2 py-1 text-xs text-muted-foreground">No connected sources</p>
        ) : (
          connected.map((schema) => {
            const id = String(schema.id)
            return (
              <SourceTreeItem
                key={id}
                schema={schema}
                role={sourceRoles.get(id)}
                connected
                savedQueries={savedQueries}
                canUseV2={canUseV2}
                selection={selection}
                onSelectSource={() => onSelectSource(id)}
                onSelectQuery={(queryId) => onSelectQuery(id, queryId)}
                onSelectSavedQuery={(queryId) => onSelectSavedQuery(id, queryId)}
                onCreateQuery={() => onCreateQuery(id)}
              />
            )
          })
        )}
      </div>

      {browsed ? (
        <div className="flex flex-col gap-0.5">
          <div className="px-2 py-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
            Browsing
          </div>
          <SourceTreeItem
            schema={browsed}
            role={sourceRoles.get(String(browsed.id))}
            connected={false}
            savedQueries={[]}
            canUseV2={false}
            selection={selection}
            onSelectSource={() => onSelectSource(String(browsed.id))}
            onSelectQuery={(queryId) => onSelectQuery(String(browsed.id), queryId)}
            onSelectSavedQuery={() => undefined}
            onCreateQuery={() => undefined}
          />
        </div>
      ) : null}

      <button
        type="button"
        onClick={onBrowseAll}
        className="flex items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground"
      >
        <Search className="size-3.5" />
        <span>Browse all sources…</span>
      </button>
    </nav>
  )
}
