import { useEffect, useMemo, useState } from "react"
import { ChevronDown, ChevronRight, Copy, MoreHorizontal, Pencil, Plus, RotateCcw, Star } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { getAppStateEditor } from "@/lib/app-state-editor"
import { ROOT_STATE, scenePointId } from "@/lib/app-state-graph"
import { appPageLabel } from "@/lib/app-page-label"
import { useAdminMap } from "@/lib/live-map-options"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { cn } from "@/lib/utils"

type Action = { id: string; kind: "add" | "rename" }

function StateTree({ map }: { map: MapsvgMapInstance }) {
  const editor = useMemo(() => getAppStateEditor(map), [map])
  const [, refresh] = useState(0)
  const [collapsed, setCollapsed] = useState<Set<string>>(new Set())
  const [action, setAction] = useState<Action | null>(null)
  const [title, setTitle] = useState("")
  const [error, setError] = useState<string | null>(null)
  useEffect(() => editor.subscribe(() => refresh(tick => tick + 1)), [editor])
  const begin = (next: Action) => {
    setTitle(next.kind === "rename" ? editor.graph.states.find(state => state.id === next.id)?.title ?? "" : "")
    setError(null); setAction(next)
  }
  const toggle = (id: string, open: boolean) => setCollapsed(previous => {
    const next = new Set(previous)
    if (open) next.delete(id)
    else next.add(id)
    return next
  })
  const row = (id: string, name: string, kind: "root" | "scene" | "state") => {
    const state = editor.graph.states.find(item => item.id === id)
    const active = editor.activeId === id
    const changed = !!state?.changes.length
    const isDefault = editor.graph.defaultStateId === id || (id === ROOT_STATE && editor.graph.defaultStateId === null)
    return <div data-state-point={id} data-state-kind={kind} className={cn("group flex min-h-10 min-w-0 items-center gap-1 rounded-md pr-1", active ? "bg-muted" : "hover:bg-muted/50")}>
      {kind !== "state" ? <CollapsibleTrigger asChild><Button type="button" variant="ghost" size="icon-xs" aria-label={`${collapsed.has(id) ? "Expand" : "Collapse"} ${name}`}>{collapsed.has(id) ? <ChevronRight /> : <ChevronDown />}</Button></CollapsibleTrigger> : <span className="w-6 shrink-0" />}
      <button type="button" aria-label={`Select ${name}`} aria-current={active ? "true" : undefined} className="flex min-w-0 flex-1 items-center gap-2 rounded-sm py-2 text-left text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" onClick={() => editor.select(id)}>
        <span data-slot="state-circle" data-active={active} data-changed={changed} className={cn("size-3 shrink-0 rounded-full border-[1.5px]", active && kind !== "root" ? "border-black bg-black" : changed ? "border-violet-600 bg-violet-600" : "border-black bg-transparent")} />
        <span data-slot="state-title" className={cn("min-w-0 flex-1 truncate", (active || kind !== "state") && "font-medium")}>{name}</span>
        {isDefault ? <span data-slot="state-default" className="shrink-0 rounded bg-background px-1.5 py-0.5 text-[10px] text-muted-foreground">Default</span> : null}
      </button>
      <DropdownMenu modal={false}>
        <DropdownMenuTrigger asChild><Button type="button" variant="ghost" size="icon-sm" aria-label={`Actions for ${name}`} className="shrink-0 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 data-[state=open]:opacity-100 max-sm:opacity-100"><MoreHorizontal /></Button></DropdownMenuTrigger>
        <DropdownMenuContent align="end" onCloseAutoFocus={event => { if (action) event.preventDefault() }}>
          {kind === "scene" ? <DropdownMenuItem aria-label={`Add Scene to ${name}`} onSelect={() => begin({ id: id.slice(6), kind: "add" })}><Plus />Add Scene</DropdownMenuItem> : null}
          {state ? <>
            <DropdownMenuItem aria-label={`Duplicate ${name}`} onSelect={() => editor.select(editor.duplicate(id))}><Copy />Duplicate</DropdownMenuItem>
            <DropdownMenuItem aria-label={`Rename ${name}`} onSelect={() => begin({ id, kind: "rename" })}><Pencil />Rename</DropdownMenuItem>
            <DropdownMenuItem aria-label={`Reset ${name} overrides`} disabled={!changed} onSelect={() => editor.reset(id)}><RotateCcw />Reset overrides</DropdownMenuItem>
            <DropdownMenuSeparator />
          </> : null}
          <DropdownMenuItem aria-label={`Set ${name} as default`} disabled={isDefault} onSelect={() => editor.setDefault(id)}><Star />Set as default</DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  }
  return <section data-slot="app-states-panel" className="flex h-full min-h-0 min-w-0 flex-col">
    <header className="shrink-0 border-b border-border px-3 py-3"><h2 className="text-sm font-semibold">Scenes</h2><p data-slot="active-state-label" className="mt-1 truncate text-xs text-muted-foreground">{editor.label()}</p></header>
    <div data-slot="app-states-tree" className="min-h-0 min-w-0 flex-1 overflow-y-auto overflow-x-hidden p-3">
      <Collapsible open={!collapsed.has(ROOT_STATE)} onOpenChange={open => toggle(ROOT_STATE, open)}>
        {row(ROOT_STATE, "root", "root")}
        <CollapsibleContent className="ml-3 border-l border-border pl-3">
          {editor.scenes().map(scene => <Collapsible key={scene.id} open={!collapsed.has(scenePointId(scene.id))} onOpenChange={open => toggle(scenePointId(scene.id), open)}>
            {row(scenePointId(scene.id), appPageLabel(scene), "scene")}
            <CollapsibleContent className="ml-3 border-l border-border pl-3">
              {editor.graph.states.filter(state => state.sceneId === scene.id).map(state => <div key={state.id}>{row(state.id, state.title, "state")}</div>)}
            </CollapsibleContent>
          </Collapsible>)}
        </CollapsibleContent>
      </Collapsible>
    </div>
    {action ? <form className="shrink-0 space-y-3 border-t border-border p-3" onSubmit={event => {
      event.preventDefault()
      try {
        if (action.kind === "rename") editor.rename(action.id, title)
        else editor.select(editor.create(action.id, title))
        setAction(null); setError(null)
      } catch (err) { setError(err instanceof Error ? err.message : String(err)) }
    }}>
      <Label htmlFor="state-title">Scene title</Label><Input id="state-title" value={title} onChange={event => setTitle(event.target.value)} required maxLength={120} autoFocus />
      {error ? <p role="alert" className="text-xs text-destructive">{error}</p> : null}
      <div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => { setAction(null); setError(null) }}>Cancel</Button><Button type="submit">{action.kind === "rename" ? "Save name" : "Create scene"}</Button></div>
    </form> : null}
  </section>
}

export function AppStatesPanel({ mapId }: { mapId: number | null }) {
  const map = useAdminMap()
  return map && map.id === mapId ? <StateTree key={map.id} map={map} /> : <p className="p-3 text-sm text-muted-foreground">Loading Scenes…</p>
}
