import type { SettingsField, SettingsFormSchema } from "@/lib/settings-form/types"

const MARKER_STATE_DEFAULTS = { opacity: 100, saturation: 100 }

/** `colors.markers` slice. */
export const MARKER_STYLES_DEFAULTS: Record<string, unknown> = {
  base: { ...MARKER_STATE_DEFAULTS },
  hovered: { ...MARKER_STATE_DEFAULTS },
  unhovered: { opacity: 40, saturation: 100 },
  active: { ...MARKER_STATE_DEFAULTS },
  inactive: { opacity: 40, saturation: 100 },
}

export const markerStylesSchema: SettingsFormSchema = {
  fields: ["base", "hovered", "unhovered", "active", "inactive"].flatMap<SettingsField>(state => [
    { type: "section", id: `sec-marker-${state}`, label: state[0].toUpperCase() + state.slice(1) },
    {
      type: "group", id: `marker-${state}-appearance`, label: "", inputLabels: "above",
      fields: [
        { type: "number", path: `${state}.opacity`, label: "Opacity", shortLabel: "Opacity", integer: true, slider: true, min: 0, max: 100 },
        { type: "number", path: `${state}.saturation`, label: "Saturation", shortLabel: "Saturation", integer: true, slider: true, min: 0, max: 100 },
      ],
    },
  ]),
}
