import type { SettingsFormSchema, SettingsOption } from "@/lib/settings-form/types"
import { getByPath } from "@/lib/settings-form/path"
import { createElement } from "react"
import { GOOGLE_MAP_LANGUAGES } from "../../../../../mapsvg/Map/GoogleMapsPresets"
import { GoogleMapStyleJsonField } from "../map/GoogleMapStyleJsonField"

const MAP_TYPE_OPTIONS: SettingsOption[] = [
  { value: "roadmap", label: "Road" },
  { value: "satellite", label: "Satellite" },
  { value: "hybrid", label: "Hybrid" },
  { value: "terrain", label: "Terrain" },
]

const MAP_STYLE_OPTIONS: SettingsOption[] = [
  { value: "default", label: "Default" },
  { value: "silver", label: "Silver" },
  { value: "retro", label: "Retro" },
  { value: "dark", label: "Dark" },
  { value: "night", label: "Night" },
  { value: "blue", label: "Blue" },
  { value: "custom", label: "Custom" },
]

function eq(path: string, value: string) {
  return (values: Record<string, unknown>) => getByPath(values, path) === value
}

/** `googleMaps` options slice. */
export const GOOGLE_MAPS_SETTINGS_DEFAULTS: Record<string, unknown> = {
  on: false,
  apiKey: "",
  language: "en",
  type: "roadmap",
  style: "default",
  styleJSON: [],
  minZoom: 1,
}

export const googleMapsSettingsSchema: SettingsFormSchema = {
  fields: [
    { type: "switch", path: "on", label: "Enable" },
    {
      type: "select",
      path: "language",
      label: "Map language",
      options: GOOGLE_MAP_LANGUAGES,
      help: "Save settings and reload the page to apply the language change.",
    },
    {
      type: "radio",
      path: "type",
      label: "Map type",
      options: MAP_TYPE_OPTIONS,
    },
    {
      type: "radio",
      path: "style",
      label: "Map style",
      options: MAP_STYLE_OPTIONS,
    },
    {
      type: "custom",
      id: "styleJSON",
      visible: eq("style", "custom"),
      render: ctx => createElement(GoogleMapStyleJsonField, {
        value: ctx.getValue("styleJSON"), onChange: value => ctx.setValue("styleJSON", value),
      }),
    },
  ],
}
