import { useEffect, useState } from "react"
import { ComponentController } from "@/components/ComponentController"
import { MapLayersItemsEditor } from "@/components/settings/layers/MapLayersItemsEditor"
import { LAYERS_SETTINGS_DEFAULTS, layersSettingsSchema } from "@/components/settings/layers/layersSettingsSchema"
import { mergeOptionsSlice, subscribeLiveMapOptions } from "@/lib/live-map-options"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { readNodes, type MapSvgNode } from "@/lib/nodes-admin"
import { mergeRegisteredSettingsSchema } from "@/lib/settings-form/schemaMerge"
import type { SettingsFormSchema } from "@/lib/settings-form/types"
import { mapPresentationSourceField, mapPresentationStyles, patchPresentationSettings } from "../MapPresentationSettings"
import { layersPresentation } from "../../../../../mapsvg/Components/MapPresentation"

export function MapLayersSettingsPanel({ map, node: selected }: { map: MapsvgMapInstance | null; node?: MapSvgNode }) {
  const [, setTick] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => setTick((tick) => tick + 1)), [])
  const nodes = readNodes(map)
  const node = nodes.find(node => selected ? node.id === selected.id : node.type === "layers")
  const parent = nodes.find(parent => parent.children?.includes(node?.id || ""))
  const values = { ...layersPresentation(mergeOptionsSlice(LAYERS_SETTINGS_DEFAULTS, map?.options.layersControl), node), mapNodeId: node?.settings.mapNodeId ?? "" }
  const schema: SettingsFormSchema = mergeRegisteredSettingsSchema("layers.settings", {
    fields: [
      mapPresentationSourceField(map),
      ...layersSettingsSchema.fields.filter(field => !("path" in field && field.path === "position" && parent?.type !== "map")),
      { type: "section", id: "layers-items", label: "Items" },
      { type: "custom", id: "layers-items-editor", render: () => <MapLayersItemsEditor map={map} /> },
    ],
  })
  return <ComponentController settings={{
    retainEnable: true,
    schema,
    values,
    onChange: (next) => {
      if (node) patchPresentationSettings(map, node.id, values, next)
    },
  }} styles={mapPresentationStyles(map, node)} />
}
