import { useEffect, useId, useState } from "react"
import { SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { Textarea } from "@/components/ui/textarea"
import { parseGoogleMapStyles } from "../../../../../mapsvg/Map/GoogleMapsOptions"

export function GoogleMapStyleJsonField({ value, onChange }: { value: unknown; onChange: (value: unknown) => void }) {
  const id = useId()
  const serialized = typeof value === "string" ? value : JSON.stringify(value ?? [], null, 2)
  const [text, setText] = useState(serialized)
  const [error, setError] = useState<string | null>(null)
  useEffect(() => { setText(serialized); setError(null) }, [serialized])
  return <SettingsControlField id={id} label="Custom style JSON" help="Paste a JSON styles array from Google Maps or Snazzy Maps.">
    <Textarea id={id} value={text} rows={7} aria-invalid={!!error} aria-describedby={error ? `${id}-error` : undefined}
      onChange={event => {
        setText(event.target.value)
        try { const parsed = parseGoogleMapStyles(event.target.value); setError(null); onChange(parsed) }
        catch (failure) { setError(failure instanceof Error ? failure.message : String(failure)) }
      }} />
    {error ? <p id={`${id}-error`} role="alert" className="text-xs text-destructive">Invalid JSON: {error}</p> : null}
  </SettingsControlField>
}
