import type { LucideIcon } from "lucide-react"
import { getRegisteredComponentNavLeaves } from "@/lib/admin-extension-registry"
import { Database, Eye, Map as MapIcon, Puzzle, Settings2 } from "lucide-react"

/** Selectable leaf in the Components sidebar. */
export type ComponentNavItem = {
  id: string
  label: string
}

/** App is an editor tree root; retain Core's settings identity without a runtime node. */
export const MAP_SETTINGS_NAV_ITEMS = [
  { id: "core", label: "App" },
  { id: "gallery", label: "Galleries" },
  { id: "components", label: "Components" },
] as const

/**
 * Nested expandable under a group (e.g. WooCommerce → ProductCard).
 * The nest label itself is not selectable.
 */
export type ComponentNavNest = {
  id: string
  label: string
  items: ComponentNavItem[]
}

export type ComponentNavChild = ComponentNavItem | ComponentNavNest

export type ComponentNavGroup = {
  id: string
  label: string
  icon: LucideIcon
  children: ComponentNavChild[]
}

export function isComponentNavNest(child: ComponentNavChild): child is ComponentNavNest {
  return "items" in child
}

