export function resolveComponentNavGroups(
  coreGroups: readonly ComponentNavGroup[] = COMPONENT_NAV_GROUPS,
): ComponentNavGroup[] {
  const groups = coreGroups.map((group) => ({
    ...group,
    children: group.children.map((child) =>
      isComponentNavNest(child)
        ? { ...child, items: child.items.map((item) => ({ ...item })) }
        : { ...child },
    ),
  }))

  const existingIds = new Set<string>()
  for (const group of groups) {
    for (const child of group.children) {
      if (isComponentNavNest(child)) {
        for (const item of child.items) existingIds.add(item.id)
      } else {
        existingIds.add(child.id)
      }
    }
  }

  for (const leaf of getRegisteredComponentNavLeaves()) {
    if (existingIds.has(leaf.id)) {
      throw new Error(
        '[MapSVG admin extensions] Component navigation leaf "' +
          leaf.id +
          '" collides with a Lite-owned leaf.',
      )
    }

    const group = groups.find((candidate) => candidate.id === leaf.groupId)
    if (!group) {
      throw new Error(
        '[MapSVG admin extensions] Unknown component navigation group "' +
          leaf.groupId +
          '" for "' +
          leaf.id +
          '".',
      )
    }

    const item = { id: leaf.id, label: leaf.label }
    if (leaf.nestId) {
      const nest = group.children.find(
        (child): child is ComponentNavNest => isComponentNavNest(child) && child.id === leaf.nestId,
      )
      if (!nest) {
        throw new Error(
          '[MapSVG admin extensions] Unknown component navigation nest "' +
            leaf.nestId +
            '" for "' +
            leaf.id +
            '".',
        )
      }
      nest.items.push(item)
    } else {
      group.children.push(item)
    }
    existingIds.add(leaf.id)
  }

  return groups
}

/** Resolve leaf + breadcrumb path for a selected component id. */
export function findComponentNav(
  componentId: string | null,
  groups: readonly ComponentNavGroup[] = COMPONENT_NAV_GROUPS,
): {
  group: ComponentNavGroup
  nest: ComponentNavNest | null
  item: ComponentNavItem
} | null {
  if (!componentId) return null
  for (const group of groups) {
    for (const child of group.children) {
      if (isComponentNavNest(child)) {
        const item = child.items.find((i) => i.id === componentId)
        if (item) return { group, nest: child, item }
      } else if (child.id === componentId) {
        return { group, nest: null, item: child }
      }
    }
  }
  return null
}
