import type { DataSchema, GlobalSavedQuery } from "@/lib/mapsvg-api"
import type { BindingRole } from "../../../mapsvg/Map/pageBindings"

export function queryResultFields(query: GlobalSavedQuery | undefined, schema: DataSchema | undefined) {
  const select: unknown = query?.input?.select
  const names = Array.isArray(select) ? select : select && typeof select === "object"
    ? Object.entries(select).filter(([, included]) => included).map(([name]) => name) : null
  return (schema?.fields ?? []).filter(field => names === null || names.includes(field.name))
}

/** Compatibility is a result capability, independent of the App's former Collection. */
export function compatibleGlobalQueries(queries: GlobalSavedQuery[], catalog: DataSchema[], role: BindingRole): GlobalSavedQuery[] {
  return queries.filter(query => {
    const schema = catalog.find(schema => String(schema.id) === String(query.schemaId))
    if (!schema || schema.type === "api") return false
    const select: unknown = query.input?.select
    if (select && !(Array.isArray(select) ? select.includes("id") : (select as Record<string, unknown>).id === true)) return false
    return role !== "regions" || schema.type === "region" || Boolean(schema.bindings?.svg)
  })
}
