import { useEffect, useMemo, useState } from "react"
import { BracesIcon, SaveIcon, Trash2Icon, XIcon } from "lucide-react"
import { QueryBuilder, type RuleGroupType } from "react-querybuilder"
import "react-querybuilder/dist/query-builder.css"
import "@/components/data/saved-data-query-editor.css"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  createSavedDataQuery,
  EMPTY_QUERY_BUILDER,
  PLASMA_QUERY_OPERATORS,
  prismaQueryFromBuilder,
  queryBuilderFieldsForSchema,
  type SavedDataQuery,
} from "@/components/data/savedDataQueries"
import { queryBuilderControls } from "./queryBuilderControls"
import type { DataSourceRole } from "@/components/data/dataNav"
import type { DataSchema } from "@/lib/mapsvg-api"

function cloneBuilder(builder: RuleGroupType): RuleGroupType {
  return JSON.parse(JSON.stringify(builder)) as RuleGroupType
}

type Props = {
  schema: DataSchema
  sourceRole: DataSourceRole
  query?: SavedDataQuery | null
  onSave: (query: SavedDataQuery) => void
  onCancel: () => void
  onDelete?: (query: SavedDataQuery) => void
}

/** Pure editor for one map-scoped React Query Builder definition. */
export function SavedDataQueryEditor({
  schema,
  sourceRole,
  query,
  onSave,
  onCancel,
  onDelete,
}: Props) {
  const fields = useMemo(() => queryBuilderFieldsForSchema(schema), [schema])
  const [name, setName] = useState(query?.name ?? "New query")
  const [builder, setBuilder] = useState<RuleGroupType>(() =>
    cloneBuilder(query?.builder ?? EMPTY_QUERY_BUILDER),
  )
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    setName(query?.name ?? "New query")
    setBuilder(cloneBuilder(query?.builder ?? EMPTY_QUERY_BUILDER))
    setError(null)
  }, [query?.builder, query?.id, query?.name, schema.id, sourceRole])

  const preview = useMemo(() => {
    try {
      return JSON.stringify(prismaQueryFromBuilder(builder), null, 2)
    } catch (nextError) {
      return nextError instanceof Error ? nextError.message : String(nextError)
    }
  }, [builder])

  const save = () => {
    try {
      const next = createSavedDataQuery({
        id: query?.id,
        name,
        schemaId: String(schema.id),
        sourceRole,
        builder,
      })
      setError(null)
      onSave(next)
    } catch (nextError) {
      setError(nextError instanceof Error ? nextError.message : String(nextError))
    }
  }

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-col gap-5 p-4">
      <div className="grid gap-2">
        <Label htmlFor="mapsvg-data-query-name">Query name</Label>
        <Input
          id="mapsvg-data-query-name"
          value={name}
          maxLength={120}
          onChange={(event) => setName(event.target.value)}
          placeholder="Active museums"
          autoFocus={!query}
        />
        <p className="text-xs text-muted-foreground">
          Saved in this map and shown under {sourceRole === "objects" ? "Objects" : "Regions"}.
        </p>
      </div>

      {fields.length === 0 ? (
        <p className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">
          This source has no scalar fields supported by the simple Plasma query path.
        </p>
      ) : (
        <QueryBuilder
          controlElements={queryBuilderControls}
          fields={fields}
          operators={PLASMA_QUERY_OPERATORS.map((operator) => ({ ...operator }))}
          query={builder}
          onQueryChange={setBuilder}
          parseNumbers="strict"
          listsAsArrays
          resetOnFieldChange
          controlClassnames={{ queryBuilder: "mapsvg-saved-query-builder" }}
        />
      )}

      <details className="rounded-md border bg-muted/20">
        <summary className="flex cursor-pointer items-center gap-2 px-3 py-2 text-sm font-medium">
          <BracesIcon className="size-4" />
          Prisma query preview
        </summary>
        <pre className="max-h-72 overflow-auto border-t p-3 text-xs leading-relaxed">{preview}</pre>
      </details>

      {error ? <p className="text-sm text-destructive">{error}</p> : null}

      <div className="flex flex-wrap items-center justify-between gap-2 border-t pt-4">
        <div>
          {query && onDelete ? (
            <Button
              type="button"
              variant="destructive"
              size="sm"
              onClick={() => {
                if (window.confirm(`Delete query “${query.name}”?`)) onDelete(query)
              }}
            >
              <Trash2Icon />
              Delete
            </Button>
          ) : null}
        </div>
        <div className="flex items-center gap-2">
          <Button type="button" variant="outline" size="sm" onClick={onCancel}>
            <XIcon />
            Cancel
          </Button>
          <Button type="button" size="sm" disabled={fields.length === 0} onClick={save}>
            <SaveIcon />
            Save query
          </Button>
        </div>
      </div>
    </div>
  )
}
