import { ProductFeaturePlaceholder } from "@/components/PremiumFeaturePlaceholder"
import { productFeatureForNode, isProductNodeAvailable } from "@/lib/product-features"
import { ContainerSettingsBody } from "./ContainerSettingsBody"
import { ComponentLayoutControls } from "./ComponentLayoutControls"
import { LayoutDisplaySection } from "./LayoutDisplaySection"
import { ComponentDeleteControls } from "./ComponentDeleteControls"
import { useEffect, useMemo, useState } from "react"
import { ComponentInteractionsProvider } from "@/components/ComponentController"
import { ComponentSettingsBody } from "@/components/settings/ComponentSettingsBody"
import { SettingsForm } from "@/components/settings-form/SettingsForm"
import { INTERACTIONS_NAV } from "@/components/settings/interactionsNav"
import {
  NodeInteractionsPanel,
  NodeInteractionsToolbar,
} from "@/components/settings/NodeInteractionsPanel"
import { getNodeAdminDefinition } from "@/components/settings/nodeAdminRegistry"
import { subscribeLiveMapOptions, useAdminMap } from "@/lib/live-map-options"
import { appEditingPageId } from "@/lib/app-state-editor"
import { pageOwnsNode } from "@/lib/app-page-context"
import {
  buildParentIndex,
  interactionGroupForNodeType,
  isMapInternalNode,
  isMovableLayoutNode,
  isCoreNodeType,
  legacyComponentIdForNode,
  nodeById,
  readNodes,
  type MapSvgNode,
} from "@/lib/nodes-admin"

type Props = {
  nodeId: string | null
  omitLayoutPlacement?: boolean
}

function NodeLayoutControls({
  node, nodes, parentId, map,
}: {
  node: MapSvgNode
  nodes: MapSvgNode[]
  parentId: string | undefined
  map: NonNullable<ReturnType<typeof useAdminMap>>
}) {
  const parent = parentId ? nodeById(nodes, parentId) : undefined

  return (
    <><LayoutDisplaySection map={map} node={node} />
    {node.type !== "map" && parent?.type !== "body" && (parent?.type !== "map" || ["legend", "layers"].includes(node.type)) ? <ComponentLayoutControls node={node} nodes={nodes} map={map} /> : null}</>
  )
}

/** Resolve selected Layers node → component settings with optional Interactions tab. */
export function NodeSettingsBody({ nodeId, omitLayoutPlacement = true }: Props) {
  const map = useAdminMap()
  const [, setOptionsTick] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => setOptionsTick((n) => n + 1)), [])
  const nodes = readNodes(map)

  const node = useMemo(() => (nodeId ? nodeById(nodes, nodeId) : undefined), [nodeId, nodes])

  if (!nodeId || !node) {
    return (
      <p className="p-3 text-sm text-muted-foreground">
        Select a layer to edit settings and interactions.
      </p>
    )
  }

  const pageId = appEditingPageId(map)
  if (map && pageId && !pageOwnsNode(map.options, pageId, nodeId)) {
    return <p className="p-3 text-sm text-muted-foreground">Select the owning Page in the preview switcher to edit this component.</p>
  }

  const premiumFeature = productFeatureForNode(node.type)
  if (premiumFeature && !isProductNodeAvailable(node.type)) return <ProductFeaturePlaceholder feature={node.type === "mobileToolbar" ? "mobile_toolbar" : premiumFeature} />
  if (node.type === "slot" || node.type === "frame") return <ContainerSettingsBody key={node.id} node={node} />
  if (node.type === "body") return null

  const componentId = legacyComponentIdForNode(node)
  const placementParentId = buildParentIndex(nodes).get(node.id)
  const placementParent = placementParentId ? nodeById(nodes, placementParentId) : undefined
  const registeredDefinition = getNodeAdminDefinition(node.type)
  const RegisteredPanel = registeredDefinition?.SettingsPanel
  const unavailableExtensionNode = !registeredDefinition && !isCoreNodeType(node.type)
  const interactionGroupId = interactionGroupForNodeType(node.type)
  const hasInteractions =
    interactionGroupId != null &&
    INTERACTIONS_NAV.some((group) => group.id === interactionGroupId)
  const settingsLead = map && !isMapInternalNode(node) && (placementParent?.type !== "map" || ["legend", "layers"].includes(node.type))
    ? <NodeLayoutControls
        node={node}
        nodes={nodes}
        parentId={placementParentId}
        map={map}
      />
    : null

  const settingsEnd = map && isMovableLayoutNode(node) ? <ComponentDeleteControls map={map} node={node} /> : null

  return (
    <ComponentInteractionsProvider
      interactions={
        hasInteractions ? <NodeInteractionsPanel nodeType={node.type} /> : null
      }
      toolbarEnd={
        hasInteractions ? <NodeInteractionsToolbar nodeType={node.type} /> : null
      }
      settingsLead={settingsLead}
      settingsEnd={settingsEnd}
    >
      <div className="flex h-full min-h-0 flex-col">
        {RegisteredPanel ? (
          <div className="flex min-h-0 flex-1 flex-col">
            <RegisteredPanel
              node={node}
              omitLayoutPlacement={omitLayoutPlacement}
            />
          </div>
        ) : componentId && componentId !== "gallery" ? (
          <div className="flex min-h-0 flex-1 flex-col">
            <ComponentSettingsBody
              componentId={componentId}
              node={node}
              omitLayoutPlacement={omitLayoutPlacement}
            />
          </div>
        ) : (
          <div className="min-h-0 flex-1 overflow-y-auto">
            {settingsLead ? (
              <SettingsForm schema={{ fields: [] }} values={{}} onChange={() => undefined} leading={settingsLead} trailing={settingsEnd} />
            ) : null}
            <div className="px-3 pb-3 text-sm text-muted-foreground">
              <p className="font-medium text-foreground">
                {node.title || node.id}
              </p>
              {unavailableExtensionNode ? (
                <p className="mt-1">
                  The <span className="font-mono">{node.type}</span> module is not
                  available in the active MapSVG installation. Its saved
                  configuration is preserved and will become editable again when
                  the matching add-on is active.
                </p>
              ) : (
                <p className="mt-1 capitalize">
                  {node.type} — settings coming soon.
                </p>
              )}
            </div>
          </div>
        )}
      </div>
    </ComponentInteractionsProvider>
  )
}
