import type { SettingsFormSchema } from "@/lib/settings-form/types"

const HIDDEN_PATHS = new Set([
  "location",
  "containerId",
  "modalLocation",
  "detailsViewLocation",
  "locationMobile",
  "customContainer",
])

/** Hide legacy placement fields — layout tree is source of truth. */
export function withoutLayoutPlacementFields(
  schema: SettingsFormSchema,
): SettingsFormSchema {
  return {
    fields: schema.fields.filter((field) => {
      if (field.type === "section") return true
      if (!("path" in field) || typeof field.path !== "string") return true
      const leaf = field.path.split(".").pop() ?? field.path
      if (HIDDEN_PATHS.has(leaf)) return false
      if (field.path.endsWith(".on") && leaf === "on") {
        // keep feature toggles like tooltips.on / filters.on
        return true
      }
      return !HIDDEN_PATHS.has(field.path)
    }),
  }
}
