import { useState } from "react"
import { Trash2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { SettingsSection } from "@/components/settings-form/SettingsSection"
import { DeleteLayoutNodeDialog } from "@/components/layout/DeleteLayoutNodeDialog"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import type { MapSvgNode } from "@/lib/nodes-admin"

export function ComponentDeleteControls({
  map,
  node,
}: {
  map: MapsvgMapInstance
  node: MapSvgNode
}) {
  const [open, setOpen] = useState(false)
  return (
    <SettingsSection title="Danger zone">
      <Button
        type="button"
        size="xs"
        variant="outline"
        className="self-start text-destructive"
        onClick={() => setOpen(true)}
      >
        <Trash2 />
        Delete component
      </Button>
      <DeleteLayoutNodeDialog map={map} nodeId={node.id} open={open} onOpenChange={setOpen} />
    </SettingsSection>
  )
}
