import { useEffect, useState } from "react"
import { CheckIcon, PencilIcon, Trash2Icon, XIcon } from "lucide-react"
import { FormBuilderMultiCombobox, type FormBuilderComboboxOption } from "@/components/form-builder/FormBuilderCombobox"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { patchLiveMapOptions, subscribeLiveMapOptions } from "@/lib/live-map-options"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

type LayerObject = { label: string; value: string; [key: string]: unknown }
type LayerItem = {
  id?: string | number
  title?: string
  objects?: LayerObject[]
  visible?: boolean
  [key: string]: unknown
}
type LayerDraft = { title: string; objects: LayerObject[] }
type LayerRuntime = MapsvgMapInstance & {
  groups: LayerItem[] & {
    push: (...items: LayerItem[]) => number
    update: (item: LayerItem) => unknown
    delete: (id: string | number) => void
  }
  setGroups: () => void
  getGroupSelectOptions: () => Array<{ title: string; options: FormBuilderComboboxOption[] }>
  containers?: { svg?: SVGElement }
}

const emptyDraft = (): LayerDraft => ({ title: "", objects: [] })

function draftFor(item: LayerItem): LayerDraft {
  return { title: item.title ?? "", objects: (item.objects ?? []).map((object) => ({ ...object })) }
}

/** Retains unknown object metadata and references absent from the current SVG. */
function optionsFor(options: FormBuilderComboboxOption[], objects: LayerObject[]): FormBuilderComboboxOption[] {
  const result = [...options]
  const known = new Set(result.map((option) => option.value))
  for (const object of objects) {
    if (!known.has(object.value)) {
      result.push({ value: object.value, label: object.label || object.value })
      known.add(object.value)
    }
  }
  return result
}

function ItemInputs({ draft, onChange, options, name }: {
  draft: LayerDraft
  onChange: (next: LayerDraft) => void
  options: FormBuilderComboboxOption[]
  name: string
}) {
  const available = optionsFor(options, draft.objects)
  return <>
    <FormBuilderMultiCombobox
      aria-label={`${name} objects`}
      placeholder="Objects"
      searchPlaceholder="Search SVG objects..."
      className="min-w-0 max-w-full [&>span]:min-w-0"
      options={available}
      values={draft.objects.map((object) => object.value)}
      onValuesChange={(values) => {
        const selected = new Set(values)
        // Existing references retain their order, labels and unknown properties.
        const objects = draft.objects.filter((object) => selected.has(object.value))
        const retained = new Set(objects.map((object) => object.value))
        for (const value of values) {
          if (!retained.has(value)) {
            objects.push({ value, label: available.find((option) => option.value === value)?.label ?? value })
          }
        }
        onChange({ ...draft, objects })
      }}
    />
    <Input aria-label={`${name} label`} placeholder="Label" className="min-w-0 w-full" value={draft.title}
      onChange={(event) => onChange({ ...draft, title: event.target.value })} />
  </>
}

/** Inline authoring over native runtime groups; Publish owns the eventual write. */
export function MapLayersItemsEditor({ map }: { map: MapsvgMapInstance | null }) {
  const [, setTick] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => setTick((tick) => tick + 1)), [])
  const [newItem, setNewItem] = useState<LayerDraft>(emptyDraft)
  const [editing, setEditing] = useState<{ id: string | number; draft: LayerDraft } | null>(null)
  const runtime = map as LayerRuntime | null
  const items = Array.from(runtime?.groups ?? [])
  const options = runtime?.getGroupSelectOptions?.().flatMap((group) => group.options) ?? []

  const refresh = (previous?: LayerItem) => {
    if (!runtime) return
    // The retained setter only visits current references. Retired references
    // from a hidden group must become visible again when no hidden group owns
    // them, before reapplying the remaining groups in their native order.
    if (previous && !previous.visible && runtime.containers?.svg) {
      const retired = new Set((previous.objects ?? []).map((object) => object.value))
      for (const item of runtime.groups) {
        if (!item.visible) for (const object of item.objects ?? []) retired.delete(object.value)
      }
      for (const element of runtime.containers.svg.querySelectorAll("[id]")) {
        if (retired.has(element.getAttribute("id")!)) element.classList.remove("mapsvg-hidden")
      }
    }
    // Bulk setGroups(array) regenerates every auto ID. Use the native indexed
    // collection operations, then the no-argument setter just as legacy does.
    runtime.options.groups = runtime.groups
    runtime.setGroups()
    // Redraw the frontend switches and notify editor/draft subscribers.
    patchLiveMapOptions({ layersControl: {} })
  }
  const saveEdit = () => {
    if (!runtime || !editing) return
    // Read the live item now, so frontend visibility changes made during editing
    // and extension-owned properties survive this title/object-only update.
    const item = runtime.groups.find((item) => item.id === editing.id)
    if (item) {
      const previous = { ...item }
      runtime.groups.update({ ...item, ...editing.draft })
      refresh(previous)
    }
    setEditing(null)
  }

  return <div className="min-w-0 w-full max-w-full space-y-2" data-slot="layers-items">
    {items.map((item) => {
      const active = editing?.id === item.id
      const name = `Item ${String(item.id)}`
      return <div key={String(item.id)} data-slot="layers-item-row"
        className="grid min-w-0 w-full grid-cols-[minmax(0,1fr)_minmax(0,1fr)_auto] items-center gap-2">
        {active && editing ? <ItemInputs draft={editing.draft} options={options} name={name}
          onChange={(draft) => setEditing({ ...editing, draft })} /> : <>
          <span className="min-w-0 truncate text-xs text-muted-foreground" title={(item.objects ?? []).map((object) => object.label || object.value).join(", ")}>
            {(item.objects ?? []).map((object) => object.label || object.value).join(", ") || "No objects"}
          </span>
          <span className="min-w-0 truncate text-xs" title={item.title}>{item.title}</span>
        </>}
        <div className="flex shrink-0 items-center gap-1">
          {active ? <>
            <Button type="button" variant="ghost" size="icon-xs" aria-label={`Save ${name}`} onClick={saveEdit}><CheckIcon /></Button>
            <Button type="button" variant="ghost" size="icon-xs" aria-label={`Cancel editing ${name}`} onClick={() => setEditing(null)}><XIcon /></Button>
          </> : <>
            <Button type="button" variant="ghost" size="icon-xs" aria-label={`Edit ${name}`} onClick={() => {
              if (item.id !== undefined) setEditing({ id: item.id, draft: draftFor(item) })
            }}><PencilIcon /></Button>
            <Button type="button" variant="ghost" size="icon-xs" aria-label={`Delete ${name}`} onClick={() => {
              if (runtime && item.id !== undefined) {
                runtime.groups.delete(item.id)
                refresh(item)
              }
            }}><Trash2Icon /></Button>
          </>}
        </div>
      </div>
    })}
    <div data-slot="layers-item-add-row" className="grid min-w-0 w-full grid-cols-[minmax(0,1fr)_minmax(0,1fr)_auto] items-center gap-2">
      <ItemInputs name="New item" draft={newItem} onChange={setNewItem} options={options} />
      <Button type="button" size="sm" disabled={!runtime || (!newItem.objects.length && !newItem.title.trim())} onClick={() => {
        if (!runtime) return
        runtime.groups.push({ ...newItem, visible: true })
        refresh()
        setNewItem(emptyDraft())
      }}>Add</Button>
    </div>
  </div>
}
