import type { SettingsFormSchema } from "@/lib/settings-form/types"

/** Defaults matching `default-options.ts` popovers + form extras. */
export const POPOVER_SETTINGS_DEFAULTS: Record<string, unknown> = {
  position: "top",
  template: "",
  centerOn: true,
  resetViewboxOnClose: false,
}

export const POPOVER_STYLES_DEFAULTS: Record<string, unknown> = {
  width: 300,
  maxWidth: 50,
  maxHeight: 50,
  mobileFullscreen: false,
}

/** Schema for Components → Popover settings (dev `form-popover-settings`). */
export const popoverSettingsSchema: SettingsFormSchema = {
  fields: [
    { type: "section", id: "popover-position", label: "Position" },
    {
      type: "switch",
      path: "centerOn",
      label: "Center map on popovers",
    },
    {
      type: "switch",
      path: "resetViewboxOnClose",
      label: "Reset map position on popover close",
    },
  ],
}

export const popoverStylesSchema: SettingsFormSchema = {
  fields: [
    { type: "section", id: "popover-size", label: "Size" },
    {
      type: "number",
      path: "width",
      label: "Width",
      integer: true,
      allowEmpty: true,
      suffix: "px",
    },
    {
      type: "number",
      path: "maxWidth",
      label: "Max-width",
      allowEmpty: true,
      suffix: "%",
      help: "Relative to map width",
    },
    {
      type: "number",
      path: "maxHeight",
      label: "Max-height",
      allowEmpty: true,
      suffix: "%",
      help: "Relative to map height",
    },
    {
      type: "switch",
      path: "mobileFullscreen",
      label: "Fullscreen on mobile devices",
    },
  ],
}
