type Props = {
  selectedNodeId: string | null
  selectedSceneId?: string | null
  selectedComponentId?: string | null
  onSelectNode: (nodeId: string) => void
  onEditInteractions?: (nodeId: string) => void
  onSelectScene: (sceneId: string) => void
  onSelectComponent?: (componentId: string) => void
  layoutBreakpoint?: LayoutBreakpoint
  className?: string
}

function layerLabelClass(node: MapSvgNode): string {
  if (node.type === "slot" || node.type === "frame" || node.type === "body" ||
    node.type === "map" || isMapInternalNode(node)) {
    return "text-foreground"
  }
  return "text-violet-700 dark:text-violet-400"
}

function childNodes(nodes: MapSvgNode[], parent: MapSvgNode): MapSvgNode[] {
  return (parent.children ?? [])
    .map((id) => nodeById(nodes, id))
    .filter((n): n is MapSvgNode => Boolean(n))
}

/** Top-level Layers for a scene: page slots + Body portal (not a separate scene). */
function sceneTopNodes(nodes: MapSvgNode[], scene: SceneNode, slotIds: string[]): MapSvgNode[] {
  const out: MapSvgNode[] = []
  const seen = new Set<string>()

  for (const slotId of slotIds) {
    const node = nodeById(nodes, slotId)
    if (node && !seen.has(node.id)) {
      seen.add(node.id)
      out.push(node)
    }
  }

  if (scene.rootNodeId && !seen.has(scene.rootNodeId)) {
    const root = nodeById(nodes, scene.rootNodeId)
    if (root && root.type !== "body") {
      seen.add(root.id)
      out.push(root)
    }
  }

  const bodyId = scene.bodyNodeId || "body"
  if (!seen.has(bodyId)) {
    const body = nodeById(nodes, bodyId)
    if (body) {
      seen.add(body.id)
      out.push(body)
    }
  }

  return out
}

function LayerTreeNode({
  node,
  nodes,
  actions,
  depth,
  selectedNodeId,
  onSelectNode,
  onEditInteractions,
  onAdd,
  draggedId,
  dropTarget,
  onDragStart,
  onDragEnd,
  onDragOver,
  onDrop,
}: {
  node: MapSvgNode
  nodes: MapSvgNode[]
  actions: unknown
  depth: number
  selectedNodeId: string | null
  onSelectNode: (id: string) => void
  onEditInteractions?: (id: string) => void
  onAdd: (nodeId: string, nodeType: NodeType) => void
  draggedId: string | null
  dropTarget: { id: string; position: TreeDropPosition } | null
  onDragStart: (id: string, event: DragEvent<HTMLDivElement>) => void
  onDragEnd: () => void
  onDragOver: (id: string, event: DragEvent<HTMLDivElement>) => void
  onDrop: (id: string, event: DragEvent<HTMLDivElement>) => void
}) {
  const map = useAdminMap()
  const breakpoint = useWorkspaceStore(state => previewSessionLayoutBreakpoint(map ? state.mapSessions[String(map.id)] : undefined))
  const hidden = (node.type === "slot" || isMovableLayoutNode(node)) && isContainerHidden(node, breakpoint, readLayoutOptions(map?.options.layout))
  const kids = childNodes(nodes, node)
  const hasChildren = kids.length > 0
  const canAdd = canAddChildren(node.type)
  const movable = isMovableLayoutNode(node)
  const [open, setOpen] = useState(true)
  const selected = node.id === selectedNodeId
  const dropPosition = dropTarget?.id === node.id ? dropTarget.position : null
  const interactions = nodeInteractionsStatus(node.type, actions)
  const interactionsPointerDown = useRef(false)

  const row = (
    <div
      data-slot="component-tree-row"
      className={cn(
        "group/layer flex h-7 w-full cursor-pointer items-center gap-0.5 rounded-md pr-1 text-xs",
        selected && "bg-accent",
        !selected && "hover:bg-muted/60",
        movable && "active:cursor-grabbing",
        (draggedId === node.id || hidden) && "opacity-40",
        dropPosition === "inside" && "bg-primary/15 outline outline-1 outline-primary",
        dropPosition === "before" && "border-t-2 border-primary",
        dropPosition === "after" && "border-b-2 border-primary",
      )}
      style={{ paddingLeft: `${4 + depth * 12}px` }}
      draggable={movable}
      onClick={(event) => {
        if (!(event.target as Element).closest("button")) onSelectNode(node.id)
      }}
      onPointerDownCapture={(event) => {
        interactionsPointerDown.current = Boolean((event.target as Element)
          .closest('[data-slot="component-interactions-indicator"]'))
      }}
      onDragStart={(event) => {
        if (interactionsPointerDown.current) {
          event.preventDefault()
          event.stopPropagation()
          return
        }
        onDragStart(node.id, event)
      }}
      onDragEnd={onDragEnd}
      onDragOver={(event) => onDragOver(node.id, event)}
      onDrop={(event) => onDrop(node.id, event)}
    >
      {hasChildren ? (
        <button
          type="button"
          className="inline-flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground hover:bg-muted"
          aria-label={open ? "Collapse" : "Expand"}
          onClick={(e) => {
            e.preventDefault()
            e.stopPropagation()
            setOpen((v) => !v)
          }}
        >
          <ChevronRight className={cn("size-3.5 transition-transform", open && "rotate-90")} />
        </button>
      ) : (
        <span className="inline-block size-5 shrink-0" />
      )}

      <button
        type="button"
        className="flex h-full min-w-0 flex-1 items-center gap-1.5 truncate text-left"
        onClick={() => onSelectNode(node.id)}
      >
        <LayerTypeIcon node={node} />
        {hidden ? <EyeOff className="size-3 shrink-0" aria-label={`Hidden in ${breakpoint} layout`} /> : null}
        <span className={cn("truncate", layerLabelClass(node))}>{node.title || node.id}</span>
        {!isProductNodeAvailable(node.type) ? <PremiumBadge /> : null}
      </button>

      {movable ? (
        <span
          aria-hidden="true"
          title="Drag to move"
          className="inline-flex size-5 shrink-0 items-center justify-center text-muted-foreground opacity-0 group-hover/layer:opacity-100 group-focus-within/layer:opacity-100"
        >
          <GripVertical className="size-3.5" />
        </span>
      ) : null}

      {canAdd ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <ComponentTreeActionButton
              aria-label={`Add to ${node.title || node.id}`}
              className={cn(
                "text-muted-foreground hover:text-foreground focus-visible:opacity-100",
                node.type === "frame" ? "opacity-100" : "opacity-0 group-hover/layer:opacity-100",
              )}
              onClick={(e) => {
                e.preventDefault()
                e.stopPropagation()
                onAdd(node.id, node.type)
              }}
            >
              <PlusIcon className="size-3.5" />
            </ComponentTreeActionButton>
          </TooltipTrigger>
          <TooltipContent side="right" sideOffset={6}>
            Add component
          </TooltipContent>
        </Tooltip>
      ) : null}

      {interactions && isProductNodeAvailable(node.type) ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <ComponentTreeActionButton
              data-slot="component-interactions-indicator"
              data-state={interactions.enabled ? "enabled" : "disabled"}
              aria-label={`${node.title || node.id}: interactions ${interactions.enabled ? "enabled" : "disabled"}`}
              draggable={false}
              className={interactions.enabled ? "text-neutral-400 dark:text-neutral-500" : "text-neutral-300 dark:text-neutral-600"}
              onPointerDown={(event) => event.stopPropagation()}
              onDragStart={(event) => {
                event.preventDefault()
                event.stopPropagation()
              }}
              onClick={(event) => {
                event.preventDefault()
                event.stopPropagation()
                if (onEditInteractions) onEditInteractions(node.id)
                else onSelectNode(node.id)
              }}
            >
              <MousePointer2Icon className="size-3.5" aria-hidden="true" />
            </ComponentTreeActionButton>
          </TooltipTrigger>
          <TooltipContent side="right" sideOffset={6}>Edit interactions</TooltipContent>
        </Tooltip>
      ) : null}
    </div>
  )

  if (!hasChildren) return row

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      {row}
      <CollapsibleContent>
        {kids.map((child) => (
          <LayerTreeNode
            key={child.id}
            node={child}
            nodes={nodes}
            actions={actions}
            depth={depth + 1}
            selectedNodeId={selectedNodeId}
            onSelectNode={onSelectNode}
            onEditInteractions={onEditInteractions}
            onAdd={onAdd}
            draggedId={draggedId}
            dropTarget={dropTarget}
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
            onDragOver={onDragOver}
            onDrop={onDrop}
          />
        ))}
      </CollapsibleContent>
    </Collapsible>
  )
}

/**
 * App-rooted sidebar with the current Scene and its layers for Components tab.
 * The multi-scene picker is intentionally hidden until scene management lands.
 */
export function ScenesLayersSidebar({
  selectedNodeId,
  selectedSceneId,
  selectedComponentId,
  onSelectNode,
  onEditInteractions,
  onSelectScene,
  onSelectComponent,
  layoutBreakpoint = "desktop",
  className,
}: Props) {
  const map = useAdminMap()
  const { requestMigration } = useLayoutMigration()
  const [optionsTick, setOptionsTick] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => setOptionsTick((n) => n + 1)), [])
  const nodes = useMemo(() => readNodes(map), [map, optionsTick])
  const scenes = useMemo(() => readScenes(map), [map, optionsTick])
  const [appOpen, setAppOpen] = useState(true)
  const [layersOpen, setLayersOpen] = useState(true)
  const [libraryOpen, setLibraryOpen] = useState(false)
  const [libraryContext, setLibraryContext] = useState<LibraryParentContext | null>(null)
  const [draggedId, setDraggedId] = useState<string | null>(null)
  const [dropTarget, setDropTarget] = useState<{ id: string; position: TreeDropPosition } | null>(null)

  const activeScene = scenes.find(scene => scene.id === appEditingPageId(map)) ?? scenes[0]
  const appSettings = MAP_SETTINGS_NAV_ITEMS[0]
  const slotIds = useMemo(
    () => getSlotIdsFromLayout(map, layoutBreakpoint),
    [map, layoutBreakpoint, optionsTick],
  )

  const tops = useMemo(() => {
    if (!activeScene) return []
    const visible = map && scenes.length > 1 ? pageNodeIds(map.options, activeScene.id) : null
    return sceneTopNodes(nodes, activeScene, slotIds).filter(node => !visible || visible.has(node.id))
  }, [activeScene, nodes, slotIds, map, scenes.length])

  const openLibraryForNode = (nodeId: string, nodeType: NodeType) => {
    setLibraryContext({ kind: "node", nodeId, nodeType })
    setLibraryOpen(true)
  }

  const dropPositionFor = (targetId: string, event: DragEvent<HTMLDivElement>): TreeDropPosition => {
    const target = nodeById(nodes, targetId)!
    const moving = draggedId ? nodeById(nodes, draggedId) : undefined
    const rect = event.currentTarget.getBoundingClientRect()
    const fraction = (event.clientY - rect.top) / Math.max(1, rect.height)
    if (moving && canContainLayoutNode(target, moving, nodes) && (target.type === "slot" || target.type === "body")) {
      return "inside"
    }
    if (moving && canContainLayoutNode(target, moving, nodes) && fraction > 0.25 && fraction < 0.75) {
      return "inside"
    }
    return fraction < 0.5 ? "before" : "after"
  }

  const handleDragOver = (targetId: string, event: DragEvent<HTMLDivElement>) => {
    event.stopPropagation()
    if (!draggedId) return
    const position = dropPositionFor(targetId, event)
    if (!moveLayoutNode(nodes, draggedId, targetId, position, scenes).ok) {
      setDropTarget(null)
      return
    }
    event.preventDefault()
    event.dataTransfer.dropEffect = "move"
    setDropTarget({ id: targetId, position })
  }

  const handleDrop = (targetId: string, event: DragEvent<HTMLDivElement>) => {
    event.stopPropagation()
    event.preventDefault()
    if (!draggedId || !map) return
    const result = moveLayoutNode(nodes, draggedId, targetId, dropPositionFor(targetId, event), scenes)
    setDraggedId(null)
    setDropTarget(null)
    if (!result.ok) return
    requestMigration(() => {
      applyLayoutEdit({
        nodes: result.nodes,
        layout: { ...readLayoutOptions(map.options.layout), mountMode: "tree" },
      })
      onSelectNode(draggedId)
    })
  }

  return (
    <>
      <SidebarGroup className={cn("p-0", className)}>
        <SidebarMenu>
          <SidebarMenuItem>
            <div className="w-full px-1 pb-2">
              <Collapsible open={appOpen} onOpenChange={setAppOpen}>
                <div
                  data-slot="component-tree-app-row"
                  draggable={false}
                  className={cn(
                    "mb-0.5 flex h-7 cursor-pointer items-center gap-0.5 rounded-md pr-0.5 text-xs font-medium",
                    selectedComponentId === appSettings.id ? "bg-accent" : "hover:bg-muted/60",
                  )}
                  style={{ paddingLeft: "4px" }}
                  onClick={(event) => {
                    if (!(event.target as Element).closest("button")) onSelectComponent?.(appSettings.id)
                  }}
                >
                  <button
                    type="button"
                    className="inline-flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground hover:bg-muted"
                    aria-label={appOpen ? "Collapse App" : "Expand App"}
                    onClick={() => setAppOpen((v) => !v)}
                  >
                    <ChevronRight
                      className={cn("size-3.5 transition-transform", appOpen && "rotate-90")}
                    />
                  </button>
                  <button
                    type="button"
                    aria-current={selectedComponentId === appSettings.id ? "page" : undefined}
                    className="flex h-full min-w-0 flex-1 items-center gap-1.5 truncate text-left"
                    onClick={() => onSelectComponent?.(appSettings.id)}
                  >
                    <ComponentTreeIcon kind="app" />
                    <span className="truncate">{appSettings.label}</span>
                  </button>
                </div>
                <CollapsibleContent>
                  <Collapsible open={layersOpen} onOpenChange={setLayersOpen}>
                    <div
                      data-slot="component-tree-scene-row"
                      className={cn(
                        "mb-0.5 flex h-7 cursor-pointer items-center gap-0.5 rounded-md pr-0.5 text-xs font-medium",
                        selectedSceneId === activeScene?.id && "bg-accent",
                      )}
                      style={{ paddingLeft: "16px" }}
                      onClick={(event) => {
                        if (!(event.target as Element).closest("button") && activeScene) onSelectScene(activeScene.id)
                      }}
                    >
                      <button
                        type="button"
                        className="inline-flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground hover:bg-muted"
                        aria-label={layersOpen ? "Collapse layers" : "Expand layers"}
                        onClick={() => setLayersOpen((v) => !v)}
                      >
                        <ChevronRight
                          className={cn("size-3.5 transition-transform", layersOpen && "rotate-90")}
                        />
                      </button>
                      <button
                        type="button"
                        className="flex h-full min-w-0 flex-1 items-center gap-1.5 truncate text-left"
                        onClick={() => activeScene && onSelectScene(activeScene.id)}
                      >
                        <ComponentTreeIcon kind="page" />
                        <span className="truncate">{appPageLabel(activeScene)}</span>
                      </button>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <ComponentTreeActionButton
                            data-slot="scene-data-bindings-shortcut"
                            aria-label="Edit data bindings"
                            draggable={false}
                            className="text-neutral-400 dark:text-neutral-500"
                            onPointerDown={(event) => event.stopPropagation()}
                            onDragStart={(event) => {
                              event.preventDefault()
                              event.stopPropagation()
                            }}
                            onClick={(event) => {
                              event.preventDefault()
                              event.stopPropagation()
                              if (activeScene) onSelectScene(activeScene.id)
                            }}
                          >
                            <DatabaseIcon className="size-3.5" aria-hidden="true" />
                          </ComponentTreeActionButton>
                        </TooltipTrigger>
                        <TooltipContent side="right" sideOffset={6}>Edit data bindings</TooltipContent>
                      </Tooltip>
                    </div>
                    <CollapsibleContent>
                      {tops.length === 0 ? (
                        <p className="px-2 py-2 text-xs text-muted-foreground">
                          No layers yet. Add slots in Layout mode.
                        </p>
                      ) : (
                        tops.map((node) => (
                          <LayerTreeNode
                            key={node.id}
                            node={node}
                            nodes={nodes}
                            actions={map?.options.actions}
                            depth={2}
                            selectedNodeId={selectedNodeId}
                            onSelectNode={onSelectNode}
                            onEditInteractions={onEditInteractions}
                            onAdd={openLibraryForNode}
                            draggedId={draggedId}
                            dropTarget={dropTarget}
                            onDragStart={(id, event) => {
                              setDraggedId(id)
                              event.dataTransfer.effectAllowed = "move"
                              event.dataTransfer.setData("text/plain", id)
                            }}
                            onDragEnd={() => {
                              setDraggedId(null)
                              setDropTarget(null)
                            }}
                            onDragOver={handleDragOver}
                            onDrop={handleDrop}
                          />
                        ))
                      )}
                    </CollapsibleContent>
                  </Collapsible>
                  <ComponentResourcesTree map={map} selected={selectedComponentId === "components" || selectedComponentId === "gallery"} />
                </CollapsibleContent>
              </Collapsible>
            </div>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarGroup>

      <LibraryModal
        open={libraryOpen}
        onOpenChange={setLibraryOpen}
        context={libraryContext}
        existingSlotIds={slotIds}
        onAdded={(nodeId) => onSelectNode(nodeId)}
      />
    </>
  )
}
