import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react"
import { FormBuilderChoice } from "@/components/form-builder/FormBuilderChoice"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Field, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { getAdminParams } from "@/lib/admin-params"
import { getAdminMapInstance, subscribeAdminMapInstance } from "@/lib/apply-options-patch"
import { subscribeLiveMapOptions } from "@/lib/live-map-options"
import { captureMapSvgOwner, changeMapSvg, isMapSvgOwnerCurrent, reloadMapSvg } from "@/lib/map-svg-operations"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { MapRegionSyncControls } from "./MapRegionSyncControls"
import { refreshSvgAssets } from "@/lib/svg-assets"
import { loadAdminCatalog } from "@/lib/admin-catalogs"

type Session = {
  mode: "change" | "reload"
  owner: ReturnType<typeof captureMapSvgOwner>
  abort: AbortController
  busy: boolean
  submitted: boolean
}

function filename(source: string) {
  const name = source.split(/[?#]/)[0].split("/").pop() || source
  try { return decodeURIComponent(name) } catch { return name }
}

export function MapSvgControls({ map }: { map: MapsvgMapInstance | null }) {
  const id = useId()
  const [, setOptionsTick] = useState(0)
  const [session, setSession] = useState<Session | null>(null)
  const sessionRef = useRef<Session | null>(null)
  const [selection, setSelection] = useState("")
  const [busy, setBusy] = useState(false)
  const [submitted, setSubmitted] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [catalog, setCatalog] = useState(() => getAdminParams().svgFiles)
  const [catalogLoading, setCatalogLoading] = useState(false)
  const [catalogError, setCatalogError] = useState(false)
  const source = typeof map?.options.source === "string" ? map.options.source : ""
  const resource = map?.options.svgAsset as { name?: string } | undefined

  const current = useCallback((candidate: Session) =>
    sessionRef.current === candidate && !candidate.abort.signal.aborted && isMapSvgOwnerCurrent(candidate.owner), [])
  const retire = useCallback(() => {
    const previous = sessionRef.current
    sessionRef.current = null
    previous?.abort.abort()
    setSession(null)
    setBusy(false)
    setSubmitted(false)
    setError(null)
    setCatalogLoading(false)
  }, [])
  useLayoutEffect(() => {
    if (sessionRef.current && sessionRef.current.owner.map !== map) retire()
  }, [map, retire])
  useLayoutEffect(() => () => {
    const previous = sessionRef.current
    sessionRef.current = null
    previous?.abort.abort()
  }, [])
  useEffect(() => {
    const check = () => {
      if (sessionRef.current && !current(sessionRef.current)) retire()
    }
    const unsubscribeMap = subscribeAdminMapInstance(check)
    const unsubscribeOptions = subscribeLiveMapOptions(() => { setOptionsTick((tick) => tick + 1); check() })
    return () => { unsubscribeMap(); unsubscribeOptions() }
  }, [current, retire])

  const open = (mode: Session["mode"]) => {
    if (!map || getAdminMapInstance() !== map) return
    try {
      sessionRef.current?.abort.abort()
      const next: Session = { mode, owner: captureMapSvgOwner(map), abort: new AbortController(), busy: false, submitted: false }
      sessionRef.current = next
      setSelection(catalog.some((file) => file.relativeUrl === source) ? source : "")
      setError(null)
      setCatalogError(false)
      setSession(next)
      if (mode === "change" && (getAdminParams().deferredCatalogs || getAdminParams().svgRegistryEnabled)) {
        setCatalogLoading(true)
        const loading = getAdminParams().deferredCatalogs ? loadAdminCatalog("svg") : refreshSvgAssets(getAdminParams().svgFiles, next.abort.signal)
        void loading.then(files => {
          if (current(next)) setCatalog(files)
        }).catch(failure => { if (current(next)) { setCatalogError(true); setError(failure instanceof Error ? failure.message : "The SVG library could not be loaded.") } })
          .finally(() => { if (current(next)) setCatalogLoading(false) })
      }
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : "The SVG file could not be opened.")
    }
  }
  const close = () => { if (!sessionRef.current?.submitted) retire() }
  const commit = async (updateTitles?: boolean) => {
    const owner = sessionRef.current
    if (!owner || owner.busy || !current(owner) || (owner.mode === "change" && !selection)) return
    owner.busy = true
    setBusy(true)
    setError(null)
    const params = {
      signal: owner.abort.signal,
      onSubmitted: () => {
        if (current(owner)) { owner.submitted = true; setSubmitted(true) }
      },
    }
    try {
      if (owner.mode === "change") await changeMapSvg(owner.owner, selection, params)
      else await reloadMapSvg(owner.owner, updateTitles === true, params)
      if (current(owner)) retire()
    } catch (failure) {
      if (current(owner)) setError(failure instanceof Error ? failure.message : "The SVG file could not be updated.")
    } finally {
      if (current(owner)) {
        owner.busy = false
        owner.submitted = false
        setBusy(false)
        setSubmitted(false)
      }
    }
  }

  return (
    <div data-slot="map-svg-file-controls" className="flex min-w-0 flex-col gap-3">
      <Field>
        <FieldLabel htmlFor={`${id}-file`}>File</FieldLabel>
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <Input id={`${id}-file`} value={resource?.name || filename(source)} readOnly className="min-w-0 flex-1" />
          <Button type="button" variant="outline" disabled={!map} onClick={() => open("change")}>Change</Button>
          <Button type="button" variant="outline" disabled={!map || !source} onClick={() => open("reload")}>Reload</Button>
        </div>
      </Field>
      <MapRegionSyncControls map={map} />
      {!session && error ? <p role="alert" className="text-xs text-destructive">{error}</p> : null}
      <Dialog open={session != null} onOpenChange={(next) => { if (!next) close() }}>
        <DialogContent
          data-slot={session?.mode === "change" ? "map-svg-change-dialog" : "map-svg-reload-dialog"}
          showCloseButton={false}
          onEscapeKeyDown={(event) => { if (submitted) event.preventDefault() }}
          onPointerDownOutside={(event) => event.preventDefault()}
        >
          <DialogHeader>
            <DialogTitle>{session?.mode === "change" ? "Change SVG file" : "Reload SVG file"}</DialogTitle>
            <DialogDescription>
              {session?.mode === "change" ? "Choose an existing SVG file." : "Reload Region titles from the SVG file, or keep your current titles."}
            </DialogDescription>
          </DialogHeader>
          {session?.mode === "change" ? (
            <Field>
              <FieldLabel htmlFor={`${id}-catalog`}>SVG file</FieldLabel>
              <FormBuilderChoice
                id={`${id}-catalog`} value={selection} disabled={busy || catalogLoading} onValueChange={setSelection}
                options={catalog.map((file) => ({ value: file.relativeUrl, label: file.pathShort || file.name }))}
                emptyLabel="Choose an SVG file" className="max-w-full"
              />
              {!catalog.length ? <p className="text-xs text-muted-foreground">No SVG files are available.</p> : null}
              {catalogLoading ? <p role="status" className="text-xs text-muted-foreground">Loading files…</p> : null}
            </Field>
          ) : null}
          {error ? <p role="alert" className="text-sm text-destructive">{error}</p> : null}
          {catalogError && session?.mode === "change" && !busy ? <Button type="button" variant="link" onClick={() => open("change")}>Retry</Button> : null}
          <DialogFooter>
            <Button type="button" variant="outline" disabled={submitted} onClick={close}>Close</Button>
            {session?.mode === "change" ? (
              <Button type="button" disabled={!selection || busy || catalogLoading} onClick={() => void commit()}>{busy ? "Applying…" : "Apply"}</Button>
            ) : (
              <>
                <Button type="button" variant="outline" disabled={busy} onClick={() => void commit(false)}>Keep current titles</Button>
                <Button type="button" disabled={busy} onClick={() => void commit(true)}>Reload titles</Button>
              </>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}
