import { defaultFilterLayoutPadding, stackComponentLayout } from "../../../../mapsvg/Layout/StackLayout"
import type { ContainerLayout } from "../../../../mapsvg/Layout/ResponsiveLayout"
import { SettingsSection } from "@/components/settings-form/SettingsSection"
import { SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { LayoutPositionField, LayoutSizeFields } from "./LayoutGeometryFields"
import { Input } from "@/components/ui/input"
import { useLayoutMigration } from "@/components/layout/LayoutMigrationDialog"
import { containerSettingsPatch } from "@/lib/layout-containers"
import { readLayoutOptions } from "@/lib/layout-grid"
import { applyLayoutEdit } from "@/lib/layout-history"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { previewSessionLayoutBreakpoint } from "@/lib/preview-canvas"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import type { MapSvgNode } from "@/lib/nodes-admin"

export function ComponentLayoutControls({ node, nodes, map }: { node: MapSvgNode; nodes: MapSvgNode[]; map: MapsvgMapInstance }) {
  const bp = useWorkspaceStore(state => previewSessionLayoutBreakpoint(state.mapSessions[String(map.id)]))
  const { requestMigration } = useLayoutMigration()
  const values = stackComponentLayout(node, bp, nodes)
  const defaultAnchor = node.type === "legend" && nodes.some(parent => parent.type === "map" && parent.children?.includes(node.id)) ? "bottom-left" : "top-left"
  const automaticPadding = defaultFilterLayoutPadding(node, bp, (map.options.filters as Record<string, unknown> | undefined)?.padding,
  { nodes, widgets: readLayoutOptions(map.options.layout).grids[bp] })
  const change = (patch: ContainerLayout) => requestMigration(() => {
    const next = containerSettingsPatch(map, node.id, bp, patch)
    applyLayoutEdit({ ...next, layout: { ...next.layout, mountMode: "tree" } })
  })
  return <SettingsSection title={`Layout · ${bp.charAt(0).toUpperCase() + bp.slice(1)}`}>
    <LayoutPositionField values={values} onChange={change} defaultAnchor={defaultAnchor} />
    <LayoutSizeFields values={values} onChange={change} defaultAnchor={defaultAnchor} />
    {node.type === "filters" ? <SettingsControlField label="Padding (px)" id={`filter-padding-${node.id}`}>
      <Input id={`filter-padding-${node.id}`} type="number" min={0} value={values.padding ?? ""}
        placeholder={`Auto · ${automaticPadding}`} onChange={event => {
          const padding = event.target.value === "" ? undefined : Math.max(0, Number(event.target.value) || 0)
          change({ padding, paddingBottom: padding })
        }} />
    </SettingsControlField> : null}
  </SettingsSection>
}
