import { SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { SettingsChoice } from "@/components/settings-form/SettingsChoice"
import { SettingsPositionGrid } from "@/components/settings-form/SettingsPositionGrid"
import { Input } from "@/components/ui/input"
import { FieldDescription } from "@/components/ui/field"
import { ABSOLUTE_ANCHORS, type AbsoluteAnchor, type ContainerLayout, type ContainerSize } from "../../../../mapsvg/Layout/ResponsiveLayout"

type Props = { values: ContainerLayout; onChange: (patch: ContainerLayout) => void; defaultAnchor?: AbsoluteAnchor }
const labels: Record<AbsoluteAnchor, string> = { "top-left": "Top left", top: "Top center", "top-right": "Top right", left: "Center left", center: "Center", right: "Center right", "bottom-left": "Bottom left", bottom: "Bottom center", "bottom-right": "Bottom right" }

export function LayoutPositionField({ values, onChange, defaultAnchor = "top-left" }: Props) {
  return <>
    <SettingsControlField label="Position">
      <SettingsChoice aria-label="Component position" value={values.position ?? "relative"}
        onValueChange={position => onChange({ position: position as ContainerLayout["position"], ...(position === "absolute" ? { anchor: values.anchor ?? defaultAnchor } : {}) })}
        options={[{ value: "relative", label: "Relative" }, { value: "absolute", label: "Absolute" }]} />
    </SettingsControlField>
    {values.position === "absolute" ? <SettingsControlField label="Placement">
      <SettingsPositionGrid aria-label="Absolute placement" value={values.anchor ?? defaultAnchor}
        options={ABSOLUTE_ANCHORS.map(value => ({ value, label: labels[value] }))}
        onValueChange={anchor => onChange({ anchor: anchor as AbsoluteAnchor })} />
    </SettingsControlField> : null}
  </>
}

export function LayoutSizeFields({ values, onChange, defaultAnchor = "top-left" }: Props) {
  const update = (patch: ContainerLayout) => onChange({
    ...patch,
    ...(values.position === "absolute" && !values.anchor ? { anchor: defaultAnchor } : {}),
  })
  return <>
    <div className="flex min-w-0 flex-col gap-4" data-slot="component-size-fields">
      {(["width", "height"] as const).map(axis => <SettingsControlField key={axis} label={axis === "width" ? "Width" : "Height"}>
        <SettingsChoice aria-label={`Component ${axis}`} value={values[axis === "width" ? "widthPercent" : "heightPercent"] !== undefined ? "legacy-percentage" : values[axis]?.mode ?? (axis === "width" ? "fill" : "auto")}
          onValueChange={mode => update({ [axis]: { mode: mode as ContainerSize["mode"], ...(mode === "fixed" ? { value: values[axis]?.value ?? (axis === "width" ? 250 : 300) } : {}) } })}
          options={[{ value: "auto", label: "Auto" }, { value: "fill", label: "Fill" }, { value: "fixed", label: "Fixed" }]} />
        {values[axis]?.mode === "fixed" ? <Input type="number" min={0} aria-label={`Component ${axis} in pixels`} value={values[axis]?.value ?? 0}
          onChange={event => update({ [axis]: { mode: "fixed", value: Math.max(0, Number(event.target.value) || 0) } })} /> : null}
        {values[axis === "width" ? "widthPercent" : "heightPercent"] !== undefined ? <FieldDescription>Imported {axis}: {values[axis === "width" ? "widthPercent" : "heightPercent"]}%. Choose a size mode to replace it.</FieldDescription> : null}
      </SettingsControlField>)}
    </div>
    <FieldDescription>Auto fits content. Fill uses the available space. Fixed uses pixels.</FieldDescription>
  </>
}
