import { ProductFeaturePlaceholder } from "@/components/PremiumFeaturePlaceholder"
import { getAdminPanelDefinition } from "@/lib/admin-extension-registry"
import { hasProductFeature } from "@/lib/product-features"
import { useWorkspaceStore } from "@/lib/workspace-store"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

/** Core keeps saved identities visible without loading paid authoring code. */
export function GalleriesPanel({ map }: { map: MapsvgMapInstance | null }) {
  const selectedId = useWorkspaceStore(state => map ? state.mapSessions[String(map.id)]?.selectedGalleryId : null)
  if (!map) return null
  const Panel = hasProductFeature("gallery") ? getAdminPanelDefinition("gallery")?.Panel : undefined
  return Panel ? <Panel mapId={map.id} selectedGalleryId={selectedId} /> : <ProductFeaturePlaceholder feature="gallery" />
}
