import { INTERACTIONS_NAV, getSchemaForInteractionEvent } from "@/components/settings/interactionsNav"
import { mergeInteractionValues } from "@/lib/interaction-values"
import { interactionGroupForNodeType, type NodeType } from "@/lib/nodes-admin"
import { getByPath } from "@/lib/settings-form/path"

/** Matches NodeSettingsBody's Interactions capability and its actual toggle fields. */
export function nodeInteractionsStatus(type: NodeType, actions: unknown): { enabled: boolean; count: number } | null {
  const groupId = interactionGroupForNodeType(type)
  const group = INTERACTIONS_NAV.find((group) => group.id === groupId)
  if (!group) return null

  const values = mergeInteractionValues(actions)
  let count = 0
  for (const event of group.events) {
    for (const field of getSchemaForInteractionEvent(event.path).fields) {
      if (field.type === "select" && field.path === "map.afterLoad.loadPost") {
        if (["auto", "objectsRepository", "regionsRepository"].includes(String(getByPath(values, field.path)))) count++
        continue
      }
      if (field.type !== "checkbox" && field.type !== "switch") continue
      if (field.visible && !field.visible(values)) continue
      // Use the same boolean projection as SettingsFieldRow, while excluding
      // templates, text/select values and unrecognized boolean properties.
      if (Boolean(getByPath(values, field.path))) count++
    }
  }
  return { enabled: count > 0, count }
}
