import { createElement } from "react"
import { MapSizeControls } from "@/components/settings/map/MapSizeControls"
import { MapPositionControls } from "@/components/settings/map/MapPositionControls"
import type { SettingsFormSchema, SettingsOption } from "@/lib/settings-form/types"
import { getByPath } from "@/lib/settings-form/path"

const ZOOM_LEVELS: SettingsOption[] = Array.from({ length: 23 }, (_, i) => ({
  value: String(i),
  label: String(i),
}))

function on(path: string) {
  return (values: Record<string, unknown>) => Boolean(getByPath(values, path))
}

/** Root map options slice (excludes the mapfile picker). */
export const MAP_SETTINGS_DEFAULTS: Record<string, unknown> = {
  responsive: true,
  width: undefined,
  height: undefined,
  lockAspectRatio: false,
  zoom: {
    mousewheel: true,
    fingers: true,
    limit: [0, 22],
    hideSvg: false,
    hideSvgZoomLevel: 7,
  },
  scroll: { on: true, limit: false },
  fitMarkers: false,
  fitMarkersOnStart: false,
  fitSingleMarkerZoom: 20,
  choropleth: {
    on: false,
    labels: { low: "low", high: "high" },
  },
  regionChoroplethField: "",
}

export const mapSettingsSchema: SettingsFormSchema = {
  fields: [
    {
      type: "section",
      id: "sec-map-size",
      label: "Map size and initial position",
    },
    { type: "switch", path: "responsive", label: "Responsive" },
    { type: "custom", id: "map-size", render: ctx => createElement(MapSizeControls, { ctx }) },
    { type: "custom", id: "map-position", render: () => createElement(MapPositionControls) },
    { type: "checkbox", path: "showPagination", label: "Show pagination" },

    { type: "section", id: "sec-zoom", label: "Zoom" },
    { type: "switch", path: "zoom.mousewheel", label: "Zoom by mousewheel" },
    { type: "switch", path: "zoom.fingers", label: "Zoom by fingers" },
    {
      type: "range",
      path: "zoom.limit",
      label: "Zoom limits",
      min: 0,
      max: 22,
      step: 1,
      lowerLabel: "Zoom limit minimum",
      upperLabel: "Zoom limit maximum",
    },
    { type: "switch", path: "zoom.hideSvg", label: "Hide SVG layer on zoom" },
    {
      type: "select",
      path: "zoom.hideSvgZoomLevel",
      label: "Hide SVG zoom level",
      indent: true,
      options: ZOOM_LEVELS,
      visible: on("zoom.hideSvg"),
    },

    { type: "section", id: "sec-scroll", label: "Scroll" },
    { type: "switch", path: "scroll.on", label: "Scroll" },
    {
      type: "switch",
      path: "scroll.limit",
      label: "Limit scroll to boundaries",
      indent: true,
      visible: on("scroll.on"),
    },

    { type: "section", id: "sec-markers-fit", label: "Markers" },
    {
      type: "switch",
      path: "fitMarkers",
      label: "Fit markers on filter/search",
    },
    {
      type: "switch",
      path: "fitMarkersOnStart",
      label: "Fit markers on start",
    },
    {
      type: "select",
      path: "fitSingleMarkerZoom",
      label: "Zoom level for single found marker",
      options: ZOOM_LEVELS,
      help: "This option has effect when Google Maps are enabled only.",
    },

  ],
}
