import type { SettingsFormSchema, SettingsOption } from "@/lib/settings-form/types"
import { getByPath } from "@/lib/settings-form/path"

const REFETCH_UNITS: SettingsOption[] = [
  { value: "s", label: "seconds" },
  { value: "m", label: "minutes" },
  { value: "h", label: "hours" },
]

function on(path: string) {
  return (values: Record<string, unknown>) => Boolean(getByPath(values, path))
}

export const LOCATIONS_CONNECTIONS_DEFAULTS: Record<string, unknown> = {
  loadOnStart: true,
  noFiltersNoLoad: false,
  autoRefetch: { on: false, value: 5, unit: "s" },
}

/** Objects query settings (markers / directory objects). */
export const locationsConnectionsSchema: SettingsFormSchema = {
  fields: [
    {
      type: "switch",
      path: "loadOnStart",
      label: "Load objects on start",
      help: "If off, nothing loads until a filter or search is used.",
    },
    {
      type: "switch",
      path: "noFiltersNoLoad",
      label: "Never load objects if no filters are chosen",
    },
    {
      type: "switch",
      path: "autoRefetch.on",
      label: "Auto-refetch",
      help: "Periodically reload objects on the front-end map only. Minimum interval is 5 seconds.",
    },
    {
      type: "number",
      path: "autoRefetch.value",
      label: "Interval",
      indent: true,
      integer: true,
      min: 1,
      visible: on("autoRefetch.on"),
    },
    {
      type: "select",
      path: "autoRefetch.unit",
      label: "Unit",
      indent: true,
      options: REFETCH_UNITS,
      visible: on("autoRefetch.on"),
    },
  ],
}
