import { ComponentController, type ComponentSchemaSection } from "@/components/ComponentController"
import { useEffect, useState } from "react"
import { FormBuilderCombobox } from "@/components/form-builder/FormBuilderCombobox"
import { SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { InputGroup, InputGroupAddon, InputGroupInput, InputGroupText } from "@/components/ui/input-group"
import { appEditingPageId } from "@/lib/app-state-editor"
import { patchLiveMapOptions, subscribeLiveMapOptions } from "@/lib/live-map-options"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { readNodes, readScenes, type MapSvgNode } from "@/lib/nodes-admin"
import type { SettingsField } from "@/lib/settings-form/types"
import { mobileToolbarPageNodes } from "../../../../mapsvg/Layout/MobileToolbarLayout"
import { PRESENTATION_MARGIN_SIDES } from "../../../../mapsvg/Components/MapPresentation"

/** Visual properties belong to the node, independently of responsive geometry. */
export function mapPresentationStyles(map: MapsvgMapInstance | null, node?: MapSvgNode): ComponentSchemaSection {
  const values = { ...node?.styles }
  return {
    schema: { fields: [
      { type: "custom", id: "presentation-margins", render: ctx => <SettingsControlField label="Margin (px)">
        <div className="grid min-w-0 grid-cols-2 gap-2" data-slot="presentation-margin-fields">
          {PRESENTATION_MARGIN_SIDES.map(side => {
            const path = `margin${side}`
            const value = ctx.getValue(path)
            return <InputGroup key={side}>
              <InputGroupAddon><InputGroupText>{side}</InputGroupText></InputGroupAddon>
              <InputGroupInput aria-label={`${side} margin (px)`} type="number" placeholder="0"
                value={typeof value === "number" && Number.isFinite(value) ? value : ""}
                onChange={event => ctx.setValue(path, event.target.value === "" ? undefined : Number(event.target.value))} />
            </InputGroup>
          })}
        </div>
      </SettingsControlField> },
      { type: "color", path: "backgroundColor", label: "Background" },
    ] },
    values,
    onChange: next => {
      if (!node) return
      const changed = Object.fromEntries(Object.entries(next).filter(([key, value]) => !Object.is(values[key], value)))
      if (!Object.keys(changed).length) return
      patchLiveMapOptions({ nodes: readNodes(map).map(current => current.id === node.id
        ? { ...current, styles: { ...current.styles, ...changed } } : current) })
    },
  }
}

/** Source selectors appear only for an ambiguity or a retained explicit binding. */
export function mapPresentationSourceField(map: MapsvgMapInstance | null): SettingsField {
  const maps = mobileToolbarPageNodes(readNodes(map), readScenes(map), appEditingPageId(map)).filter(node => node.type === "map")
  return { type: "custom", id: "map-source", render: ctx => {
    const selected = String(ctx.getValue("mapNodeId") || "")
    if (maps.length === 1 && !selected) return null
    return <SettingsControlField label="Source Map">
      <FormBuilderCombobox aria-label="Source Map" value={selected} emptyLabel="Auto" searchPlaceholder="Search maps..."
        options={[...maps.map(node => ({ value: node.id, label: node.title || node.id })),
          ...(selected && !maps.some(node => node.id === selected) ? [{ value: selected, label: `Unavailable · ${selected}`, disabled: true }] : [])]}
        onValueChange={value => ctx.setValue("mapNodeId", value)} />
    </SettingsControlField>
  } }
}

export function patchPresentationSettings(map: MapsvgMapInstance | null, nodeId: string, previous: Record<string, unknown>, next: Record<string, unknown>): void {
  const changed = Object.fromEntries(Object.entries(next).filter(([key, value]) => !Object.is(previous[key], value)))
  if (!Object.keys(changed).length) return
  patchLiveMapOptions({ nodes: readNodes(map).map(node => node.id === nodeId ? { ...node, settings: { ...node.settings, ...changed } } : node) })
}

export function MapLegendSettingsPanel({ map, node: selected }: { map: MapsvgMapInstance | null; node?: MapSvgNode }) {
  const [, setTick] = useState(0)
  useEffect(() => subscribeLiveMapOptions(() => setTick(tick => tick + 1)), [])
  const node = readNodes(map).find(node => selected ? node.id === selected.id : node.type === "legend")
  if (!node) return null
  const legacy = map?.options.regionDataRules as { on?: boolean; legend?: { on?: boolean; title?: string } } | undefined
  const values = {
    on: node.settings.on ?? legacy?.legend?.on ?? false,
    title: node.settings.title ?? legacy?.legend?.title ?? "",
    mapNodeId: node.settings.mapNodeId ?? "",
  }
  return <ComponentController settings={{
    retainEnable: true,
    schema: { fields: [
      { type: "alert", id: "legend-info", variant: "info", html: "Shows colors and scale from the Map’s Region Data rules. Move Legend to any Layout slot or Frame." },
      mapPresentationSourceField(map),
      { type: "switch", path: "on", label: "Enable" },
      { type: "text", path: "title", label: "Title" },
      ...(!legacy?.on ? [{ type: "alert" as const, id: "legend-no-rules", variant: "info" as const, html: "Enable Data rules in Map → Region to display the legend." }] : []),
    ] },
    values,
    onChange: next => patchPresentationSettings(map, node.id, values, next),
  }} styles={mapPresentationStyles(map, node)} />
}
