import { mergeRegisteredSettingsSchema } from "@/lib/settings-form/schemaMerge"
import {
  interactionsSettingsSchema,
} from "@/components/settings/interactionsSettingsSchema"
import { getByPath } from "@/lib/settings-form/path"
import type { SettingsFormSchema } from "@/lib/settings-form/types"

export type InteractionEventId = string

export type InteractionEventNavItem = {
  id: InteractionEventId
  /** Event name in the sidebar (click, mouseover, …). */
  label: string
  /** Options path prefix, e.g. `region.click`. */
  path: string
}

export type InteractionComponentNavGroup = {
  id: string
  label: string
  events: InteractionEventNavItem[]
}

/**
 * Interactions sidebar: Component → events (legacy Actions sections).
 * Labels match runtime event names where possible.
 */
export const INTERACTIONS_NAV: InteractionComponentNavGroup[] = [
  {
    id: "map",
    label: "Map",
    events: [
      { id: "map.afterLoad", label: "afterLoad", path: "map.afterLoad" },
    ],
  },
  {
    id: "region",
    label: "Region",
    events: [
      { id: "region.click", label: "click", path: "region.click" },
      { id: "region.mouseover", label: "mouseover", path: "region.mouseover" },
      { id: "region.touch", label: "touch", path: "region.touch" },
    ],
  },
  {
    id: "marker",
    label: "Marker",
    events: [
      { id: "marker.click", label: "click", path: "marker.click" },
      { id: "marker.mouseover", label: "mouseover", path: "marker.mouseover" },
      { id: "marker.touch", label: "touch", path: "marker.touch" },
    ],
  },
  {
    id: "directory",
    label: "Directory",
    events: [
      {
        id: "directoryItem.click",
        label: "click",
        path: "directoryItem.click",
      },
      {
        id: "directoryItem.hover",
        label: "hover",
        path: "directoryItem.hover",
      },
    ],
  },
]

export const DEFAULT_INTERACTION_EVENT_ID: InteractionEventId =
  INTERACTIONS_NAV[1]!.events[0]!.id

export function findInteractionEvent(
  eventId: InteractionEventId,
): {
  group: InteractionComponentNavGroup
  event: InteractionEventNavItem
} | null {
  for (const group of INTERACTIONS_NAV) {
    const event = group.events.find((e) => e.id === eventId)
    if (event) return { group, event }
  }
  return null
}

/** Count enabled (true) boolean actions under an event path. */
export function countEnabledInteractions(
  values: Record<string, unknown>,
  eventPath: string,
): number {
  return countTrueBooleans(getByPath(values, eventPath))
}

function countTrueBooleans(value: unknown): number {
  if (typeof value === "boolean") return value ? 1 : 0
  if (value == null || typeof value !== "object" || Array.isArray(value)) {
    return 0
  }
  let n = 0
  for (const child of Object.values(value as Record<string, unknown>)) {
    n += countTrueBooleans(child)
  }
  return n
}

/** Schema fields for one event (path prefix match; sections dropped). */
export function getSchemaForInteractionEvent(
  eventPath: string,
): SettingsFormSchema {
  const fields = mergeRegisteredSettingsSchema("interactions", interactionsSettingsSchema).fields.filter((field) => {
    if (field.type === "section") return false
    if (field.type === "custom") return field.id.startsWith(`${eventPath}.`)
    if (!("path" in field) || typeof field.path !== "string") return false
    return (
      field.path === eventPath || field.path.startsWith(`${eventPath}.`)
    )
  })
  return { fields }
}
