import { useEffect, useRef, useState } from "react"
import { GripVertical, Plus, RefreshCw, Trash2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Field, FieldContent, FieldLabel } from "@/components/ui/field"
import { Switch } from "@/components/ui/switch"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { DataRuleValue } from "../DataRuleValue"
import { ColorInput } from "@/components/settings-form/ColorInput"
import { FormBuilderChoice } from "@/components/form-builder/FormBuilderChoice"
import { patchLiveMapOptions, subscribeLiveMapOptions } from "@/lib/live-map-options"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { useDragSort } from "@/lib/use-drag-sort"
import { cn } from "@/lib/utils"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { filterSourceFields } from "../filter-fields/model"
import { loadPostFilterFields } from "../filter-fields/post-filter-fields"
import { readRegionDataRules, validateRegionDataRules, type RegionDataRules, type RegionRule, type RuleException } from "../../../../../mapsvg/Region/dataRules"
import { loadRuleFieldOptions } from "../../../../../mapsvg/Region/dataRuleDomain"

type Repo = { getSchema: () => { getFields: () => any[]; postType?: string }; getOptionsByField: (path: string) => Promise<Array<{ label: string; value: string | number }>> }
type Runtime = MapsvgMapInstance & { regionsRepository: Repo; objectsRepository: Repo }
const blankRow = (): RegionRule => ({ label: "", value: "", color: "", disabled: false, from: null, to: null })
const sourceOptions = [{ value: "regions", label: "Regions" }, { value: "objects", label: "Connected objects" }]
const priorityLabels = { filtered: "Filtered out", noObjects: "No linked objects", field: "Field value" }
const exceptionLabels = { noData: "No data", unmatched: "Unmatched / out of range", filtered: "Filtered out", noObjects: "No linked objects", multiple: "Multiple values" }
function read(map: Runtime) { return readRegionDataRules(map.options, map.regionsRepository?.getSchema().getFields().find(field => field.type === "status")?.options) }

export function RegionDataRulesEditor({ map }: { map: MapsvgMapInstance | null }) {
  if (!map) return null
  return <Editor key={map.id} map={map as Runtime} />
}
function Editor({ map }: { map: Runtime }) {
  const [rules, setRules] = useState(() => read(map))
  const rulesRef = useRef(rules)
  const published = useRef(JSON.stringify(rules))
  const [newRow, setNewRow] = useState(blankRow)
  const [error, setError] = useState("")
  const [loading, setLoading] = useState(false)
  const [manual, setManual] = useState(false)
  const [path, setPath] = useState(rules.field)
  const [catalog, setCatalog] = useState<Array<{ value: string; label: string }>>([])
  const request = useRef(0)
  const catalogRequest = useRef(0)
  const repo = rules.source === "objects" ? map.objectsRepository : map.regionsRepository
  useEffect(() => {
    const unsubscribe = subscribeLiveMapOptions(() => {
      const next = read(map), serialized = JSON.stringify(next)
      if (serialized !== published.current) {
        prioritySort.cancel()
        request.current++; published.current = serialized; rulesRef.current = next; setRules(next); setPath(next.field); setNewRow(blankRow()); setError(""); setLoading(false)
      }
    })
    return () => { unsubscribe(); request.current++; catalogRequest.current++ }
  }, [map])
  useEffect(() => {
    const run = ++catalogRequest.current
    const schema = repo?.getSchema(), fields = schema?.getFields() || []
    const source = rules.source
    const base = filterSourceFields(fields, source).map(option => ({ value: option.value.replace(/^Region\./, "region.").replace(/^Object\./, "object."), label: option.label }))
    setCatalog(base)
    void loadPostFilterFields(fields, source, schema?.postType).then(extra => {
      if (catalogRequest.current === run) setCatalog([...base, ...extra.map(option => ({ value: option.value.replace(/^Region\./, "region.").replace(/^Object\./, "object."), label: option.label }))])
    }).catch(() => { if (catalogRequest.current === run) setError("Could not load nested post fields. You can enter a field path or retry.") })
    return () => { catalogRequest.current++ }
  }, [map, repo, rules.source])

  const change = (next: RegionDataRules) => {
    request.current++; setLoading(false); rulesRef.current = next; setRules(next)
    const errors = validateRegionDataRules(next)
    setError(errors.join(" "))
    if (!errors.length && getAdminMapInstance() === map) {
      published.current = JSON.stringify(next)
      patchLiveMapOptions({ regionDataRules: next })
    }
  }
  const update = (patch: Partial<RegionDataRules>) => change({ ...rulesRef.current, ...patch })
  const movePriority = (from: RegionDataRules["priority"][number], to: RegionDataRules["priority"][number]) => {
    const priority = [...rulesRef.current.priority], start = priority.indexOf(from), end = priority.indexOf(to)
    if (start < 0 || end < 0 || start === end) return
    priority.splice(start, 1); priority.splice(end, 0, from)
    update({ priority })
  }
  const prioritySort = useDragSort(movePriority)
  const load = async (field = rulesRef.current.field, source = rulesRef.current.source, reset = false) => {
    const current = rulesRef.current
    if (reset) { change({ ...current, field, source, rows: [] }); setPath(field); setNewRow(blankRow()) }
    if (rulesRef.current.mode !== "values") return
    const owner = source === "objects" ? map.objectsRepository : map.regionsRepository
    const run = ++request.current
    setLoading(true); setError("")
    try {
      const values = await loadRuleFieldOptions(owner, field, () => request.current === run && getAdminMapInstance() === map)
      if (run !== request.current || getAdminMapInstance() !== map) return
      const latest = rulesRef.current
      if (latest.mode !== "values") return
      const existing = new Map(latest.rows.map(row => [String(row.value), row]))
      const seen = new Set<string>()
      const rows = (values || []).flatMap(option => {
        const value = String(option.value ?? "")
        if (!value || seen.has(value)) return []
        seen.add(value)
        return [{ ...blankRow(), ...existing.get(value), label: String(option.label ?? value), value }]
      })
      change({ ...latest, rows })
    } catch { if (run === request.current) setError("Could not load field values. Please retry.") }
    finally { if (run === request.current) setLoading(false) }
  }
  const patchRow = (index: number, patch: Partial<RegionRule>) => update({ rows: rules.rows.map((row, i) => i === index ? { ...row, ...patch } : row) })
  const paint = (key: keyof RegionDataRules["exceptions"], patch: Partial<RuleException>) => update({ exceptions: { ...rules.exceptions, [key]: { ...rules.exceptions[key], ...patch } } })
  const rowCells = (row: RegionRule, patch: (value: Partial<RegionRule>) => void, prefix: string) => <>
    {rules.mode === "values" ? <TableCell><DataRuleValue label={row.label} value={row.value} /></TableCell> : <>
      <TableCell><Input aria-label={`${prefix} label`} value={row.label} onChange={e => patch({ label: e.target.value })} /></TableCell>
      <TableCell><Input aria-label={`${prefix} from`} type="number" placeholder="−∞" value={row.from ?? ""} onChange={e => patch({ from: e.target.value === "" ? null : Number(e.target.value) })} /></TableCell>
      <TableCell><Input aria-label={`${prefix} to`} type="number" placeholder="∞" value={row.to ?? ""} onChange={e => patch({ to: e.target.value === "" ? null : Number(e.target.value) })} /></TableCell>
    </>}
    <TableCell><ColorInput compact id={`${prefix}-color`} label={prefix} value={row.color} onChange={color => patch({ color })} /></TableCell>
    <TableCell><Checkbox aria-label={`${prefix} disabled`} checked={!!row.disabled} onCheckedChange={disabled => patch({ disabled: disabled === true })} /></TableCell>
  </>
  return <div className="grid min-w-0 gap-4" data-slot="region-data-rules">
    <Field orientation="horizontal"><FieldLabel>Enable</FieldLabel><Switch aria-label="Enable Data rules" checked={rules.on} onCheckedChange={on => update({ on })} /></Field>
    <Field><FieldContent><FieldLabel>Source</FieldLabel><FormBuilderChoice aria-label="Rules source" value={rules.source} options={sourceOptions} onValueChange={source => void load(source === "regions" ? "region.status" : "object.status", source as RegionDataRules["source"], true)} /></FieldContent></Field>
    <Field><FieldContent><FieldLabel>Field</FieldLabel><FormBuilderChoice aria-label="Rules field" value={rules.field} options={catalog} onValueChange={field => void load(field, rules.source, true)} />
      <Button type="button" size="xs" variant="ghost" className="justify-start" onClick={() => setManual(!manual)}>Enter field path</Button>
      {manual ? <Input aria-label="Custom field path" value={path} placeholder="region.post.meta.myField" onChange={e => setPath(e.target.value)} onBlur={() => { if (path !== rules.field) void load(path, rules.source, true) }} onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); e.currentTarget.blur() } }} /> : null}
    </FieldContent></Field>
    <Field><FieldContent><FieldLabel>Mode</FieldLabel><FormBuilderChoice aria-label="Rules mode" value={rules.mode} options={[{ value: "values", label: "Values" }, { value: "ranges", label: "Ranges" }, { value: "gradient", label: "Gradient" }]} onValueChange={mode => { update({ mode: mode as RegionDataRules["mode"], rows: [] }); setNewRow(blankRow()); if (mode === "values") void load() }} /></FieldContent></Field>
    {rules.mode === "gradient" ? <div className="grid grid-cols-2 gap-3">
      {(["min", "max"] as const).map(key => <Field key={key}><FieldContent><FieldLabel>{key === "min" ? "Minimum" : "Maximum"}</FieldLabel><Input aria-label={`Gradient ${key}`} type="number" placeholder="Auto" value={rules.gradient[key] ?? ""} onChange={e => update({ gradient: { ...rules.gradient, [key]: e.target.value === "" ? null : Number(e.target.value) } })} /></FieldContent></Field>)}
      {(["low", "high"] as const).map(key => <ColorInput key={key} id={`gradient-${key}`} label={`Gradient ${key}`} value={rules.gradient[key]} onChange={color => update({ gradient: { ...rules.gradient, [key]: color } })} />)}
    </div> : <>
      {rules.mode === "values" ? <Button type="button" size="xs" variant="outline" disabled={loading} onClick={() => void load()}><RefreshCw className="size-3" />{loading ? "Loading values…" : "Load available values"}</Button> : <p className="text-xs text-muted-foreground">From is inclusive; To is exclusive. Leave a boundary empty for an open range.</p>}
      <Table aria-label="Region appearance rules" className={`table-fixed [&_td]:px-1 [&_th]:px-1 [&_th]:text-xs [&_input]:px-1.5 ${rules.mode === "values" ? "min-w-[240px]" : "min-w-[360px]"}`}><colgroup><col />{rules.mode === "ranges" ? <><col /><col /></> : null}<col className="w-12" /><col className="w-14" /><col className="w-9" /></colgroup><TableHeader><TableRow className="hover:bg-transparent has-aria-expanded:bg-transparent">{rules.mode === "values" ? <TableHead>Label – value</TableHead> : <><TableHead>Label</TableHead><TableHead>From</TableHead><TableHead>To</TableHead></>}<TableHead>Color</TableHead><TableHead>Disable</TableHead><TableHead /></TableRow></TableHeader><TableBody>
        {rules.rows.map((row, index) => <TableRow className="hover:bg-transparent has-aria-expanded:bg-transparent" key={index}>{rowCells(row, patch => patchRow(index, patch), `Rule ${index + 1}`)}<TableCell><Button type="button" size="icon" variant="outline" aria-label={`Delete rule ${index + 1}`} onClick={() => update({ rows: rules.rows.filter((_, i) => i !== index) })}><Trash2 /></Button></TableCell></TableRow>)}
        {rules.mode === "ranges" ? <TableRow className="hover:bg-transparent has-aria-expanded:bg-transparent">{rowCells(newRow, patch => setNewRow({ ...newRow, ...patch }), "New rule")}<TableCell><Button type="button" size="icon-xs" variant="outline" aria-label="Add rule" onClick={() => { const next = { ...rules, rows: [...rules.rows, { ...newRow, label: newRow.label || newRow.value }] }; const errors = validateRegionDataRules(next); if (errors.length) setError(errors.join(" ")); else { change(next); setNewRow(blankRow()) } }}><Plus /></Button></TableCell></TableRow> : null}
      </TableBody></Table>
    </>}
    {error ? <p role="alert" className="text-xs text-destructive">{error}</p> : null}
    <Field><FieldContent><FieldLabel>Multiple values</FieldLabel><FormBuilderChoice aria-label="Multiple values" value={rules.multiple} options={[{ value: "first", label: rules.mode === "gradient" ? "First numeric value" : "First matching row" }, { value: "special", label: "Use special appearance" }]} onValueChange={multiple => update({ multiple: multiple as RegionDataRules["multiple"] })} /></FieldContent></Field>
    <div className="grid gap-3 border-t pt-3"><h4 className="text-xs font-medium">Exceptions</h4>
      {(Object.keys(exceptionLabels) as Array<keyof typeof exceptionLabels>).filter(key => key !== "multiple" || rules.multiple === "special").map(key => <div key={key} className="grid gap-2">
        <Field orientation="horizontal"><FieldLabel>{exceptionLabels[key]}</FieldLabel><Switch aria-label={`Override ${exceptionLabels[key]}`} checked={rules.exceptions[key].on} onCheckedChange={on => paint(key, { on })} /></Field>
        {rules.exceptions[key].on ? <div className="grid grid-cols-2 gap-2"><ColorInput id={`exception-${key}`} label={exceptionLabels[key]} value={rules.exceptions[key].color} onChange={color => paint(key, { color })} /><FormBuilderChoice aria-label={`${exceptionLabels[key]} interaction`} value={rules.exceptions[key].disabled === undefined ? "inherit" : rules.exceptions[key].disabled ? "disabled" : "enabled"} options={[{ value: "inherit", label: "Default interaction" }, { value: "enabled", label: "Enabled" }, { value: "disabled", label: "Disabled" }]} onValueChange={value => paint(key, { disabled: value === "inherit" ? undefined : value === "disabled" })} /></div> : null}
      </div>)}
    </div>
    <div className="grid gap-2 border-t pt-3">
      <h4 className="text-xs font-medium">Priority · first matching rule wins</h4>
      <div role="list" aria-label="Rule priority" className="grid gap-1">
        {rules.priority.map((key, index) => <div key={key} role="listitem" {...prioritySort.itemProps(key)} className={cn("flex cursor-grab items-center gap-2 rounded-md px-1 py-1 transition-colors hover:bg-accent active:cursor-grabbing", prioritySort.dragged === key && "opacity-40", prioritySort.target === key && prioritySort.dragged !== key && "bg-accent")}>
          <span role="img" tabIndex={0} className="flex size-6 shrink-0 cursor-grab items-center justify-center text-muted-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing" aria-label={`Reorder ${priorityLabels[key]}`} onKeyDown={event => {
            if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return
            event.preventDefault()
            const target = rules.priority[index + (event.key === "ArrowUp" ? -1 : 1)]
            if (target) movePriority(key, target)
          }}><GripVertical aria-hidden="true" className="size-3.5" /></span>
          <span className="flex-1 text-xs">{priorityLabels[key]}</span>
        </div>)}
      </div>
    </div>
    <p className="text-xs text-muted-foreground">Configure the Legend component to display these colors and scale.</p>
  </div>
}
