import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { getAdminParams } from "@/lib/admin-params"
import { resourceApiUrl } from "@/lib/resource-api-url"
import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import type { filterSourceFields } from "./model"

/** The same post metadata/taxonomy catalog used by the retained filter constructor. */
export async function loadPostFilterFields(
  fields: FormFieldData[],
  source: "objects" | "regions",
  postType?: string,
): Promise<ReturnType<typeof filterSourceFields>> {
  const params = getAdminParams()
  const prefix = source === "regions" ? "Region" : "Object"
  const groups = await Promise.all(
    fields
      .filter((field) => field.type === "post" && (field.post_type || postType))
      .map(async (field) => {
        const type = String(field.post_type || postType)
        const response = await adminRestFetch(
          resourceApiUrl(params.apiUrl, `/post-types/${encodeURIComponent(type)}`),
          {
            credentials: "same-origin",
            headers: { Accept: "application/json", "X-WP-Nonce": params.nonce },
          },
        )
        if (!response.ok) throw new Error("Could not load post filter fields")
        const data = (await response.json()) as {
          meta?: Array<{ name: string }>
          taxonomy?: Array<{ name: string }>
        }
        const names = [
          ...(data.meta ?? [])
            .filter(({ name }) => !["mapsvg_location", "footnotes"].includes(name))
            .map(({ name }) => `post.meta.${name}`),
          ...(data.taxonomy ?? []).map(({ name }) => `post.taxonomy.${name}`),
        ]
        return names.map((name) => ({
          value: `${prefix}.${name}`,
          label: `${prefix}.${name}`,
          field,
        }))
      }),
  )
  return groups.flat()
}
